INSERT INTO `activity` (`ID`, `Name`, `Time`, `Place`, `Introduction`, `Status`) VALUES
	(1, '经典共读计划', '每周六 14:00-16:00', '一楼A区', '共读经典名著，交流读书心得，分享感悟与思考。活动旨在带领大家深度品读文学经典，在交流中碰撞思想，共同提升阅读深度与人文素养，感受经典作品的长久魅力。', '进行中'),
	(2, '读书分享会', '每月最后一周周日 14:00-16:00', '二楼A区', '邀请广大读者分享近期阅读的书籍与个人感悟，讲述书中故事、人物与收获。通过轻松自由的交流，营造良好阅读氛围，让更多人爱上阅读、学会阅读、享受阅读。', '进行中'),
	(3, '亲子阅读活动', '每周日 19:00-20:30', '二楼B区', '面向家长与孩子开展温馨共读活动，通过趣味故事、互动阅读，培养孩子良好阅读习惯，增进亲子情感交流。在书香陪伴中度过美好时光，让阅读成为家庭共同的爱好。', '进行中'),
	(4, '作家签售会', '2026年4月1日 13:30-16:30', '一楼B区', '本次特邀知名作家亲临现场，与读者面对面交流创作心得，分享作品背后的故事。活动现场可携带书籍参与签名留念，近距离感受文字的力量，共赴一场书香盛宴。', '进行中'),
	(5, '新书宣传会', '2026年6月1日 13:30-14:30', '一楼A区', '聚焦最新出版的优质图书，为读者推荐近期上架的热门新书、经典再版与口碑佳作。活动将帮助读者快速了解前沿阅读趋势，发掘值得一读的好书，让每一位读者都能找到心仪的新书，开启全新阅读之旅。', '未开始');
INSERT INTO `administrator` (`ID`, `UserName`, `Password`) VALUES
	(1, '111', '111');
INSERT INTO `book` (`ID`, `Cover`, `Name`, `Name_EN`, `Author`, `Nationality`, `Publication_Date`, `Type`, `Introduction`, `Place`, `Lend_Status`, `Lend_ID`, `Lend_Time`, `Return_Time`) VALUES
	(1, 'Fortress Besieged.jpg', '围城', 'Fortress Besieged', '钱锺书', '中国', '1991-2-1', '小说', '《围城》是一幅栩栩如生的世井百态图，人生的酸甜苦辣千般滋味均在其中得到了淋漓尽致的体现。钱钟书先生将自己的语言天才并入极其渊博的知识，再添加上一些讽刺主义的幽默调料，以一书而定江山。《围城》显示给我们一个真正的聪明人是怎样看人生，又怎样用所有作家都必得使用的文字来表述自己的“观”和“感”的。', '1楼A区', 'Lend', '1', '2026-05-11', '2026-05-11'),
	(2, 'The Litchi Road.jpg', '长安的荔枝', 'The Litchi Road', '马伯庸', '中国', '2022-10', '小说', '大唐天宝十四年，长安城的小吏李善德突然接到一个任务：要在贵妃诞日之前，从岭南运来新鲜荔枝。荔枝“一日色变，两日香变，三日味变”，而岭南距长安五千余里，山水迢迢，这是个不可能完成的任务，可为了家人，李善德决心放手一搏：“就算失败，我也想知道，自己倒在距离终点多远的地方。”《长安的荔枝》是马伯庸备受好评的历史小说。', '1楼A区', 'Save', NULL, NULL, NULL),
	(3, 'To Live.jpg', '活着', 'To Live', '余华', '中国', '2012-8', '小说', '《活着(新版)》讲述了农村人福贵悲惨的人生遭遇。福贵本是个阔少爷，可他嗜赌如命，终于赌光了家业，一贫如洗。他的父亲被他活活气死，母亲则在穷困中患了重病，福贵前去求药，却在途中被国民党抓去当壮丁。经过几番波折回到家里，才知道母亲早已去世，妻子家珍含辛茹苦地养大两个儿女。此后更加悲惨的命运一次又一次降临到福贵身上，他的妻子、儿女和孙子相继死去，最后只剩福贵和一头老牛相依为命，但老人依旧活着，仿佛比往日更加洒脱与坚强。', '1楼A区', 'Save', NULL, NULL, NULL),
	(4, 'The Vegetarian.jpg', '素食者', 'The Vegetarian', '韩江', '韩国', '2021-9', '小说', '亚洲首位国际布克文学奖得主获奖作品。我在写作时，经常会思考这些问题：人类的暴力能达到什么程度；如何界定理智和疯狂；我们能在多大程度上理解别人。我希望《素食者》可以回答我的这些问题。我想通过《素食者》刻画一个誓死不愿加入人类群体的女性。——韩江在国家布克文学奖颁奖礼上的致辞', '1楼A区', 'Save', NULL, NULL, NULL),
	(5, 'East of Eden.jpg', '伊甸之东', 'East of Eden', '约翰·斯坦贝克', '美国', '2024-5', '小说', '《伊甸之东》是斯坦贝克文学生命的巅峰之作，也是美国经久不衰的经典畅销书，自出版以来，已被上千万读者阅读，在美国文化史占有重要的地位。本版首次收录作者两万字创作手记。小说以加利福尼亚州萨利纳斯河谷为背景，以象征和写实交融的手法，讲述了两个家族从南北战争到“一战”时期长达半个世纪的故事。在这里，斯坦贝克塑造了他最为迷人的人物形象，探讨了他最为永恒的主题：身份之谜、爱的盲目，以及爱的缺失所带来的凶残后果。', '1楼A区', 'Save', NULL, NULL, NULL),
	(6, 'The Dream of Red Chamber.jpg', '红楼梦', 'The Dream of Red Chamber', '曹雪芹', '清朝', '1996-12', '经典', '《红楼梦》是一部百科全书式的长篇小说。以宝黛爱情悲剧为主线，以四大家族的荣辱兴衰为背景，描绘出18世纪中国封建社会的方方面面，以及封建专制下新兴资本主义民主思想的萌动。结构宏大、情节委婉、细节精致，人物形象栩栩如生，声口毕现，堪称中国古代小说中的经典。', '1楼A区', 'Save', NULL, NULL, NULL),
	(7, 'Journey to the West.jpg', '西游记', 'Journey to the West', '吴承恩', '明朝', '2004-8', '经典', '《西游记》主要描写的是孙悟空保唐僧西天取经，历经九九八十一难的故事。唐僧取经是历史上一件真实的事。大约距今一千三百多年前，即唐太宗贞观元年（627），年仅25岁的青年和尚玄奘离开京城长安，只身到天竺（印度）游学。他从长安出发后，途经中亚、阿富汗、巴基斯坦，历尽艰难险阻，最后到达了印度。他在那里学习了两年多，并在一次大型佛教经学辩论会任主讲，受到了赞誉。贞观十九年（645）玄奘回到了长安，带回佛经657部。他这次西天取经，前后十九年，行程几万里，是一次传奇式的万里长征，轰动一时。', '1楼A区', 'Lend', '11', '2026-05-07', '2026-05-10'),
	(8, 'To Kill a Mocking Bird.jpg', '杀死一只知更鸟', 'To Kill a Mocking Bird', '哈珀·李', '美国', '2017-2', '经典', '《杀死一只知更鸟》是公认的美国文学经典，而它在教育领域的意义却使其突破了国界，成为世界上最有名的成长小说之一。《杀死一只知更鸟》在西方世界的影响力巨大，是美国中小学的必读书目，图书馆借阅次数最高的图书，以及英国青少年最喜爱的图书，在最近一次民意投票中，它甚至压倒《圣经》，成为“最具启示意义的书”。', '1楼A区', 'Save', NULL, NULL, NULL),
	(9, 'War and Peace.jpg', '战争与和平', 'War and Peace', '托尔斯泰', '俄国', '2015-4', '经典', '《战争与和平》(1866—1869)描写1812年俄法战争的全过程，以当时四大贵族家庭的人物活动为线索，反映了1805至1820年间许多重大的历史事件，以及各阶层的现实生活，抨击了那些谈吐优雅，但漠视祖国命运的贵族，歌颂了青年一代在战争中表现出来的爱国主义和英雄主义精神，是一部史诗般的鸿篇巨制。', '1楼A区', 'Save', NULL, NULL, NULL),
	(10, 'The Metamorphosis.jpg', '变形记', 'The Metamorphosis', '弗朗茨·卡夫卡', '奥地利', '2020-1-1', '经典', '"本书属于《设计师联名书系·K经典》全6册的其中一本。《变形记》是卡夫卡著名的中篇小说，完成于1912年，1915年出版面市。小说主人公格雷戈尔是一家公司的旅行业务员，他也是整个家庭的经济支柱。一天清晨醒来时，格雷戈尔变成了甲虫，自此他不仅丧失了生活和工作能力，还被视为家庭的负担和丑闻。父母、妹妹对他的态度骤然反转，由尊敬到嫌恶，露出一张张冷漠的嘴脸。最后，格雷戈尔在饥饿中孤独死去。"', '1楼A区', 'Save', NULL, NULL, NULL),
	(11, 'The corner of altay.jpg', '阿勒泰的角落', 'The corner of altay', '李娟', '中国', '2024-1-9', '随笔', '十九岁，她随家人初入阿尔泰深山牧场，在荒野中经营起半流动的裁缝店和杂货铺。牧民自古逐水草而居，为了生活，她与家人也不断随之迁徙——从草场到沙漠、戈壁，甚至是凋敝的废墟。踏入新的土地，空空荡荡，而自然丰泽。人有手有脚、感官明晰，就是自由。什么都可以从无到有，一点点被创造出来。这样的土地容不下虚伪和矫情，一切都那么直接、真实——世界是未驯服的，感观是纯·天然的。哪怕生活永远在一边抛弃，一边继续，只要感受力还在，永远可以发现新的、值得记忆的美好。', '1楼A区', 'Save', NULL, NULL, NULL),
	(12, 'Two people on a lonely island.jpg', '孤岛上的两人', 'Two people on a lonely island', '山本文绪', '日本', '2025-7', '随笔', '作家山本文绪生前最后一本日记，记录她生命的最后几个月。“告别的话，说了也说不完……”这是一本突然去世的作家的战斗日记。“请允许我把写这个作为告别……”就像被意想不到的大浪卷走，和丈夫两个人一起被冲到了无人岛上一样，有一天她突然被诊断出患有癌症，两人开始了在“新冠疫情”冲击下的家中与病魔斗争的生活。58岁被宣布时日无多，但仍没有放弃写作的作家，直到临终仍在写日记。', '1楼A区', 'Save', NULL, NULL, NULL),
	(13, 'Write about father.jpg', '写父亲', 'Write about father', '宁不远', '中国', '2025-6', '随笔', '这是一个女儿对父亲和乡土的怀念，也是一份坦诚的自我剖白。父亲的一生沉默又勤恳，他努力让女儿踏上求学之路，远离乡下，前往更好的世界。但远离“粗俗的人情味”，生活是否变得更有意义？一个独自从农村走到大都市的女孩要经历多少挣扎和蜕变，才能完成对自我的重塑？父亲是一种语言，一个来处，一方土壤，一份参照；女儿书写父亲既是清空，也是填满；既是为了告别，也是为了重新开始。', '1楼A区', 'Save', NULL, NULL, NULL),
	(14, 'Not Blown Down by the Wind.jpg', '不被大风吹倒', 'Not Blown Down by the Wind', '莫言', '中国', '2024-10', '随笔', '本书为莫言散文精选集，除了从莫言以往的作品中选取了莫言的人生经历、写作经验和人生感悟相关的篇目，还加入了莫言全新创作的写给年轻人的内容。通过莫对自己人生经历的讲述，给现在的年轻人一些启发和鼓舞。全书共分为六草，内容分别莫言如何走上写作之路-一为什么叫莫言?与家人的关系:莫言对待生活的态度--如何面对生活中的疲惫与困难;莫言的童年有哪些有趣的童年经历?童年经历对他的成长和写作有什么影响;与朋友的关系--都交了哪些朋友;阅读的意义--阅读对莫言的影响:莫言的写作技巧-哪些东西成为他写作的源泉。', '1楼A区', 'Save', NULL, NULL, NULL),
	(15, 'And then there was light.jpg', '于是有了光', 'And then there was light', '王东杰', '中国', '2025-10', '随笔', '本书是清华大学历史系教授王东杰所著的学术随笔集。全书分为四辑，收录文章四十余篇。第一辑聚焦社会文化评论，探讨了知识分子的角色定位、世界视野的拓展、传统观念的转型以及数字时代带来的挑战等议题；第二辑以书评为主，呈现了作者对近代中国若干文化、思想议题的简要评说；第三辑和第四辑则收录了与读书、治学方法有关的杂文。该书内容丰富广泛，以跨领域的观察视角，从传统观念转型、数字时代挑战、读书治学方法等多个维度，对社会现实生活中的热点问题展开多元探讨，既有学术深度，又关照现实生活，可从中窥见多层次的人文情怀。', '1楼A区', 'Save', NULL, NULL, NULL),
	(16, 'I and the Temple of Earth.jpg', '我与地坛', 'I and the Temple of Earth', '史铁生', '中国', '2011-1-1', '散文', '《我与地坛》收入《我与地坛》、《记忆与印象》等以记事为主的散文，配少量图片。《我与地坛》由中国当代著名作家史铁生著。是史铁生文学作品中，充满哲思又极为人性化的代表作之一。前两部分注重讲地坛和他与母亲的后悔，对于中学生来说，这是一篇令人反思的优秀文章。史铁生是当代中国最令人敬佩的作家之一。他的写作与他的生命完全同构在了一起，在自己的“写作之夜”，史铁生用残缺的身体，说出了最为健全而丰满的思想。他体验到的是生命的苦难，表达出的却是存在的明朗和欢乐，他睿智的言辞，照亮的反而是我们日益幽暗的内心。', '1楼A区', 'Save', NULL, NULL, NULL),
	(17, 'Dawn Blossoms Plucked at Dusk.jpg', '朝花夕拾', 'Dawn Blossoms Plucked at Dusk', '鲁迅', '中国', '1973-4', '散文', '本书收作者1926年所作回忆散文十篇。1928年9月由北平未名社初版，列为作者所编的《未名新集》之一。1932年8月改由上海北新书局出版。作者生前共印行七版次。', '1楼A区', 'Save', NULL, NULL, NULL),
	(18, 'Wild Grass.jpg', '野草', 'Wild Grass', '鲁迅', '中国', '1973-3', '散文', '本书所收散文诗23篇〔包括一首打油诗和一出诗剧〕，最初都曾陆续发表于1924年12月至1926年1月的《语丝》周刊上，《题辞》最初也曾发表于1927年7月2日出版的《语丝》第138期，发表时署名均为鲁迅。本书于于年1927年4月由作者亲自编定，同年7月由上海北新书局初版印行列为作者所编的《乌合丛书》之一。此后印行的版本，除个别字和标点有所不同外，各篇文字大都和初版相同。《题辞》在本书最初的几次印刷都曾印入；后来被国民党政府书报检查机关抽去〔鲁迅在1935年11月23日致邱遇信和1936年2月19日致夏传经信中，均提及此事〕，至1941年上海鲁迅全集出版社出版《鲁迅三十年集》时才重新收入。《野草》的封面画系孙福熙所作，初版封面题字署“鲁迅先生”，后按鲁迅意思改为“鲁迅著”，鲁迅在1927年12月9日夜致章廷谦信中曾提及此事。', '1楼A区', 'Save', NULL, NULL, NULL),
	(19, 'Tree.jpg', '树', 'Tree', '幸田文', '日本', '2025-6', '散文', '从北海道到鹿儿岛，从儿时对姐姐的嫉妒，到成年后对女儿的遗憾，本书记录了幸田文在13年间与树木的15次“ 交流”。她以一双极具洞察力的眼睛凝视着树的来路和 归处，在这些回忆和感受中，探寻生命的意义。倒木更新的鱼鳞云杉、沉默的巨杉、改变容貌的扁柏……它们在经历了生命的洗礼之后依然美丽，它们开始诉说那些隐藏的情感……', '1楼A区', 'Save', NULL, NULL, NULL),
	(20, 'Look at Those Lights, Darling.jpg', '看那些灯光，亲爱的', 'Look at Those Lights, Darling', '安妮·埃尔诺', '法国', '2023-11', '散文', '安妮·埃尔诺一直在突破哪些故事值得讲述、哪些主题值得探讨的约定俗成的界限。在这本书中，她将目光投向了大卖场和超市。这是现代生活中无处不在的一个特征，但文学作品却鲜有关注。埃尔诺用一年多的时间记录了她对位于巴黎郊区的大型连锁超市欧尚的访问。在她看来，超市是“一个巨大的人类聚会的场所，一个真正的人文景观”。资本生产、文化生产和阶级分层在这里汇聚，并支配着我们的欲望。埃尔诺用她无情的犀利观察，打量着这个我们自以为熟悉的场所，号召探寻那些被我们忽略的日常，更深入地凝视平凡的生活。', '1楼A区', 'Save', NULL, NULL, NULL),
	(21, 'Nine Poetic Hearts.jpg', '九诗心', 'Nine Poetic Hearts', '黄晓丹', '中国', '2024-11', '诗歌', '古诗，有可能回应当下的时代变局、生活处境吗？或许这本书提供了一种答案。这本书写于疫情期间，作者没有选择那些更加耳熟能详的诗人，而是诚实地从自己的生命困惑和时代困惑出发，选择了能够回应这些问题的诗人（屈原、李陵、曹丕、陶渊明、杜甫、欧阳修、李清照、文天祥、吴梅村）。他们都身处时代变动的阵痛中，都面临一个命题：当昔日安稳世界的许诺失效，人究竟应以怎样的方式度过这一生？在他们笔下，我们看见人如何在大的时代纷乱中，转化生命的痛苦，获得个体的从容；在看不到希望的前提下，他们如何感受到幸福；对于人生的根本处境，人可以作出怎样的回答。作者黄晓丹以女性学者的细腻，挖掘诗人不为人知的一面；以诗性文笔做文本细读，带读者跨越古语障碍；以扎实的文献校勘和文史互证，再现诗人心灵与现实冲突的历史现场，成就这部中国的《人类群星闪耀时》。', '1楼C区', 'Save', NULL, NULL, NULL),
	(22, 'Things You May Find Hidden in My Ear.jpg', '玫瑰朝上', 'Things You May Find Hidden in My Ear', '莫萨布·阿布·托哈', '巴勒斯坦', '2025-5', '诗歌', '“别吃惊，当你看见 一朵玫瑰在家宅的废墟中 昂首挺立： 这就是我们活下来的方式。” 本诗集直接源于诗人成长和生活在长期封锁中的加沙，且经常被袭击的的经历。作为曾经的孩子、现在的父亲，以及多次军事袭击的幸存者，他见证了破坏和毁灭的残酷循环。但除了炮弹与无人机，这里也有茶香、盛开的玫瑰和日落时的海景。孩子们出生了，家庭延续着传统，学生上了大学，图书馆从废墟中崛起……巴勒斯坦人继续他们的生活，创造美丽，寻找新的生存方式。诗人在本书开头以《巴勒斯坦词典》速写了巴勒斯坦的民众生活，展现了巴勒斯坦人民的集体记忆，并在《作者访谈》中讨论了诗人自己在加沙的经历、他的家庭起源以及他如何走上了诗歌创作的道路。与作者年纪相仿的青年诗人、译者李琬为本书倾情写作了译后记，更充分地介绍和阐释了本书的意义。', '1楼C区', 'Save', NULL, NULL, NULL),
	(23, 'Under the Golden Branches and Stars of Night.jpg', '在夜的金枝与星辰下', 'Under the Golden Branches and Stars of Night', '格奥尔格·特拉克尔', '奥地利', '2026-1', '诗歌', '从萨尔茨堡山间幽暗的牧歌 到第一次世界大战的前线 “我不理解特拉克尔的诗，可是其语调令我欢喜。 那种语调属于一位真正的天才。” ——维特根斯坦 格奥尔格·特拉克尔是德语表现主义诗歌最杰出的代表之一，他的作品超逸于时代，深远地影响后世诗人。特拉克尔以语言速写了至第一次世界大战为止的奥地利帝国。强力的意象和旋律节奏化的语言贯彻了其诗的核心主题：死亡、衰败和西方的毁灭，以及对灵性的追寻。他梦想一种全新的人类，以及向着无罪天国的复归。这些疲惫而梦幻的蓝色篇章捎带着萨尔茨堡的山地气息。本书按照主题和时间顺序分为十三辑，是一本既忠于德文原文，又具备当代风格的新译之作。', '1楼C区', 'Save', NULL, NULL, NULL),
	(24, 'All of Us.jpg', '我们所有人', 'All of Us', '雷蒙德·卡佛', '美国', '2025-12', '诗歌', '《我们所有人》完整收录雷蒙德·卡佛一生创作的300余首诗歌，涵盖卡佛生前出版过的四本诗集《火》《水流交汇的地方》《海青色》《通往瀑布的新路》及身后出版的“未辑之诗”《别逞英雄，拜托》中的所有诗作，此外还有美国诗人、卡佛第二任妻子苔丝·加拉格尔为其所作的一篇动人序言。在这些质朴、坚韧且颇具自传性的诗行间，生命、记忆、爱情、家庭、疾痛与死亡等主题交错出现，卡佛的“整整一生，曲折多变，就在眼前”。而“我们所有人”，都将在其中，发现一条生活的“新路”。尽管雷蒙德·卡佛以短篇小说家身份赢得他最大的声誉，但他却是以诗人身份开始其写作生涯，并一直坚持诗歌创作直至1988年去世。随着这本丰富得令人吃惊的诗集的出版，卡佛一生的文学成就终于得以完整清晰地展示。诗全集《我们所有人》中的300余首诗歌具有卡佛小说的所有美德：对于物质世界的深切关注；将广阔情感压缩在朴素瞬间的非凡能力；谈话式的亲切的诗歌声音；以及对于“我们所有人，所有人，所有人/ 都想要拯救/ 我们不朽的灵魂”的慷慨的共鸣。——Vintage Books', '1楼C区', 'Save', NULL, NULL, NULL),
	(25, 'Faust.jpg', '浮士德', 'Faust', '歌德', '德国', '2013-6', '诗歌', '《浮士德》是歌德的代表作，它根据十六世纪一民间传说创作而成，为诗体悲剧，是作者倾注了毕生心血的鸿篇巨制。它描写主人公浮士德一生探求真理的痛苦经历，反映从文艺复兴到十九世纪初整个欧洲的历史，揭示了光明与黑暗，进步与落后，科学与迷信两种势力的不断斗争。歌德借助浮士德的抱负和追求，表达了他本人对人类未来的远大而美好的理想。全书由一系列叙事诗、抒情诗、戏剧、歌剧以及舞剧组成，涉及神学、神话学、哲学、科学、美学、文学、音乐以及政治经济学等。同样，《浮士德》与《荷马史诗》、《神曲》、《哈姆雷特》并列，同为欧洲的四大名著。', '1楼C区', 'Save', NULL, NULL, NULL),
	(26, 'The Little Prince.jpg', '小王子', 'The Little Prince', '安东尼·德·圣-埃克苏佩里', '法国', '2003-8', '童话', '小王子是一个超凡脱俗的仙童，他住在一颗只比他大一丁点儿的小行星上。陪伴他的是一朵他非常喜爱的小玫瑰花。但玫瑰花的虚荣心伤害了小王子对她的感情。小王子告别小行星，开始了遨游太空的旅行。他先后访问了六个行星，各种见闻使他陷入忧伤，他感到大人们荒唐可笑、太不正常。只有在其中一个点灯人的星球上，小王子才找到一个可以作为朋友的人。但点灯人的天地又十分狭小，除了点灯人他自己，不能容下第二个人。在地理学家的指点下，孤单的小王子来到人类居住的地球。小王子发现人类缺乏想象力，只知像鹦鹉那样重复别人讲过的话。小王子这时越来越思念自己星球上的那枝小玫瑰。后来，小王子遇到一只小狐狸，小王子用耐心征服了小狐狸，与它结成了亲密的朋友。小狐狸把自己心中的秘密——肉眼看不见事务的本质，只有用心灵才能洞察一切——作为礼物，送给小王子。用这个秘密，小王子在撒哈拉大沙漠与遇险的飞行员一起找到了生命的泉水。最后，小王子在蛇的帮助下离开地球，重新回到他的B612号小行星上。', '1楼C区', 'Save', NULL, NULL, NULL),
	(27, 'Andersen’s Fairy Tales.jpg', '安徒生童话故事集', 'Andersen’s Fairy Tales', '安徒生', '丹麦', '1997-08', '童话', '安徒生是丹麦19世纪著名童话作家，世界文学童话创始人。他生于欧登塞城一个贫苦鞋匠家庭，早年在慈善学校读过书，当过学徒工。受父亲和民间口头文学影响，他自幼酷爱文学。“为了争取未来的一代”，安徒生决定给孩子写童话，出版了《讲给孩子们听的故事》。此后数年，每年圣诞节都出版一本这样的童话集。其后又不断发表新作，直到1872年因患癌症才逐渐搁笔。近40年间，共计写了童话168篇。安徒生的创作可分早、中、晚三个时期。早期童话多充满绮丽的幻想、乐观的精神，体现现实主义和浪漫主义相结合的特点。代表作有《打火匣》、《小意达的花儿》、《拇指姑娘》、《海的女儿》、《野天鹅》、《丑小鸭》等。中期童话，幻想成分减弱，现实成分相对增强。在鞭挞丑恶、歌颂善良中，表现了对美好生活的执着追求，也流露了缺乏信心的忧郁情绪。代表作有《卖火柴的小女孩》、《白雪皇后》、《影子》、《一滴水》、《母亲的故事》、《演木偶戏的人》等。晚期童话比中期更加面对现实，着力描写底层民众的悲苦命运，揭露社会生活的阴冷、黑暗和人间的不平。作品基调低沉。代表作有《柳树下的梦》、《她是一个废物》、《单身汉的睡帽》、《幸运的贝儿》等。', '1楼C区', 'Save', NULL, NULL, NULL),
	(28, 'Alice\'s Adventures in Wonderland.jpg', '爱丽丝梦游仙境', 'Alice\'s Adventures in Wonderland', '刘易斯·卡罗尔', '英国', '2017-8', '童话', '一位可爱的英国小女孩爱丽丝在百般无聊之际，发现了一只揣着怀表、会说话的白兔。她追赶着它而不慎掉进了一个兔子洞，由此坠入了神奇的地下世界。在探险的同时不断认识自我，不断成长，在终于成长为一个“大”姑娘的时候，她猛然惊醒，才发现原来这一切都是自己的一个梦境。', '1楼C区', 'Save', NULL, NULL, NULL),
	(29, 'The Wonderful Wizard of Oz.jpg', '绿野仙踪', 'The Wonderful Wizard of Oz', '莱曼·弗兰克·鲍姆', '美国', '2016-10-1', '童话', '本书是“美国童话之父”的代表作，世界儿童文学难以逾越的经典，讲述了小姑娘多萝西被一阵突然而至的龙卷风吹到了一个叫做奥兹国的神秘国度，然后开始重返家乡的漫长旅途的故事。旅途中她先后遇到了四个小伙伴，和多萝西一样，他们也有各自的愿望想要达成。小伙伴们一起经历种种神奇的幻境和曲折的探险，最终却发现，他们想要的东西，其实一直都在自己的身边。这既是一部纯真美好的童话作品，也折射出人们对自己曾失落的内心世界的寻找。', '1楼C区', 'Save', NULL, NULL, NULL),
	(30, 'Grimm\'s Fairy Tales.jpg', '格林童话全集', 'Grimm\'s Fairy Tales', '格林兄弟', '德国', '1994-11', '童话', '《格林童话全集》是德国民间故事集。由德国的雅各・格林和威廉・格林兄弟根据民间口述材料改写而成。他们搜集、整理、出版这些民间童话的目的，正如威廉所说，是"希望它成为一本有教育意义的书，因为我再也想不出什么更富有教益，更天真无邪，更令人心旷神怡的读物，能比它更适合于儿童的心性与能力了。"作品的主要内容是颂扬勤劳和诚实，鄙弃懒惰和自私，鼓励对暴力和邪恶的反抗，激发对被压迫者的同情和爱护。书中的200多个故事，大部分源自民问的口头传说，因而比较正确地反映了当时人民的思想感情。其中的《灰姑娘》、《白雪公主》、《小红帽》、《青蛙王子》等童话故事，脍炙人口，享誉世界。作品问世一百多年来，已被译成70多种文字，在世界各国广为流传，成为各地收集民间故事的范例。', '1楼C区', 'Save', NULL, NULL, NULL),
	(31, 'Usborne Guzzle Adventures.jpg', '午夜飞机上的谋杀', 'Usborne Guzzle Adventures', '沃特斯', '美国', '1997', '推理', '《午夜飞机上的谋杀》是个非同一般的神秘故事。它的故事特点是你必须自己解开迷底。在整本书里，你必须按顺序去解开迷底，以便理解后面的故事。案件的线索和证据隐藏在字里行间和图画里。', '1楼D区', 'Save', NULL, NULL, NULL),
	(32, 'The Complete Sherlock Holmes.jpg', '福尔摩斯探案全集', 'The Complete Sherlock Holmes', '柯南·道尔', '英国', '2013-10', '推理', '如果你到世界各地旅行，不论是巴黎还是纽约，东京还是伦敦，你会看到在大小书店、车站码头，甚至在火车车厢和飞机的座舱里，到处都有侦探小说出售；你翻开欧美的报刊杂志，立刻就会看到醒目的侦探小说的新书预告。侦探小说今天拥有最大数量的读者。1887年，一位叫阿?柯南道尔的医生以大侦探夏洛克?福尔摩斯为主角，在刊物上发表了《血字的研究》，从此后人们发现原来侦探小说还可以如此实用，能渗透日常生活的肌理找到事件真相。于是，全世界都开始为福尔摩斯而疯狂，他独特的思维方式，他瘦削的体态与古怪的生活方式，他敏锐的洞察力以及让助理华生恐惧到背后发毛的判断能力，让这位名侦探成为神一般的存在，为陷入迷雾中的英国伦敦点燃一线曙光，贝克街221号缔造的传奇就这样诞生了。福尔摩斯这个人物，彻底地体现了一种维多利亚时代的实证精神——一种基于理性和科学的信念。这也是他的中文译者最景仰他的地方。', '1楼D区', 'Save', NULL, NULL, NULL),
	(33, 'Agatha Christie\'s Hercule Poirot Series.jpg', '阿加莎·克里斯蒂“波洛”系列', 'Agatha Christie\'s Hercule Poirot Series', '阿加莎·克里斯蒂', '英国', '2009-11', '推理', '《阿加莎·克里斯蒂侦探推理“波洛”系列(套装全32册)》包括《蓝色列车之谜》、《古墓之谜》、《人性记录》、《沉默的证人》、《东方快车谋杀案》、《阳光下的罪恶》、《罗杰疑案》、《尼罗河上的惨案》、《死亡约会》、《悬崖山庄奇案》、《ABC谋杀案》、《空谷幽魂》、《云中命案》、《啤酒谋杀案》、《斯泰尔斯庄园奇案》、《鸽群中的猫》、《底牌》、《葬礼之后》、《幕后凶手》、《牙医谋杀案》、《高尔夫球场命案》、《死人的殿堂》、《四魔头》、《圣诞奇案》、《柏棺》、《第三个女郎》、《三幕悲剧》、《怪钟》、《大象的证词》、《清洁女工之死》、《致命遗产》、《万圣节前夜的谋杀案》。阿加莎·克里斯蒂被誉为举世公认的侦探推理小说女王。她的著作英文版销售量逾10亿册，而且还被译成百余种文字，销售量亦逾10亿册。她一生创作了80部侦探小说和短篇故事集，19部剧本，以及6部以玛丽·维斯特麦考特的笔名出版的小说。著作数量之丰仅次于莎士比亚。', '1楼D区', 'Save', NULL, NULL, NULL),
	(34, 'Keigo Higashino Collection.jpg', '东野圭吾精品集', 'Keigo Higashino Collection', '东野圭吾', '日本', '2013-8', '推理', '日本当代作家东野圭吾的作品集，由4部长篇小说组成。东野圭吾四大杰作盒装合集，含《嫌疑人X的献身》、《白夜行》、《放学后》、《幻夜》。', '1楼D区', 'Save', NULL, NULL, NULL),
	(35, 'Miss Marple The Complete Short Stories.jpg', '马普尔小姐探案全集', 'Miss Marple The Complete Short Stories', '阿加莎·克里斯蒂', '英国', '2019-10', '推理', '马普尔小姐探案全集！收录十四本：1.《寓所谜案》2.《死亡草》3.《藏书室女尸之谜》4.《魔手》5.《谋杀启事》6.《借镜杀人》7.《黑麦奇案》8.《命案目睹记》9.《破镜谋杀案》10.《加勒比海之谜》11.《伯特伦旅馆》12.《复仇女神》13.《沉睡谋杀案》14.《马普尔小姐最后的案件》', '1楼D区', 'Save', NULL, NULL, NULL),
	(36, 'Dear Little Dog.jpg', '亲爱的小狗', 'Dear Little Dog', '线条小狗', '中国', '2025-4', '绘本', '《亲爱的小狗》是风靡全网的IP形象“线条小狗”的首部治愈系漫画故事集，收录38篇全新漫画内容，讲述四季流转间，马尔济斯和小金毛一起度过的美好时光。其中既有时而温暖、时而搞怪的快乐日常，也有探索自我、寻找幸福定义的冒险故事，还有与小伙伴们的趣味互动。内容可爱有趣，画风清新治愈，每一篇都萌化心脏。', '1楼C区', 'Save', NULL, NULL, NULL),
	(37, 'What Happens Next.jpg', '后来呢后来怎么了', 'What Happens Next', '吉竹伸介', '日本', '2019-8', '绘本', '爷爷去世了，我在他床下发现了一本笔记本，上面写满了他对天堂的幻想，以及自己死后的各种计划。如果天堂真的像爷爷想象的那么好玩，我就安心了。读着读着，我开始兴奋地计划自己去天堂之后的事情，可很快就发现——我有很多很多现在就想做的事！', '1楼C区', 'Save', NULL, NULL, NULL),
	(38, 'Wanderings of Sanmao.jpg', '三毛流浪记', 'Wanderings of Sanmao', '张乐平', '中国', '2019-7', '绘本', '张乐平，是中国当代最杰出的漫画家之一。1910年11月10日出生于浙江省海盐县海塘乡黄庵头村。父亲是位乡村教师。母亲擅长刺绣、剪纸，是张乐平最早的美术启蒙者。1945年，张乐平从广东重返上海，开始新的漫画创作生涯。1946年，《三毛从军记》在上海《申报》发表，引起轰动。第二年，另一部传世之作《三毛流浪记》在《大公报》连载，激起社会强烈反响。这一时期，张乐平的漫画作品大胆地反映了深刻的社会矛盾。', '1楼C区', 'Save', NULL, NULL, NULL),
	(39, 'Flotsam.jpg', '海底的秘密', 'Flotsam', '大卫·威斯纳', '美国', '2008-12', '绘本', '在一个普通的日子里，男孩在沙滩上捡拾到一架被海浪冲上岸的照相机。他将相机中的底片拿去冲洗后，看到了许多令人难以置信的相片，有在海龟背上的城市、会移动的海星岛屿、坐在沙发上看书的章鱼等等。甚至透过其中一张照片，还可以看到每一张过去曾经发现相机、并拍下自己影象的所有小孩。而这个惊人的发现，也让男孩下定决心，他也要做之前每个小孩都会做的事。', '1楼C区', 'Save', NULL, NULL, NULL),
	(40, 'The Rabbit Problem.jpg', '兔子的12个大麻烦', 'The Rabbit Problem', '埃米莉·格雷维特', '英国', '2012-5', '绘本', '这个故事源自13世纪宫廷数学家裴波那契提出的一道数学题，解答了1+1等于288这样一个命题。整本书以兔子家庭年历的形式，按月份记载了兔子们的喜怒哀乐。书里的兔宝宝诞生纪念册、红萝卜食谱，兔毛衣编织手册等等，让读者应接不暇，惊喜连连。最后一个蹦出来的大立体页里，在很小的空间里，展示了满满当当288只兔子，使读者的惊喜度达到峰值。', '1楼C区', 'Save', NULL, NULL, NULL),
	(41, 'The Scream.jpg', '绝叫', 'The Scream', '叶真中显', '日本', '2020-7', '悬疑', '铃木阳子死了，死在独居的公寓里。正确说来，是铃木阳 子几个月前死了。因为发现她时，不但遗体遭到屋内的十一只猫啃食，连猫也全数饿死了。铃木阳子显然是「孤独死」的最佳范例，但这名女子为何落到这步田地？她的亲人、朋友、同事在哪里？她的人生轨迹又是如何？《绝叫》是日本新锐社会派推理作家叶真中显创作的推理小说，讲述了女主人公阳子在平庸懦弱的表象之下，隐密的跌宕、罪恶人生。该书揭露常被人们忽视的社会问题，深刻而引人深思，刻画人物思想的变化细腻而一针见血，以阳子的离奇经历，连缀了日本四十年来社会变迁的各种缩影，是日本近年来具有代表性的优秀推理小说。', '1楼D区', 'Save', NULL, NULL, NULL),
	(42, 'The Klein Bottle.jpg', '克莱因壶', 'The Klein Bottle', '冈岛二人', '日本', '2019-9', '悬疑', '什么时候你开始怀疑这个世界是假的？日本虚拟现实VR题材开山杰作，超前《盗梦空间》20年！传奇推理作家组合冈岛二人预言之书，以超强的技术预见力，30年前就已完美构想出虚拟现实游戏体验装置！上杉彰彦从未如此兴奋——他写的故事被伊普西隆研发公司买下，即将制作成颠覆时代的全新游戏《克莱因2》（Klein 2），并受邀与少女梨纱一同担任游戏测试员。上杉彻底陷入了由K2造就的完美虚拟世界，为它的逼真、超前赞叹不已。然而随着测试过程的深入，伊普西隆公司行事神秘得令他生疑，游戏中更不断听到有人警告他：“快逃！”与此同时，一个自称是梨纱好友的女孩找到上杉，她说梨纱已失踪多日，音信全无。然而在寻人的过程中，两人都开始怀疑对方在撒谎，因为他们的记忆完全对不上……', '1楼D区', 'Save', NULL, NULL, NULL),
	(43, 'The Thirteenth Step.jpg', '消失的13级台阶', 'The Thirteenth Step', '高野和明', '日本', '2020-5-15', '悬疑', '一对老夫妇惨遭杀害。一切证据都指向树原亮，他却因车祸，恰好丧失了案发前后数小时的记忆……死刑执行官南乡携手刚假释出狱的纯一调查，希望替这位丧失记忆的死刑犯洗清冤屈。但他们查到的唯一线索，就是树原亮记得自己曾“走在台阶上”。距离树原亮被执行死刑的时间所剩无几，但这起案 件始终疑云重重，仅有的线索“台阶”仿佛也凭空消失了……', '1楼D区', 'Save', NULL, NULL, NULL),
	(44, 'No One Innocent in 19 Years Crime.jpg', '19年间谋杀小叙', 'No One Innocent in 19 Years Crime', '那多', '中国', '2018-7', '悬疑', '与谋杀者的通信，与生死彼岸的通信，与不可能的爱情的通信，与叵测命运的通信。通信串起十九年的时间，串起愤怒、悲伤、不甘和眷恋，也串起了一宗又一宗的谋杀事件。当柳絮看见谋杀于面前上演，以为是一切悲剧的开始。实际上，她踏进了一条暗河的中游，无论是向上追溯，还是顺流而下，都布满了死亡的漩涡。', '1楼D区', 'Save', NULL, NULL, NULL),
	(45, 'The Long Night.jpg', '长夜难明', 'The Long Night', '紫金陈', '中国', '2017-1', '悬疑', '嫌疑人杀人抛尸，却因意外在大庭广众之下被当场抓获。现场至少有几百个目击证人，嫌疑人对整个犯罪经过也供认不讳。人证、物证、口供，证据链齐全。就在检察机关对嫌疑人正式提起公诉之时，案情却陡然生变……这样一桩铁板钉钉的杀人抛尸案背后，究竟隐藏着怎样令人震惊的案情？温文尔雅的知名律师、声名狼藉的前检察官、暴躁偏激的“坏警察”……各自扮演着什么角色？为了查清真相，“他”历经十年光阴，付出了青春、事业、名声、前途、家庭，甚至，还包括生命。', '1楼D区', 'Save', NULL, NULL, NULL),
	(46, 'Project Hail Mary.jpg', '挽救计划', 'Project Hail Mary', '安迪·威尔', '美国', '2021-9', '科幻', '一趟孤注一掷的太空远征，一座没有尽头的科学迷宫，一次争分夺秒的冒险营救，一段跨越星际的真挚友谊。浩瀚宇宙中，瑞恩•格雷斯是整个人类文明仅存的希望。但在醒来的那一刻，他连自己的名字都不记得。他在未知的恐惧中寻找身份，从记忆的碎片中获取线索。这个肩负拯救地球重任的关键人物，现已命悬一线！人类文明究竟能否存续？在这场“挽救计划”里，一切都充满了挑战……', '1楼D区', 'Save', NULL, NULL, NULL),
	(47, 'The Three-Body Problem.jpg', '三体', 'The Three-Body Problem', '刘慈欣', '中国', '2008-1', '科幻', '文化大革命如火如荼进行的同时。军方探寻外星文明的绝秘计划“红岸工程”取得了突破性进展。但在按下发射键的那一刻，历经劫难的叶文洁没有意识到，她彻底改变了人类的命运。地球文明向宇宙发出的第一声啼鸣，以太阳为中心，以光速向宇宙深处飞驰……四光年外，“三体文明”正苦苦挣扎——三颗无规则运行的太阳主导下的百余次毁灭与重生逼迫他们逃离母星。而恰在此时。他们接收到了地球发来的信息。在运用超技术锁死地球人的基础科学之后。三体人庞大的宇宙舰队开始向地球进发……人类的末日悄然来临。', '1楼D区', 'Save', NULL, NULL, NULL),
	(48, 'Flatland A Romance of Many Dimensions.jpg', '平面国', 'Flatland: A Romance of Many Dimensions', '埃德温·A·艾勃特', '英国', '2020-8', '科幻', '作者在平面宇宙设定基础上，展开细节详实的“平面国”生活画卷。平面国的各形状居民操心自己的国家社会，就像我们操心自己的日常生活。他们住在平面房子里，通过雾气和光线识别他人，靠彼此触摸识别“角度”区分地位。平面国史上还发生通过染色消除阶级而引发的大事件，比起空间世界的人类历史也不遑多让。故事的主角，一位体面的正方形先生突然遇到了从三维国前来平面国传福音的“球”。他决定跟随这位导师向平面国传播立体空间的真理，却无法用平面国居民能理解的语言去解释高度和上（而不是北）。被人当做疯子后，他写出了这部传世的《平面国》。作为读者的我们，将在这个故事中获得上帝视角，得以审视自身，以科学的态度，理解“科学的谦卑”', '1楼D区', 'Save', NULL, NULL, NULL),
	(49, 'Flowers for Algernon.jpg', '献给阿尔吉侬的花束', 'Flowers for Algernon', '丹尼尔·凯斯', '美国', '2015-4', '科幻', '声称能改造智能的科学实验在白老鼠阿尔吉侬身上获得了突破性的进展，下一步急需进行人体实验。个性和善、学习态度积极的心智障碍者查理·高登成为最佳人选。手术成功后，查理的智商从68跃升为185，然而那些从未有过的情绪和记忆也逐渐浮现。', '1楼D区', 'Save', NULL, NULL, NULL),
	(50, 'Ball Lightning.jpg', '球状闪电', 'Ball Lightning', '刘慈欣', '中国', '2016-9', '科幻', '某个离奇的雨夜，一个球状闪电闯进了少年的视野，并在一瞬间将少年的父母化为灰烬。少年毕其一生去解开那个将他变成孤儿的自然之谜。但未曾想，多年后，他的研究被纳入“新概念武器”开发计划，他所追寻的球状闪电变成了下一场战争中决定祖国生存或是灭亡的终武器。及锋而试，大西北戈壁滩上升起冰冷的“蓝太阳”，世界变得陌生而怪异。一个完全未知的未来，在宇宙观测者的注视下，降临在人类面前……', '1楼D区', 'Save', NULL, NULL, NULL),
	(51, 'Hakone Ekiden.jpg', '我们的箱根驿传', 'Hakone Ekiden', '池井户润', '日本', '2025-8-18', '青春', '箱根驿传，日本热门长跑接力赛，每年元旦后举行，除了关东的二十支大学队之外，赛场上还有一支特别的队伍，那就是由未能进入决赛的大学各派出一名选手组成的关东学生联合队（下称“学联队”），但他们的成绩不计入排名，也不会留下比赛纪录。今年，由新上任的甲斐教练带领学联队，赛前，他设定了争夺前三的目标。结果遭到其他大学队的嘲笑与批评，以及媒体的冷遇。教练、前教练、站上赛场的选手，每个人都有自己的故事。让他们不断奋力奔跑的究竟是什么？他们能否实现赛前设定的看似不可能的目标？而另一边，负责直播这次赛事的大日电视台的制作人德重和他的同事们，又是如何理解体育精神、赛事直播的意义，并克服天气、地形乃至台内人事斗争等重重困难，完成直播箱根驿传的任务的？他们与学联队的相遇，会谱写出怎样动人的故事？', '2楼A区', 'Save', NULL, NULL, NULL),
	(52, 'Harry Potter and the Philosopher\'s Stone.jpg', '哈利·波特与魔法石', 'Harry Potter and the Philosopher\'s Stone', ' J·K·罗琳', '英国', '2000-9', '青春', '一岁的哈利・波特失去父母后，神秘地出现在姨父姨妈家的门前。哈利在姨父家饱受欺凌，度过十年极其痛苦的日子。姨父和姨妈好似凶神恶煞，他们那混世魔王儿子达力――一个肥胖、娇惯、欺负人的大块头，更是经常对哈利拳脚相加。哈利的“房间”是位于楼梯口的一个又暗又小的碗橱。十年来，从来没有人为他过过生日。但是在他十一岁生日那天，一切都发生了变化，信使猫头鹰带来了一封神秘的信：邀请哈利去一个他――以及所有读到哈利故事的人――会觉得永远难忘的、不可思议的地方――霍格沃茨魔法学校。在魔法学校，哈利不仅找着了朋友、学会了空中飞行，骑着一把型号为光轮2000的飞天扫帚打魁地球，还得到了一件隐形衣。他发现那里的一切――从上课到吃饭到睡觉都充满了魔力，但是一块魔石出现了，它与哈利的命运息息相关……', '2楼A区', 'Save', NULL, NULL, NULL),
	(53, 'With you.jpg', '最好的我们', 'With you', '八月长安', '中国', '2013-8-5', '青春', '你还记得高中时的同桌吗？那个少年有世界上最明朗的笑容，那个女生有世界上最好看的侧影。高中三年，两个人的影子和粉笔灰交织在一起，黑白分明，在记忆里面转圈。本书以怀旧的笔触讲述了女主角耿耿和男主角余淮同桌三年的故事，耿耿余淮，这么多年一路走过的成长故事极为打动人心，整个故事里有的都是在成长过程中细碎的点点滴滴，将怀旧写到了极致，将记忆也写到了极致。', '2楼A区', 'Save', NULL, NULL, NULL),
	(54, 'Dragon Raja.jpg', '龙族', 'Dragon Raja', '江南', '中国', '2010-4', '青春', '他以为他将这样度过一生，他以为他始终只是个衰小孩。但是，一封来自卡塞尔学院的录取通知书改变了他的一生。云层里透出神秘的吟唱：你也有神奇的父母，你也有热血的同伴，你的血管里流动着龙族的血液。而你的目标将是 —— 屠龙。由中国最有影响力的青春读物品牌《知音漫客》、《漫客•小说绘》策划，著名青春小说家，九州创始人江南启动全新青春热血大作《龙族》，该作品以一个少年的冒险之旅为故事核心，展现了龙的世界中的神秘与宏大。主角路明非只是一个普通的懵懂高中生，一封来自卡塞尔学院的来信改变了他平淡的人生。在热血与神秘的呼唤下，在爱与梦想的抉择下，他毅然选择了未知。黑色的直升机划过天际，陌生国度的大门向他缓缓开启，平凡的中国小孩走上不平凡的屠龙之路。而遥远的卡塞尔学院却处处透着神秘——奇怪的课程、搞笑的学长、疯狂的教师、骄傲的同学……路明非刚刚进入学校就遭遇了无数的怪事。但是，随之而来的挑战也开始了，等级考试、言灵考验、地图搜索。龙的世界也终于在水下露出了神秘面纱。这个世界究竟有没有龙？龙的世界又有哪些未解之谜？路明非的人生将是如何？理想、热血、奋斗，全新的人生，全新的冒险经历！', '2楼A区', 'Save', NULL, NULL, NULL),
	(55, 'The Catcher in the Rye.jpg', '麦田里的守望者', 'The Catcher in the Rye', 'J. D. 塞林格', '美国', '2021-6', '青春', '我叫霍尔顿，16岁，身高快一米九，半边脑袋头发花白。但我爸说我像个小孩，好吧，可我还是觉得自己远比实际年龄成熟。假如你乐意听，我就跟你聊聊我前阵子的几件荒唐事吧。首先是我考砸了。比如写作文，我喜欢表达自己心里的东西，但他们更在意你标点用得对不对，假如你自由发挥，就活该得低分。有些科目我没用功，但我还是很尊重老师，可他一点儿面子也不给我留，让我很难过。前不久有个男孩从宿舍窗口跳了下去，霸凌他的人却什么事也没有……我买了顶红猎帽，也许会被当成怪人，但戴上它我感觉自己挺酷。我那自恋的室友让我帮他写作业，因为他得去约会。约会对象是我暗恋的女孩，可他连她的名字都能记错。我跟那小子打了一架，准确说，是我骂他结果挨了顿揍。我心情不大好，想着给自己放两天假，去市里散散心。然而我遇到的每个人都让我更难过。我问出租车司机公园湖面结冰后，野鸭去哪里过冬了？我问见多识广的同学，爱与性到底是怎样的关系？我问我信任的老师人生是否只有一种标准答案？没人回答我。我太难受了，想要逃离这里，找个安宁的地方度过余生，又怕我妈崩溃。我想去当一个麦田里的守望者，抓住那些跑向悬崖的孩子。但是，会有人来抓住我吗……', '2楼A区', 'Save', NULL, NULL, NULL),
	(56, 'My Sunshine.jpg', '何以笙箫默', 'My Sunshine', '顾漫', '中国', '2011-1', '言情', '我还记得与他们初遇在人群熙攘的超市，就像在后记里写的那样，忽然就冒出那样一种感触攫住了我。也许早一步，晚一步，他们不是他们，我不是我，谁知道呢，缘分总是那么玄之又玄。 我还记得那是大三的暑假，我在我的老台式机上，一遍遍的写着他们的重逢，写了十几遍，终于我满意了，他们也满意了。 我还记得我在学校的机房排队，等不及了，就拿出白纸先把情节记下来，生怕灵感转瞬即逝。 我还记得上课的时候他们也不安分，不断地在我脑袋里自行演绎着，让我不得不当个不专心的学生，一遍遍在笔记本上写着他们的名字，才能得到抒发后的平静。 一时间有些恍然。 好像是眨眼间，却已经很远了。 时间真是世间最残酷又最美好的东西。 从写这篇文开始，到现在，已经过去了七年，已经和以琛和默笙分开的时间一样漫长了。 嗨，以琛默笙，又见面了。', '2楼A区', 'Save', NULL, NULL, NULL),
	(57, 'Scarlet Heart.jpg', '步步惊心', 'Scarlet Heart', '桐华', '中国', '2006-6', '言情', '一脚踏空的少女，穿越千年的时空，从繁华都市的深圳来到风云诡变的宫廷。正处于争位时候的阿哥们，款款深情的目光后，带着探究、带着诱惑也带着几分真真假假的心疼。她努力地想避开着历史的洪流，但那一双双幽暗深邃的眼睛却将拉住……', '2楼A区', 'Save', NULL, NULL, NULL),
	(58, 'Love O2O.jpg', '微微一笑很倾城', 'Love O2O', '顾漫', '中国', '2014-8', '言情', '顾漫，传说中最著名的“乌龟”，因为每一个人物、每一段情节，都字斟句酌，精益求精，所以虽然拼命在写，还是难以脱逃被定义为“龟速”的命运（编编写着写着忽然脑补了一个使劲挪，然而还是挪不动的乌龟形象！不能更生动！改天找人画出来！）', '2楼A区', 'Save', NULL, NULL, NULL),
	(59, 'Moments We Shared.jpg', '云边有个小卖部', 'Moments We Shared', '张嘉佳', '中国', '2018-7', '言情', '云边镇少年刘十三的成长故事。刘十三自幼与开小卖部的外婆相依为命，努力读书为了离开小镇，追寻远方与梦想。在城市里碰壁受挫的刘十三回到了小镇，与少时玩伴程霜重逢。小镇生活平静却暗潮汹涌，一个孤儿，一场婚礼，一场意外，几乎打破了所有人的生活。为了完成一个几乎不可能完成的任 务，刘十三拼尽全力，却不知道，生命中更重要的正在离自己而去。', '2楼A区', 'Save', NULL, NULL, NULL),
	(60, 'Norwegian Wood.jpg', '挪威的森林', 'Norwegian Wood', '村上春树', '日本', '2023-11', '言情', '1987年，一架巨大的波音747 飞机穿过厚厚的雨云，即将降落在德国汉堡机场，机舱里开始轻声播放不知哪个交响乐团演奏的披头士乐队的《挪威的森林》。三十七岁的男主人公渡边听到这旋律，不由得心绪澎湃，回忆起十八年前学生时代的往事。当年，渡边的好朋友Kizuki有一个青梅竹马的恋人直子，她在Kizuki十七岁自杀身亡后，遭遇了严重的精神障碍。渡边深爱着温柔美丽的直子，却只能眼睁睁地看着她在精神痛苦的泥沼中越陷越深，自己也痛苦到无法自拔。就在这时，活泼开朗的小林绿像一道明亮的光束，照进他的生活。两个女孩，一动一静、一明一暗、一生一死，使得渡边左右为难、苦闷彷徨，挣扎在自我成长和相互救赎的道路上。', '2楼A区', 'Save', NULL, NULL, NULL),
	(61, 'The Demi-Gods and Semi-Devils.jpg', '天龙八部', 'The Demi-Gods and Semi-Devils', '金庸', '中国', '1994-5', '武侠', '天龙八部乃金笔下的一部长篇小说，与《射雕》，《神雕》等 几部长篇小说一起被称为可读性最高的金庸小说。《天龙》的故事情节曲折，内容丰富，也曾多次被改编为电视作品。是金庸作品中集大成的一部。故事以北宋末年动荡的社会环境为背景，展开波澜壮阔的历史画卷，塑造了乔峰、段誉、 虚竹、慕容复等形象鲜明的人物，成为武侠史上的经典之作。故事精彩纷呈，人物命运悲壮多变，是可读性很强的作品，具有震撼人心的力量。', '2楼B区', 'Save', NULL, NULL, NULL),
	(62, 'Legends of the Condor Heroes.jpg', '射雕英雄传', 'Legends of the Condor Heroes', '金庸', '中国', '1999-04', '武侠', '《射雕英雄传》是金庸的代表作之一，作于一九五七年到一九五九年，在《香港商报》连载。《射雕》中的人物个性单纯，郭靖诚朴厚重、黄蓉机智狡狯，读者容易印象深刻。这是中国传统小说和戏剧的特征，但不免缺乏人物内心世界的复杂性。由于人物性格单纯而情节热闹，所以《射雕》比较得到欢迎，被拍成各种语种的电影和电视剧在全球众多国家和地区热播。', '2楼B区', 'Save', NULL, NULL, NULL),
	(63, 'The Return of the Condor Heroes.jpg', '神雕侠侣', 'The Return of the Condor Heroes', '金庸', '中国', '1994-5', '武侠', '《神雕侠侣》是金庸作品集之一。其主人公杨过自然而然地走上了非正统的人生道路，入了“道流”。其特点是“至情至性，实现自我”，即把个人的利益、情感、个性及人格尊严置于人生首位，作为首要目标，亦作为待人处事，评价是非的首要原则。书中将杨过对郭靖的杀父之仇与疼惜之恩难以取舍的复杂心理刻画得维妙维肖；他与“姑姑”小龙女的情感纠葛和他对江湖世事的渴望又令他挣扎不已……', '2楼B区', 'Save', NULL, NULL, NULL),
	(64, 'Meteor Butterfly And a Blade.jpg', '流星·蝴蝶·剑', 'Meteor Butterfly And a Blade', '古龙', '中国', '2013-8', '武侠', '孟星魂，人称江湖第一冷血杀手，本来是奉自己的恩人——又像是母亲又像是情人的高老大之密令，要去取老伯的性命。老伯不是圣人，不是完人，也不是社会意义上的正面人物，但老伯是庄子笔下的“真人”，超逸洒脱，不拘于外界的一切戒律，唯求能明其本心，尽其本性。“老伯”就是孙玉伯！没有人真正知道孙玉伯究竟是个怎么样的人？究竟能做什么事？但无论谁有了困难——有了不能解决的困难时，都会去求他帮助。他从不托词推诿，也绝不空口许诺，只要他答应了你，天大的事你都可以放到一边，因为他绝不会令你失望。你不必给他任何报酬，甚至于不必是他的老朋友。他虽然不望报酬，但报酬却还是在不知不觉中给了他。他的报酬就是别人对他的友爱和尊敬，就是“老伯”这称呼。他喜欢这称呼，而且引以为荣。这样的一个人，孟星魂却奉命要刺杀他……', '2楼B区', 'Save', NULL, NULL, NULL),
	(65, 'Moonlight Blade.jpg', '天涯·明月·刀', 'Moonlight Blade', '古龙', '中国', '2005-8', '武侠', '《天涯·明月·刀》的故事是古龙另一作品《边城浪子》的外传，书中的主角傅红雪已是中年人。故事讲述了一个在江湖中占有着巨大财富和无上权威的名侠，同时也是武林之首的公子羽，以名利财富诱惑天下第一剑燕南飞做自己的替身，并派遣他和手下明月心前去刺杀傅红雪。傅红雪两次战胜燕南飞却没有杀死他。公子羽还制造出关于天下第一暗器孔雀翎的传说，江湖人士受诱惑为争夺这件武器而纷纷丧生。他派自己的手下卓玉贞当了孔雀翎主人秋水清的情妇，继而血洗孔雀山庄。不明真相的秋水清临死前将卓玉贞托付给傅红雪，但傅红雪从卓玉贞的行径中认识到她的真相。他怀着坚忍不拔的毅力，杀死公子羽派来的一个个杀手，最后来到公子羽的住处，在决斗中杀死了替代公子羽出战的燕南飞。他拒绝学燕南飞一样担任公子羽替身，离开那些诱人的财富，回到一个真心爱他的女人身边。而公子羽也意识到继续下去是不行的，便放弃了名利，退隐江湖。', '2楼B区', 'Lend', '3', '2026-04-05', '2026-04-12'),
	(66, 'An Shi Rebellion.jpg', '安史之乱', 'An Shi Rebellion', '张诗坪 / 胡可奇', '中国', '2025-8', '历史', '本书详细讲述了安史之乱的叛乱缘起、唐燕双方的作战计划和早期战事 ，继而系统分梳了唐燕两政权反复争夺关中和唐军收复洛阳的战事，及其背后的政治博弈、财政重组。最后将叙述重点聚焦于安史之乱后期的军事、政治活动。本书的写作并不仅仅是介绍安史之乱的来龙去脉，更重要的是重新将历史记忆的问题放置于历史书写的前台。本书指出，伴随着时间的流逝和后世史官对史料的选择，安史之乱中各方宣传的很大一部分内容，由于比起历史的本来面目更符合大众趣味，于是就如此流传下来，逐渐深入人心。', '2楼B区', 'Save', NULL, NULL, NULL),
	(67, 'Those Happenings of the Ming Dynasty.jpg', '明朝那些事儿', 'Those Happenings of the Ming Dynasty', '当年明月', '中国', '2017-5-1', '历史', '全本明朝白话史，当年明月全新修订，明史专家毛佩琦教授审订并作序推荐，全程演绎明朝三百年兴衰风云。全景立体式图文阅读体验，原文一字不少，新增四大板块全新内容——延伸内容、插图、图表、地图。涉及关键词解析、历史背景及相关插图、作战图、形势图、人物关系图等。图解历史，小细节、大事件一目了然，通俗易懂。《明朝那些事儿》主要讲述的是从1344年到1644年这三百年间关于明朝的一些事情，以史料为基础，以年代和具体人物为主线，并加入了小说的笔法，对明朝十七帝和其他王公权贵和小人物的命运进行全景展示，尤其对官场政治、战争、帝王心术着墨*多，并加入对当时政治经济制度、人伦道德的演义。', '2楼B区', 'Save', NULL, NULL, NULL),
	(68, 'The Grand Scribe\'s Records.jpg', '史记', 'The Grand Scribe\'s Records', '司马迁', '中国', '2022-9-26', '历史', '《史记》是我国历史上第一部纪传体通史，为“二十四史”之首，全书分十二本纪、十表、八书、三十世家、七十列传，凡一百三十篇，记述了自黄帝以来至汉武帝时期约三千年的历史，囊括政治、经济、军事、科技、学术各个方面的内容，是一部史学名著，也是一部文学名著。本次出版的三全本《史记》（全十册），原文以中华书局点校本《史记》修订本为底本，吸收古今学者的研究成果，对《史记》做注释、翻译、评析，各篇篇首有解释篇题、概括要点的“释名”，篇末有汇集古今点评的“集评”和延伸探讨的“评论”。注释详实，引证丰富；翻译准确，流畅易懂；评析全面，深入浅出；《史记》研究大家韩兆琦审阅把关，是市面上仅见的真正的全本全注全译本《史记》，现代人阅读《史记》的理想读本。', '2楼B区', 'Save', NULL, NULL, NULL),
	(69, 'The 1007-Day War.jpg', '1007天的战争', 'The 1007-Day War', '马平', '中国', '2022-5-1', '历史', '本书从战略和战役两个层面解读和展现了抗美援朝战争的过程。书中共九章，内容包括：出战的决策与准备、狭路相逢的遭遇战(第一次战役)、扭转战局的关键之役(第二次战役)、接近“顶点”的越线攻势(第三次战役)、由进攻到全线运动防御(第四次战役)、不成功的“决定性之战”(第五次战役)、战略转变和开启停战谈判、反“绞杀战”与反登陆准备、艰难而漫长的收局之战。', '2楼B区', 'Save', NULL, NULL, NULL),
	(70, 'Montaillou.jpg', '蒙塔尤', 'Montaillou', '埃马纽埃尔·勒华拉杜里', '法国', '2023-8', '历史', '蒙塔尤是法国南部讲奥克语的一个牧民小山村。1320年，时任帕米埃主教（后为教皇）的雅克•富尼埃作为宗教裁判所法官到此办案。在调查、审理各种案件的过程中，他像现代侦探一样发现和掌握了该山村的所有秘密，包括居民的日常生活、个人隐私以及种种矛盾、冲突等，并把它们详细记录下来。法国著名学者勒华拉杜里以历史学家的敏感和精细，发现并利用了这些珍贵史料，以现代史学、人类学和社会学方法再现了六百多年前该村落居民的生活、思想、习俗的全貌和14世纪法国的特点。', '2楼B区', 'Save', NULL, NULL, NULL),
	(71, 'Psychology Themes and Variations.jpg', '心理学导论', 'Psychology Themes and Variations', '韦恩·韦登', '美国', '2016-12', '心理学', '这部世界知名的心理学导论一直享有盛誉，由美国心理学会颁发的卓越教学奖得主韦登教授撰写，科学性和实用性的完美结合，使它在诸多心理学入门教材中脱颖而出，成为美国一流高校中使用量最大的心理学专业入门教材之一，并在全球广泛采用，充分反映了作者在国际心理学教学领域的权威地位，他独具匠心的撰写方式成就了经典之作，值得我们借鉴和学习。心理学值得我们学习的原因除了它的实用价值，还在于它提供了一种有力的思考方式。本书鼓励读者去思考开放性的问题，检验他们关于行为的假设，把心理学的概念应用到实际生活中去。作为探索心理学之旅的开始，这本非常实用的入门书一定会让大家对心理学这门科学着迷，且满怀热情。', '2楼C区', 'Save', NULL, NULL, NULL),
	(72, 'How does Analysis Cure.jpg', '精神分析治愈之道', 'How does Analysis Cure', '海因茨·科胡特', '美国', '2016-3-1', '心理学', '《精神分析治愈之道》是自体心理学创始人海因茨·科胡特的最后遗作，不仅回应了针对《自体的分析》与《自体的重建》的批评，而且从根本上修正和发展出了完全不同的精神分析治疗的思想基础，并对共情、俄狄浦斯情节和自体客体转换等核心概念作了细致的阐述；结合重新评估自体心理学的临床实践，陈述了自体心理学的理论框架，并通过临床案例，着重强调了精神分析治愈的本质。', '2楼C区', 'Save', NULL, NULL, NULL),
	(73, 'Meet Your Emotional Friends.jpg', '认识你的情绪朋友', 'Meet Your Emotional Friends', '马里安·杰拉特斯 / 黛博拉·范德沙夫', '比利时', '2022-12', '心理学', '你知道吗？每个人的身体中，有五种基本情绪，它们是伤心、愤怒、嫉妒、害怕、快乐。每一种情绪，都是我们亲密的朋友。有句话说：“你是与你相处时间最长的五个人的平均值。”人的五种基本情绪，就无时无刻都在与我们相处。《认识你的情绪朋友》一书中，比利时儿童心理学家杰拉特斯通过有趣的解说、具体的实践互动，将五种基本情绪变身为我们的亲密朋友，引导9-12岁儿童正确认知情绪，直到学会管理自己的情绪。', '2楼C区', 'Save', NULL, NULL, NULL),
	(74, 'Doing Psychotherapy.jpg', '心理治疗实战录', 'Doing Psychotherapy', 'Michael Franz Basch', '美国', '2014-1', '心理学', '作者巴史克本身拥有二十多年心理动力学及精神分析取向的教学与实务经验，他以自己曾经接触、督导的个案为例，一方面呈现治疗师和个案之间的对话，一方面完整记录在真实的治疗情境里，治疗师会面临到的各种情况、难以避免的错误、如何采取应对措施，以及在何时做适当的介入。本书的作者巴史克受过严谨的医学训练，古典精神分析的熏陶，自体心理学的沉浸以及对现代认知神经科学的理解，令他足以拨开理论的迷雾，专注于实务，用美式思维特有的简洁、具体和浅白，对心理治疗过程进行解剖，让读者明明白白地了解，治疗师的每一句话背后蕴藏着什么，目的为何，也让读者清清楚楚地看到，个案是如何在治疗师的关注、理解和有目的地推动下获得改变的。', '2楼C区', 'Save', NULL, NULL, NULL),
	(75, 'The Courage to Be Disliked.jpg', '被讨厌的勇气', 'The Courage to Be Disliked', '岸见一郎 / 古贺史健', '日本', '2015-4', '心理学', '被讨厌的勇气「并不是要去吸引被讨厌的负向能量，而是，如果这是我生命想绽放出最美的光彩，那么，即使有被讨厌的可能，我都要用自己的双手双脚往那里走去。」「因为拥有了被讨厌的勇气，于是有了真正幸福的可能。」你是否常常对繁琐的生活感到乏味？你是否时时为复杂的人际关系感到疲惫？你是否认为人生的意义越来越模糊难见？我们如何能够在繁杂的日常琐碎和复杂的人际关系中用自己的双手去获得真正的幸福？这一切的答案尽在这本《被讨厌的勇气》中！', '2楼C区', 'Lend', '4', '2026-04-05', '2026-05-05'),
	(76, 'The Philosopher\'s Final Lesson.jpg', '哲学家的最后一课', 'The Philosopher\'s Final Lesson', '朱锐', '中国', '2025-3', '哲学', '当你看到这本书的时候，你就收到了哲学家朱锐留给世界的爱与告别。被医学宣布仅剩数十天的生命，每天都在体验身体的疼痛与功能丧失，朱锐留下的文字直面每一步都更接近死亡的进程。但他无所畏惧，并将对生命和死亡的思考带至人生最后时刻。他始终认为死亡是生命的一部分，我们谈论死亡，是为了更好地活。这本书正是源自作者朱锐在生命最后的十日对谈，以及他在中国人民大学开设的最后一门哲学课，汇集了他在哲学研究领域 30 余年的思考。从大学教室到安宁病房，他将最后的时间转为生命的渡口，用哲学的理念和生命的实践阐明个体生命的意义和价值、对死亡的积极性的理解，从古希腊“练习死亡”的哲辩到庄子“大化流行”的生死观，从存在主义困境到爱的终极释义，希望给予读者一个多元的生命视角，重新理解生命、理解生活、理解自己，用哲学和艺术的态度来直面生活中的终极挑战。', '2楼C区', 'Save', NULL, NULL, NULL),
	(77, 'On the Shortness of Life.jpg', '论人生短暂', 'On the Shortness of Life', '塞涅卡', '古罗马', '2026-1', '哲学', '生命并不短暂，短暂的是我们真正活着的时光。在这部作品集中，古罗马哲学家塞涅卡以三篇随笔探讨时间、苦难与心灵的安宁。《论人生短暂》指出，生命的长度取决于我们如何使用时间；《慰藉赫尔维娅》写于流放之中，是写给母亲的安慰与自省；《论心灵之安宁》则追问人在纷扰与焦虑中如何保持内在的平静。三篇随笔层层递进，从时间管理到苦难应对，最终指向心灵平衡。塞涅卡以隽永而深刻的文字，铺就了一条抵御浮躁与虚无的思想道路。', '2楼C区', 'Save', NULL, NULL, NULL),
	(78, 'Living on Borrowed Time.jpg', '活在借来的时间中', 'Living on Borrowed Time', '齐格蒙特·鲍曼', '英国', '2026-1-1', '哲学', '“流动”的现代世界已经完成了从生产者社会到消费者社会的转型，其自然延伸是永久债务人社会。消费者社会的主导思想是阻止需求被满足并创造需求；其自然延伸是让消费者通过借贷来增加消费，使偿债过程本身转化为新一轮的借贷——债务的消解并非通过清偿，而是更多的透支。这一机制不局限于经济领域，更已渗透到社会的方方面面：消费主义的冲击让我们习惯了依赖借贷来满足欲望，追求更好的生活品质。然而，这种透支的财富并不能长久地支撑我们的生活。全球变暖的威胁已经变得不可忽视。我们一直在借来的时间中挥霍，却没有意识到自己无法为后代留下一个可持续的地球家园。基因改造的利弊不容忽视。人类通过透支的科技不断拓展自身的可能性，但在追求进步的过程中，我们也面临着道德和伦理的困境。网络社交平台的影响深远。我们通过社交媒体借来了社交体验，却忽视了真实生活中的交流和情感。', '2楼C区', 'Save', NULL, NULL, NULL),
	(79, 'Entretiens.jpg', '绝望者的练习', 'Entretiens', 'E.M.齐奥朗', '法国', '2026-1', '哲学', '真正能够承受虚空的唯一方式，就是意识到虚无，否则生命便是无法忍受的。但是，如果你意识到了虚无，那么你经历的一切都可以保持正常比例，而不会被绝望夸大成疯狂的比例。即使在极度绝望的时刻，我也有笑的力量。这就是人类比动物强的地方。笑是一种虚无主义的表现，就像愉悦可以是一种哀悼的状态。当我的朋友——或者陌生人——经历苦恼和绝望的时刻，我只有一个建议能给他们：“去墓地走走。”在生命最后的二十五年里，齐奥朗陆续接受来自世界各地的采访。在这些谈话中，齐奥朗回忆在罗马尼亚的童年和青春岁月、移居法国的经历、思想的来源、与友人的关系，并谈及自己为何抛弃母语，改用法语写作。访谈真实呈现了贯穿齐奥朗作品的核心主题，汇聚了其碎片化思想的精髓：无聊、失败、死亡、神秘主义……机锋与笑语之间，折射出这位“异端”思想家的矛盾本性——激进的悲观主义中，总是伴随着欢快、幽默和嘲讽。', '2楼C区', 'Save', NULL, NULL, NULL),
	(80, 'The Republic.jpg', '理想国', 'The Republic', '柏拉图', '古希腊', '1986-8', '哲学', '《理想国》涉及柏拉图思想体系的各个方面，包括哲学、伦理、教育、文艺、政治等内容，主要是探讨理想国家的问题。《理想国》一书是柏拉图的一篇重要对话录，对话录里柏拉图以苏格拉底之口通过与其他人对话的方式设计了一个真、善、美相统一的政体，即可以达到公正的理想国。柏拉图的理想国是人类历史上最早的乌托邦。在他的理想国里统治者必须是哲学家，他认为现存的政治都是坏的，人类的真正出路在于哲学家掌握政权，也只有真正的哲学家才能拯救当时城邦所处的危机。这种信念构成了柏拉图成熟的政治哲学体系的核心。在他的眼里“哲学家”有着特殊的内涵。他认为哲学家是最高尚、最有学识的人，而这种贤人统治下的贤人政体就是最好是政体。所以，只有建立以哲学家为国王的国家才是最理想的国家。这个国家就是存在于天上的模范国家。', '2楼C区', 'Save', NULL, NULL, NULL),
	(81, 'The Sociological Imagination.jpg', '社会学的想象力', 'The Sociological Imagination', '查尔斯·赖特·米尔斯', '美国', '2017-3-2', '社会学', '要把握人与社会、人生与历史、自我与世界之间的相互作用，必须有特定的心智品质，而他们并不具备这样的品质。他们没有能力以特别的方式应对自己的私人困扰，以控制通常隐伏其后的那些结构转型。 他们所需要的，以及他们感到他们所需要的，是一种特定的心智品质，能够有助于他们运用信息，发展理性，以求清晰地概括出周边世界正在发生什么，他们自己又会遭遇到什么。我的主张是，从记者到学者，从艺术家到公众，从科学家到编辑，都越来越期待具备这种心智品质，不妨称之为社会学的想象力。', '2楼C区', 'Save', NULL, NULL, NULL),
	(82, 'From the Soil The Foundations of Chinese Society.jpg', '乡土中国', 'From the Soil: The Foundations of Chinese Society', '费孝通', '中国', '2006-4', '社会学', '著名社会学家费孝通教授，一生行行重行行，实地调查和考察总结中国农村经济发展的各种模式，写下了诸多不朽篇章。本书推出的是学界共认的中国乡土社会传统文化和社会结构理论研究的代表作《乡土中国》、《生育制度》、《乡土重建》和《皇权与绅权》四篇著作，可供社会学工作或教学、研究者参考。', '2楼C区', 'Save', NULL, NULL, NULL),
	(83, 'Invitation to Sociology.jpg', '与社会学同游', 'Invitation to Sociology', '彼得·L.伯格', '美国', '2014-10', '社会学', '社会学是一场游戏：既有轻松的一面，可供消遣；又是思想挑战，要求游戏者有一定的素养。在《与社会学同游》书中，彼得•伯格以如椽之笔和酣畅的文字带领我们神游社会学的庄严殿堂。在这趟旅途中，我们将紧随作者去审视人与社会的关系，去体会社会学的多重视角，关照社会学的多重性质。几个突出的主题是：“人在社会”“社会在人”和“社会如戏”。这部权威学者的经典著作宛若浓缩而精美的靓汤，带给我们丰富的人文主义营养。', '2楼C区', 'Save', NULL, NULL, NULL),
	(84, 'The Discovery of Society.jpg', '发现社会', 'The Discovery of Society', '兰德尔·柯林斯 / 迈克尔·马科夫斯基', '美国', '2014-5', '社会学', '本书的第六版曾于2006年以《发现社会之旅》的书名出过中译本。本书为同一译者根据最新版本修订的新译本。全书以人物为主线，勾画了二百多年来西方社会学思想与实践的发展历程，不仅阐述了各个经典传统的发展，还讨论了当代理论的各种发展方向。作者叙述人物生平，往往着墨不多而有传神之处。评述各派思想，多结合当时的社会背景及知识潮流，溯其源头，追其余脉，使对各种思想潮流的介绍既简洁又深入。 使读者不仅能全面了解每一位思想家的思想，还能在宏观的历史背景下把握西方社会学思想的整体脉络。', '2楼C区', 'Save', NULL, NULL, NULL),
	(85, 'Nineteen Eighty-four.jpg', '一九八四', 'Nineteen Eighty-four', '乔治·奥威尔', '英国', '2018-5', '社会学', '奥威尔传世之作，20世纪影响最为深远的文学经典小说。被译为至少65种语言，全球销量超过5000万册，改编电影层出不穷：小说自1949年出版以来，被翻译成60多种语言，传播到世界各地，总销量超过5000万册，数十次被改编成电影、电视剧。《一九八四》是英国作家乔治•奥威尔生前的最后一部小说，也是20世纪独具影响力的文学作品。该书自1949年首次出版至今，多次被改编成电影上映，被列入“20世纪百大英文小说”，并被美国《时代》杂志评为“1923年以来最好的100本英文小说之一”。本书的故事发生在未来世界，即1984年的大洋国，主人公温斯顿在那个黑暗的社会环境里坚守自己的信念，努力摆脱种种枷锁，却未料到自己的命运早已注定……作者以丰富的想象力和严密的逻辑推理，展现了一个泯灭人性的未来世界，警醒世人不要落入这样的悲剧中。', '2楼C区', 'Save', NULL, NULL, NULL),
	(86, 'Source Code.jpg', '源代码', 'Source Code', '比尔·盖茨', '美国', '2025-2', '传记', '比尔·盖茨是当代富有影响力、引领变革的商业领袖和慈善家。这本书讲述的便是他的成长故事。 比尔·盖茨在商业领域创造的辉煌早已广为人知。20 岁的他离开哈佛大学，创办了一家日后成为行业巨头的软件公司，改变了整个世界的工作与生活方式。这位亿万富翁随即将注意力转向慈善事业，致力于应对气候变化、全球健康和美国教育领域的重重挑战。', '1楼A区', 'Save', NULL, NULL, NULL),
	(87, 'Elon Musk.jpg', '埃隆·马斯克传', 'Elon Musk', '沃尔特·艾萨克森', '美国', '2023-9-12', '传记', '著名传记作家艾萨克森以近距离的观察视角，揭开了如今全球引人注目、富有争议性的创新企业家的神秘面纱：他善于突破常规，引领全球进入电动汽车时代、私人太空探索时代和人工智能时代，还将推特收入囊中。埃隆·马斯克小时候在南非生活，那时他经常遭受校园欺凌，但同父亲给他造成的情感创伤相比，这些伤痛都微不足道。他的童年浸透了人性，这将他塑造为一个坚强而又脆弱的男孩，他对风险的容忍度极高，渴望营造出富有戏剧性的生活，让人类文明成为星际文明是他的宏大目标。2008年，SpaceX的火箭在前三次发射过程中接连爆炸，特斯拉也即将破产，这是他生命中地狱般的至暗时期。在飓风来临时，他是最兴奋的人之一。动荡的环境和剧烈的冲突对他有着莫大的吸引力，有时他甚至渴望这些东西，无论是在工作中，还是在他努力维持却未能持久的恋爱关系中。每当面临艰巨的挑战，紧张感常常让他夜不能寐，甚至呕吐不止，但这些都是他赖以为生的养分。2022年年初，也就是在SpaceX成功发射了31颗卫星、特斯拉卖出了近100万辆汽车、埃隆成为地球上最富有的人一年后，对于自己一再挑起戏剧性冲突的背后动机，他略带感伤地谈起了他的反思。', '1楼A区', 'Save', NULL, NULL, NULL),
	(88, 'Biography of Zeng Guofan.jpg', '曾国藩传', 'Biography of Zeng Guofan', '张宏杰', '中国', '2019-1', '传记', '曾国藩，没有显赫的家世，天赋堪称晚清同时代大人物当中最差，却官至两江总督、直隶总督、武英殿大学士，在复杂的时代变局中超越众人，成就最大，被誉为大清“中兴第一名臣”，且最后全身而退。他的人生经历，无论是过去还是现在都给人以特别的启示。他出身平常，家族五六百年没出过秀才，可谓典型的小镇青年。他智商平常，考了7次才中秀才，却以笨功夫成功打通了科举之路，顺利进入翰林院。他一生崇尚笨拙，以扎实而非机巧取胜。他踌躇满志进京，面对全国精英，发现自己见识狭隘、观念鄙俗，陷入自卑和焦虑。三十而立，他立志学做圣人，研读经典，广交朋友，提高自我管理能力，在京期间飞速升迁。他善于把握机会和创造机会，天下大乱之际，一介书生独创湘军，统率群雄。对抗太平天国，屡战屡败，甚至两次投江自尽，多次深陷绝境。47岁时更被皇帝弃用，陷入人生低谷。蛰居老家两年，他反思自我，最终大悔大悟。重新出山后，为人处世脱胎换骨，不仅清除了政治敌人，而且以“结硬寨、打呆仗”战胜了军事宿敌太平天国，位极人臣。', '1楼A区', 'Save', NULL, NULL, NULL),
	(89, 'Steve Jobs.jpg', '史蒂夫·乔布斯传', 'Steve Jobs', '沃尔特·艾萨克森', '美国', '2023-3', '传记', '作为创造力和想象力的标志偶像，乔布斯有如过山车般精彩的人生和炽热激越又敏感叛逆的性格使其成为美国伟大的创新领袖。他站在人文与科技的交会处，将创造力、想象力、哲学思辨与技术相结合，使个人电脑、动画电影、音乐、手机、平板电脑、数字出版六大产业发生了颠覆性变革，改变了人们享受生活的方式、看待世界的视角以及对未来科技的认识。一个疯狂、充满激情的时代造就了他，他也凭一己之力引领了一个时代。在两年多的时间里，艾萨克森与乔布斯进行了40多次面对面的倾谈，并对乔布斯100多位家庭成员、朋友、竞争对手和同事进行了不受限的采访，造就了这本定制传记。乔布斯全力配合本书的写作，并不干涉也不限定内容，对一切接近开放，甚至鼓励大家袒露心声。谈及与他共过事的人及竞争对手，乔布斯直言不讳，甚至尖酸刻薄。同样，乔布斯的朋友、敌人、同事也为我们提供了一个靠前的毫无掩饰的视角。这让乔布斯的激情、能量、欲望、完美主义、艺术修养及对掌控权的迷恋塑造出的商业哲学在本书中一览无余。', '1楼A区', 'Save', NULL, NULL, NULL),
	(90, 'Kafka.jpg', '卡夫卡传', 'Kafka', '莱纳·施塔赫', '德国', '2026-1', '传记', '是德国学者莱纳·施塔赫毕十八年之功写就的卡夫卡传记三部曲的最后一卷。讲述卡夫卡1916—1924人生最后九年的经历。他遭受世界大战、帝国崩解、排犹浪潮、经济危机带来的创痛，又接连染上西班牙流感、肺结核的恶疾。但这段岁月何以成为他洞悉人生的黄金期？他将“冥思”与“领悟”如炼金术士般铸入《乡村医生》《城堡》《饥饿艺术家》等奇作，凿刻出诸多难以定义的文体实验品；他在“最坏的时机”下挣脱布拉格勇赴柏林，实现迈向内心独立的重大一跃。而他的晚期创作也密织在与菲莉丝、沃里泽克、密伦娜、朵拉的情感羁绊里。施塔赫延续前作全景电影式叙事手法，基于最新一手文献、手稿，以大量特写镜头细腻还原了卡夫卡的日常生活，在广阔时代的远景里解读了卡夫卡的生存困境，“在喧噪中辨识他那独异的声音”。', '1楼A区', 'Save', NULL, NULL, NULL),
	(91, 'Chinese painting.jpg', '中国绘画', 'Chinese painting', '巫鸿', '中国', '2025-3', '艺术', '在元至清这长达六百余年的历史过程中，绘画蓬勃发展，传世画作与画论浩如烟海。延续“中国绘画”系列，《中国绘画：元至清》跳出传统画史写作的窠臼，在历史原境中展开对元、明、清三代绘画作品的细读与梳理，不止围绕名家名作展开，亦将目光投向女性画家与女性题材绘画、风俗画和人物画，探讨图像创造者的不同身份和性别，以及图像在不同场合中的应用和流通，剖析文人画、宫廷绘画与商业绘画的交融互动，揭示绘画在不同时期的发展状况，以及地域文化对绘画发展的影响，以更全面、立体的视角重新理解中国绘画。', '2楼D区', 'Save', NULL, NULL, NULL),
	(92, 'The Story of Art.jpg', '艺术的故事', 'The Story of Art', '贡布里希', '英国', '2008-04', '艺术', '《艺术的故事》概括地叙述了从最早的洞窟绘画到当今的实验艺术的发展历程，以阐明艺术史是“各种传统不断迂回、不断改变的历史，每一件作品在这历史中都既回顾过去又导向未来。继1997年三联版《艺术的故事》后，英国费顿出版社授权广西美术出版社独家出版，也是国内唯一合法授权的版本。', '2楼D区', 'Save', NULL, NULL, NULL),
	(93, 'The Course of Beauty.jpg', '美的历程', 'The Course of Beauty', '李泽厚', '中国', '2009-7', '艺术', '本书是中国美学的经典之作。凝聚了作者李泽厚先生多年研究，他把中国人古往今来对美的感觉玲珑剔透地展现在大家眼前，如斯感性，如斯亲切。今配以精美的插图，本书就更具体地显现出中国这段波澜壮阔的美的历程。这样的著作能有多少呢？凤毛麟角吧，以十几万字的篇幅来完成这样一个”美的历程”，高屋建瓴，势如破竹，且能做到“天网恢恢，疏而不漏”，该细密处细密，该留连处留连，丝丝入扣，顺理成章，在看似漫不经心的巡礼中触摸到文明古国的心灵历史，诚非大手笔而不能为。《美的历程》一书真是写得英姿勃发。才气逼人。单是标题，便气度不凡：龙飞凤舞。青铜饕餮。魏晋风度、盛唐之音，更不用说每过几页就有一段华彩乐章了。实际上，《美的历程》是可以当作艺术品来看待的。它充分地表现着李泽厚的艺术魁力。 　　　　 ——易中天', '2楼D区', 'Save', NULL, NULL, NULL),
	(94, 'Philosophy of Art.jpg', '艺术哲学', 'Philosophy of Art', '丹纳', '法国', '2019-1-1', '艺术', '《艺术哲学》一书是丹纳在巴黎美术学校讲课时讲稿的辑录，也是丹纳最重要的文艺理论著作，集中体现了他的文艺理论思想。他在书中提出决定文明的三大要素——种族、环境、时代，而这三大要素又决定了衡量艺术作品价值的标准，即艺术作品表现事物特征的重要程度、有益程度、效果集中程度，并由原则出发，阐述意大利、尼德兰和古希腊的艺术流派。', '2楼D区', 'Save', NULL, NULL, NULL),
	(95, 'What makes a home.jpg', '何以为家', 'What makes a home', '马丁·贝利', '英国', '2021-5', '艺术', '作者马丁.贝利一直在研究凡.高，这是他写的“凡.高三部曲”中的其中一本。本书以独特的视角展现了凡.高生活中的人与地方是怎样同他的作品产生交集的。通过描绘凡.高生活工作过的地方，如阿姆斯特丹、伦敦、巴黎和普罗旺斯等，来讲述这位艺术大师的故事，并探寻都市与田园景致对他创作的影响。本书附有大量画作、未发表过的档案文件和凡.高同时期的风景照片，形象演绎了天才画家的行迹所至，为人们了解这位史上最重要的艺术家提供了一种独特的视角。', '2楼D区', 'Save', NULL, NULL, NULL),
	(96, 'The Institutional Logic of China\'s National Governance.jpg', '中国国家治理的制度逻辑', 'The Institutional Logic of China\'s National Governance', '周雪光', '中国', '2017-3-1', '政治', '关于中国国家的治理逻辑，本书主要沿着两条脉络进行探讨：一是中央权威与地方政府之间的关系，这体现在各级政府体制的制度设施和行为方式；一是国家与民众之间的关系，这体现在国家与社会群体的相互影响上。本书从学术上推进了当前国内的国家治理研究，并为社会科学研究者提供了一种可以参照 的研究路径和视角。', '1楼B区', 'Save', NULL, NULL, NULL),
	(97, 'Arduous And Difficult Journey.jpg', '筚路维艰', 'Arduous And Difficult Journey', '萧冬连', '中国', '2014-10-1', '政治', '本书以简明清晰的文字对当代中国的历史轨迹做了逻辑梳理。作者认为，从执政党的建国方略、发展模式和基本政策角度考察，中国社会主义的实践路径经历了从实行新民主主义开始，途经仿效苏联模式、追寻赶超之路、发动继续革命和实行改革开放的五次历史选择。', '1楼B区', 'Save', NULL, NULL, NULL),
	(98, 'Introduction to Political Science.jpg', '政治学通识', 'Introduction to Political Science', '包刚升', '中国', '2015-11', '政治', '本书是作者在复旦大学政治学课程讲义的基础上修改润色而成的。本书力求成为一部通俗易懂、深入浅出的政治学普及入门读物。这部书正是为那些对政治和公共事务感兴趣的读者朋友们而写的。通过本书，作者希望能够帮助读者加深对中国政治与世界政治的认知，帮助读者理解政治学领域的重大议题、主要理论与基本方法，帮助读者养成健全与系统的政治思考能力。', '1楼B区', 'Save', NULL, NULL, NULL),
	(99, 'Les Partis Politiques.jpg', '政党论', 'Les Partis Politiques', '莫里斯·迪韦尔热', '法国', '2025-5', '政治', '本书作为20世纪极具影响力的政治学经典著作，开创性地构建了现代政党研究的理论框架，其核心贡献“迪韦尔热定律”深刻揭示了“多数选举制催生两党制，而比例代表制催生多党制”的制度性规律，这一发现至今仍是比较政治学研究的基石。该书不仅系统分析了政党组织形态与政治制度的互动关系，更敏锐地指出政党作为民主政治核心载体所蕴含的内在矛盾——既是实现民主治理的必要机制，又潜藏着官僚化与寡头统治的异化倾向。书中对政党类型学、政党制度动态演进的分析，对当代政党政治危机的预见，依然保持着强大的理论解释力，为理解现代民主政治的复杂本质提供了不可替代的学术视角。', '1楼B区', 'Lend', '2', '2026-04-05', '2026-04-12'),
	(100, 'Local Governments in Transition.jpg', '转型中的地方政府', 'Local Governments in Transition', '周黎安', '中国', '2017-8', '政治', '中国在过去30年取得了经济增长的奇迹，其中，有些学者从政府的角度来解析经济发展之谜，尤其是关注于地方政府在发展中充当的角色以及地方政府与中央政府的博弈过程。然而当我们把目光转向发展中国家和转型国家时，不难发现许多国家的政府表现并不令人满意。为什么中国的地方政府有这么高的激励去推动地方经济的发展？中国是如何解决地方官员激励与政府作为问题的？但是，中国的高速经济增长也导致了一系列社会问题，如粗放型增长、收入分配不公、地区差异、环境污染、官员腐败、地方保护主义等等，这些问题如何与官员激励和政府治理模式联系在一起呢？本书从地方官员激励与政府治理视角出发，揭示了中国经济高速增长所依赖的政经条件和制度基础，提供了一种关于中国经济增长的政治经济学解释。', '1楼B区', 'Save', NULL, NULL, NULL),
	(101, 'Siddhartha.jpg', '悉达多', 'Siddhartha', '赫尔曼·黑塞', '德国', '2017-1', '宗教', '《悉达多》并非是佛陀的故事，它讲述了一个人的一生，千万寻常人亦会经历的一生。意气风发的少年郎，常认为自己是被命运选中的人。抛下过去，随了跌跌撞撞的步伐，找寻心中的声音，追逐名利，经历友情，品尝爱情。不同的是，悉达多一生追求的是生命的圆融统一，看似宏大，确是每个人无法回 避的问题。黑塞的语言是充满诗性的，正如本书副题“一首印度的诗”，因不得而知的原因，此副题在前人所出版本中都被回避了。为了尽可能表现黑塞的诗意，我们选择从德文直译，尽管我们的译文不能完全实现这种诗意，但其诗的本性与精神显而易见。本书地位在前人的版本中已被反复强调——亨利·米勒的最爱；影响了包括电台司令在内的许多名人雅士；在六十年代美国掀起过阅读黑塞的热潮，大学生们人手一册等等。但如书中成为摆渡人的悉达多所述，智慧无法分享，它可以被发现，被体验。', '1楼B区', 'Save', NULL, NULL, NULL),
	(102, 'History of Religious Thought.jpg', '宗教思想史', 'History of Religious Thought', '米尔恰·伊利亚德', '罗马尼亚', '2011-9-1', '宗教', '本书不仅阐述了历史上各种宗教现象的发展过程，更在空间上揭示宗教的结构以及宗教对于人类的意义。', '1楼B区', 'Save', NULL, NULL, NULL),
	(103, 'What does the Diamond Sutra Say.jpg', '金刚经说什么', 'What does the Diamond Sutra Say', '南怀瑾', '中国', '2016-3', '宗教', '《金刚经》是初期大乘佛教的代表作之一，也是般若类佛经的纲要书，它全称《金刚般若波罗蜜经》一卷，由姚秦鸠摩罗什于弘始祥译出，问世之后，即在社会上广泛流传，篡要、注解、类颂、重演、义记、采微、集解、科释、宗通、决疑、大意，直说等略种注释达一百多种。南怀瑾教授在台的数十年教化岁月中，曾经多次讲解《金刚经》；因时代不同，对象不同，讲解的方式和重点也各次不同。 现在的这一本书，是一九八八年的讲记。当时十方书院甫自成立，《金刚经》这一门课程，是为书院的学员及研究生而开，其他院校哲学系的同学，以及许多老修行们，常随众等，亦闻风而来，听讲者共约一百余人。每逢上课时间，复青大厦的十二楼，挤得水泄不通。 由于这次的听众，对佛学都有相当基础，对《金刚经》尤不陌生，故此，怀师的讲法深入骨髓，可说是叹未曾有！真正是：为上乘者说，为最上乘者说！ 一九七八年怀师讲了“如何修证佛法”，两年后再讲《金刚经》。因机缘特殊，对经中的疑问及似解难解之处，剖析得淋漓尽致。读后虽不悟，亦得其门矣！ ', '1楼B区', 'Save', NULL, NULL, NULL),
	(104, 'Life Solves Worries.jpg', '人生解忧', 'Life Solves Worries', '成庆', '中国', '2024-11', '宗教', '在普遍的心灵危机之下，何处寻找安心之道？本书是一本适合现代人读的佛学智慧入门读物。从现代人的日常和体验出发，用通俗易懂的语言拆解佛学看似玄妙的概念，用佛学真正的精神关切，来回应当代人种种的心灵追问，帮助每个感到人生之苦、对环境、人生、自我有困惑的人，重获内心的自由和安顿的力量。本书回到悉达多的经历说起，他在菩提树下到底觉悟到了什么，他又是如何应对生命最初的疑惑的？第二章“观自我”解答的人与自己的关系，如何面对不确定的世界？什么叫与自己和解？“四圣谛”“五蕴”“无我”等概念回应地正是这些疑惑。第三章“观众生”解答的是人与他人的关系，为何我们常感到孤独？善恶是绝对的吗？菩萨到底存在吗？这一章通过讲解《心经》《金刚经》等经典来回应这些疑惑。第四章“观生死”面对的是人终极的疑惑：为何会对死亡恐惧？我死后会去哪里？真的有转世与投胎吗？本章将解读什么是佛教的生死观，以及我们该如何为死亡作准备。生，老，病，死是每个人的必须经历的过程，环境与内心、自我与他人的关系，也是每个人必将修炼的功课。这本书解答的，就是这些贴近生命，难以思索却又无法逃避的问题。', '1楼B区', 'Save', NULL, NULL, NULL),
	(105, 'The Life of Jesus.jpg', '耶稣传', 'The Life of Jesus', '欧内斯特·勒南', '法国', '2010-10', '宗教', '本书是十九世纪法国著名哲学家、圣经史学批评家欧内斯特·勒南（1823—1892）的代表作。它依据普遍经验并消弭福音书中的神迹奇事，将耶稣还原为一个血肉丰满的基督教创始人和宗教思想家。本书论及耶稣的童年、青年、所受的教育和成长环境，其“上帝之国”“纯粹宗教”等观念的形成和发展，在加利利地区的巡回布道，在耶路撒冷的传教、被捕和受难等，别具一格地探讨了耶稣事业的性质及其在世界文化史上的地位。本书出版后一度风靡欧洲，带来一场前所未有的评判风暴，亦引起马克思、恩格斯的关注。恩格斯称赞勒南在将圣经批判通俗化、大众化，以方便读者理解等方面所做的努力，认为该书“可以作为历史资料来用”。', '1楼B区', 'Save', NULL, NULL, NULL),
	(106, 'Love in the Time of Cholera.jpg', '霍乱时期的爱情', 'Love in the Time of Cholera', '加西亚·马尔克斯', '哥伦比亚', '2012-9-1', '爱情', '《霍乱时期的爱情》是加西亚•马尔克斯获得诺贝尔文学奖之后完成的第一部小说。讲述了一段跨越半个多世纪的爱情史诗，穷尽了所有爱情的可能性：忠贞的、隐秘的、粗暴的、羞怯的、柏拉图式的、放荡的、转瞬即逝的、生死相依的……再现了时光的无情流逝，被誉为“人类有史以来最伟大的爱情小说”，是20世纪最重要的经典文学巨著之一。', '2楼A区', 'Save', NULL, NULL, NULL),
	(107, 'Wuthering Heights.jpg', '呼啸山庄', 'Wuthering Heights', '艾米莉·勃朗特', '英国', '2010-8', '爱情', '《经典译林:呼啸山庄》描写的吉卜赛弃儿希思克利夫被山庄老主人收养后，因不堪受辱和恋爱受挫，外出致富。回来后发现女友凯瑟琳已与地主林顿结婚，继而产生对地主及其子女进行报复的故事。全篇充满了强烈的反压迫、求自由的斗争精神，又始终笼罩着离奇、紧张、浪漫的艺术气氛。作品开始曾被人称作是年轻女作家脱离现实的天真幻想，但结合其所描写地区激烈的阶级斗争和英国当时的社会现象，不久又被评论界给予高度肯定，并受到广大读者的热烈欢迎。', '2楼A区', 'Save', NULL, NULL, NULL),
	(108, 'Call Me by Your Name.jpg', '夏日终曲', 'Call Me by Your Name', '安德烈·艾席蒙', '美国', '2018-3', '爱情', '意大利里维埃拉，一个夏天，十七岁的少年埃利奥遇到大他六岁、前来意大利游历的美国大学生奥利弗。 两人彼此着迷、犹疑、试探，渐渐地，情感在流动中迸发。这场邂逅虽然为时只有六周，却给男孩留下了一生的印记，因为在那个闷热的仲夏，他发现了此生再也无法寻找到的东西 ……', '2楼A区', 'Save', NULL, NULL, NULL),
	(109, 'Pride and Prejudice.jpg', '傲慢与偏见', 'Pride and Prejudice', '简·奥斯丁', '英国', '2010-6-1', '爱情', '本书描写傲慢的单身青年达西与偏见的二小姐伊丽莎白、富裕的单身贵族彬格莱与贤淑的大小姐吉英之间的感情纠葛，充分表达了作者本人的婚姻观，强调经济利益对恋爱和婚姻的影响。小说情节富有喜剧性，语言机智幽默，是奥斯丁小说中最受欢迎的一部，并被多次改编成电影和电视剧。', '2楼A区', 'Save', NULL, NULL, NULL),
	(110, 'The Moon and Sixpence.jpg', '月亮与六便士', 'The Moon and Sixpence', '威廉·萨默塞特·毛姆', '英国', '2017-1-1', '爱情', '“满地都是六便士，他却抬头看见了月亮。”银行家查尔斯，人到中年，事业有成，为了追求内心隐秘的绘画梦想，突然抛妻别子，弃家出走。他深知：人的每一种身份都是一种自我绑架，唯有失去是通向自由之途。在异国他乡，他贫病交加，对梦想却愈发坚定执着。他说：我必须画画，就像溺水的人必须挣扎。在经历种种离奇遭遇后，他来到南太平洋的一座孤岛，同当地一位姑娘结婚生子，成功创作出一系列惊世杰作。就在此时，他被绝症和双目失明击倒，临死之前，他做出了让所有人震惊的决定……人世漫长得转瞬即逝，有人见尘埃，有人见星辰。查尔斯就是那个终其一生在追逐星辰的人。', '2楼A区', 'Save', NULL, NULL, NULL),
	(111, 'Acceptance.jpg', '接纳', 'Acceptance', '筝小钱', '中国', '2026-1', '成长', '我们常困于对自身缺点的苛责、对他人差异的抵触，或是对无常境遇的抗拒，在挣扎中消耗心力。本书以细腻的笔触，结合心理学理论与真实案例，拆解“接纳” 的深层逻辑 —— 它并非妥协，而是与自我、他人及世界和解的智慧。从接纳不完美的自己，到包容多元的他人，再到坦然面对生活的起伏，书中提供了做好接纳功课的具体方法，引导读者卸下防备，在接纳中寻得稳定的内核，活出更松弛、更有力量的人生。', '2楼A区', 'Save', NULL, NULL, NULL),
	(112, 'Educated.jpg', '你当像鸟飞往你的山', 'Educated', '塔拉·韦斯特弗', '美国', '2019-10', '成长', '人们只看到我的与众不同：一个十七岁前从未踏入教室的大山女孩，却戴上一顶学历的高帽，熠熠生辉。只有我知道自己的真面目：我来自一个极少有人能想象的家庭。我的童年由垃圾场的废铜烂铁铸成，那里没有读书声，只有起重机的轰鸣。不上学，不就医，是父亲要我们坚持的忠诚与真理。父亲不允许我们拥有自己的声音，我们的意志是他眼中的恶魔。哈佛大学，剑桥大学，哲学硕士，历史博士……我知道，像我这样从垃圾堆里爬出来的无知女孩，能取得如今的成就，应当感激涕零才对。但我丝毫提不起热情。我曾怯懦、崩溃、自我怀疑，内心里有什么东西腐烂了，恶臭熏天。直到我逃离大山，打开另一个世界。那是教育给我的新世界，那是我生命的无限可能。', '2楼A区', 'Save', NULL, NULL, NULL),
	(113, 'The War of Art.jpg', '一生之敌', 'The War of Art', '史蒂文·普莱斯菲尔德', '美国', '2024-9', '成长', '你本该成为一名画家、企业家、运动员；你本该从昨天开始穿上跑鞋、拿起画笔、出门旅行。你屈服于止痛药、流言蜚语和手机成瘾，你本该成为的人只存在于夜深人静时的幻想。你屈服于这位一生之敌，浪费着自己的天赋。作为一个曾跌入谷底的过来人，作者普雷斯菲尔德以其毕生的经验，为我们总结了造成这些困境的根源——内阻力，并指出这位敌人是我们过上另一种人生面临的zui大挑战，而战胜它的方法是付诸行动，成为职业选手。本书为每一个人而写，尤其是创作者、创业者、拖延症患者、浪费天赋、缺乏行动力犹豫不决的人群，作者在给出一记响亮耳光的同时，也给予了无比慷慨真诚的鼓励。', '2楼A区', 'Save', NULL, NULL, NULL),
	(114, 'Father\'s Liberation Diary.jpg', '父亲的解放日志', 'Father\'s Liberation Diary', '郑智我', '韩国', '2025-3', '成长', '10万字，只写父亲3天的葬礼。父亲死了，撞上电线杆死的。严肃古板地活了一辈子，最后竟然就这样，结束了他一本正经的人生。葬礼上来了许多人。断了来往的亲戚、有名望的官员、出狱的犯人、叛逆的不良少女……上到七八十岁，下到十几岁，爱他的、恨他的，彼此意见相左、水火不容的，都聚在这个小小的吊唁厅里，互不干涉地用自己的方式悼念。他们都与父亲相知相交，彼此之间也有过不可逾越的围墙。但现在，在葬礼上，一种微妙的和平涌动，一种或许只有在死亡面前才能实现的和平。也许，父亲一直为之奋斗的，就是葬礼上的这个画面。', '2楼A区', 'Save', NULL, NULL, NULL),
	(115, 'One sentence is worth ten thousand.jpg', '一句顶一万句', 'One sentence is worth ten thousand', '刘震云', '中国', '2022-8', '成长', '《一句顶一万句》是著名作家刘震云的扛鼎之作，也是刘震云迄今为止最成熟最大气的作品，并在2011年获第八届茅盾文学奖。小说分上下两个部分，前半部“出延津记”写的是过去：卖豆腐老杨的二儿子杨百顺百事不顺，他一生改了三次名：为了寻个营生，被天主教神父老詹纳为教徒，改名杨摩西；给县长种地时因为一个尿壶得罪了县长，提心吊胆中有人说媒，便倒插门嫁给馒头铺的吴香香，改名吴摩西；吴香香给吴摩西扣了顶绿帽子，吴摩西带着吴香香和前夫的女儿巧玲假意去寻与人私奔的妻子，路上又把巧玲丢了，失望之中，要离开故乡，从此用喊丧的罗长礼的名字度过余生；后半部“回延津记”写的是现在：巧玲被卖到陕西，成了曹青娥，嫁给牛家，儿子牛爱国也是假意寻找与人私奔的妻子，又想到自己从前的相好，想起母亲的老家，于是走回延津……一出一走，延宕百年。', '2楼A区', 'Save', NULL, NULL, NULL),
	(116, 'Chinese Idiom Stories.jpg', '中国成语故事', 'Chinese Idiom Stories', '卢延光', '中国', '2007-8', '教育', '全书共收集成语500余条，每条成语由短至七八幅图片，长至三四十幅图片组成，共计6000余幅。全书体例统一，首先介绍成语的出处，再从头至尾把故事展开，让读者从阅读故事当中领会成语的寓意，并运用到工作和学习中。图文结合、清晰明朗、生动形象、引人入胜。这套连环画出版以来，读者竞相购买，洛阳纸贵，总印数达数千万册之众。该书也因此先后获过全国第二届连环画创作一等奖、全国优秀美术图书银牌奖和上海市优秀图书一等奖等奖项。中国成语故事》连环画是上世纪70年代末、80年代初由上海人民美术出版社组织程十发、戴敦邦等200余位著名学者、画家精心编绘而成的。这200多位画家名单中，当今中国人物画名家——老中青三代人几乎全部囊括其中，可谓群贤毕至。其中刚刚去世的程十发作品更是珍贵非常。这也是我国参加编绘人数最多的连环画。', '2楼D区', 'Save', NULL, NULL, NULL),
	(117, 'Say No to Social Bullying in Primary School.jpg', '对小学社交霸凌说不', 'Say No to Social Bullying in Primary School', '特鲁迪·路德维格', '美国', '2023-5-20', '教育', '过分的玩笑、小团体、言语贬低、八卦谣言……比起肢体暴力，社交霸凌更常在校园中发生，却容易被忽视。《对小学社交霸凌说不》帮助孩子识别和预防隐形伤害，有办法应对，保护自己；同时也弄清楚哪些言行可能让别人不舒服，把握分寸，维系友谊。全书共八册，帮助孩子处理很实际的问题。例如：什么是真正的朋友，什么是打着朋友旗号的霸凌？面对过分的玩笑，想让对方住口，又怕显得自己玩不起，到底该怎么办？如何在保护自身安全的前提下，阻止谣言的传播？作者常年走访全美各地学校，以写实细腻的故事，还原孩子那些隐秘复杂的困境和微妙难言的感受。孩子读起来会感同身受，因为这就是自己日常经历或看到的事。故事不讲大道理，却巧妙融入了多种方法，例如用幽默反击、大声说不、远离让自己不舒服的人、结交盟友、报告老师、制定友谊规则等。故事之后，孩子还可读到“被霸凌者可以做什么”“开玩笑时的注意事项”“道歉时的注意事项”等，进一步了解如何应对。', '2楼D区', 'Save', NULL, NULL, NULL),
	(118, 'Little Bean by the Window.jpg', '窗边的小豆豆', 'Little Bean by the Window', '黑柳彻子 / 岩崎千弘', '日本', '2018-5', '教育', '《窗边的小豆豆》是一部影响20世纪的儿童文学杰作，讲述了作者黑柳彻子上小学时一段真实的故事。小豆豆因淘气被原学校退学后，来到巴学园。在小林校长的爱护和引导下，一般人眼里“怪怪”的小豆豆逐渐成了一个大家都能接受的孩子，并奠定了她一生的基础。世界上最可怕的事情，莫过于有眼睛却发现不了美，有耳朵却不会欣赏音乐，有心灵却无法理解什么是真。不会感动，也不会充满激情。《窗边的小豆豆》不仅带给千万读者无数的笑声和感动，而且为现代教育的发展注入了新的活力，成为全世界极有影响的作品之一。', '2楼D区', 'Save', NULL, NULL, NULL),
	(119, 'Why Don\'t Students Like School.jpg', '为什么学生不喜欢上学', 'Why Don\'t Students Like School', '丹尼尔·T.威林厄姆', '美国', '2010-5', '教育', '本书是美国弗吉尼亚大学心理学教授威林厄姆的重要著作，是一本深受学生和教师欢迎的教育心理学著作。他用认知心理学的原理，详细分析了学生学习的过程和教师在课堂教学中必须注意的一些问题。书中每一章都运用了一个认知心理学的基本原理，如“事实性的知识先于技能”、“记忆是思考的残留物”、“我们在已知的环境中理解新的事物”、“儿童在学习方面更多的是相似而不是不同”、“教学技能可以通过练习而提高”等等。本书是一本关于认知心理学的普及读物，也是一本教育心理学的入门书籍。书中的许多观点新颖而深刻。如开篇伊始关于大脑的作用的分析，作者认为，大脑不是用来思考的，它的真正作用在于使你避免思考。虽然人类生来就具有好奇心，但是我们不是天生的杰出思想者，除非认知环境符合一定的要求，否则我们会尽可能地避免思考。作者指出，学生是否喜欢学校，在很大程度上取决于学校能否持续地让学生体验到解决问题的愉悦感。', '2楼D区', 'Save', NULL, NULL, NULL),
	(120, 'A Letter to the Children.jpg', '给孩子们的信', 'A Letter to the Children', 'C.S.路易斯', '英国', '2009-07', '教育', '本书在西方是少年儿童的必读书籍，是路易斯与很多热爱纳西亚传奇的儿童读者的通信集，它循循善诱地帮助儿童成长，使他们树立一些基本的人生原则，得到更多心灵的营养。', '2楼D区', 'Save', NULL, NULL, NULL),
	(121, 'Belief.jpg', '信念', 'Belief', '雷殿生', '中国', '2023-10', '励志', '他被称为“当代徐霞客”“中国阿甘”，为梦想准备10年，35岁开启徒步中国第一步，31天孤身徒步成功穿越罗布泊，连续10年徒步81000公里，在45岁成功徒步走完全中国，之后完成2000余场讲座鼓舞更多人坚定信念。他是探险者的励志偶像，是带领孩子们走出逆境的“雷叔叔”，是引导企业家和创业者建立强大信念的“雷老师”，更是鼓舞无数普通人积极面对挑战、构建美好人生的“引路人”。 你很难想象，他出生于小山村，11岁无奈辍学，13岁失去母亲，15岁失去父亲，徒步中国10年间走掉了19个脚指甲、穿烂了52双鞋、遭遇19次抢劫、40多次遇到野兽，历经泥石流、雪崩、沙尘暴和龙卷风，数次险些丧命...... 雷殿生在书中真诚分享了他坎坷童年、徒步中国、穿越无人区、探访各民族居住地、坚持环保的经历。他具备说走就走的勇气和徒步中国的能力，我们普通人很难有这样的人生经验，但可以从中感受到信念的力量。选定目标，便择一事终一生；直面绝望，靠自己逆风翻盘；心态积极，乐观者永远前行。人生无常，走路也是一种修行。', '2楼A区', 'Save', NULL, NULL, NULL),
	(122, 'The wisdom of life.jpg', '人生的智慧', 'The wisdom of life', '叔本华', '德国', '2008-10-01', '励志', '他于1850年写了《附录和补遗》一书，《人生的智慧》是该书中的一部分。在书中，他以优雅的文体，格言式的笔触阐述了自己对人生的看法。《人生的智慧》使沉寂多年的叔本华在晚年一举成名。我社出版的这本全译本是我国第一个根据德文版译出的中文本。这本书讨论的事情与我们的世俗生活至为接近，诸如健康、财富、名声、荣誉、养生和待人接物所应遵守的原则等。正如叔本华所说的，在这本书里他尽量以世俗、实用的角度考虑问题。因此，这本书尤其适合大众阅读。虽然叔氏尽量放弃了居高俯临的审视角度，但关于错综复杂并因此众说纷纭的世俗人情的话题，经过这位思想大师一贯深刻而因此透彻的讨论之后，变得清晰简明，话题也几已穷尽矣。', '2楼A区', 'Save', NULL, NULL, NULL),
	(123, 'Life never stops, madness never ends.jpg', '生命不息 疯狂不止', 'Life never stops, madness never ends', '李哲', '中国', '2019-3', '励志', '本书总共分为三个部分：第一部分疯狂人生，讲述李哲老师的成长与英语学习经历。第二部分致女儿书，是李哲老师写给女儿的信，涉及作者的教育观。第三部分英语江湖，分为发音为王、背诵为王、交流为王三大板块，系统讲述让每一个在校学生讲一口流利的英语，并且考高分的方法，以及让每一个成人学员用英语和外国人自由交流的秘密。', '2楼A区', 'Save', NULL, NULL, NULL),
	(124, 'Mortal Footprints.jpg', '凡人脚印', 'Mortal Footprints', '黄仁忠', '中国', '2021-6', '励志', '一部逆境中斗智拼搏改变命运的创业史，一本帮助中学生高考中榜夺魁的畅销书。《凡人脚印》于2021年6月由北京团结出版社出版，全国新华书店经销。是作家黄仁忠著作的纪实文学作品，由中山文学院院长陈德民题词，广东作家协会会员廖增伟作序，著名书法家潘锡强题写书名。作者根据自身经历写的励志小说，用生花妙笔讴歌改革开放给边远山区偏僻农村带来的巨大变化，追忆求学创业艰难，靠斗智拼搏取得辉煌成果的感人故事，词语娴熟生动精练，句子优美通顺流畅，故事情节跌宕起伏，幽默诙谐风趣，具有浓厚的农村风情和乡土韵味，是非常适合大中学生、家长、教师、商人、企业老板、社会青年和股票散户阅读的佳作。', '2楼A区', 'Save', NULL, NULL, NULL),
	(125, 'If I Were Given Three Days to See.jpg', '假如给我三天光明', 'If I Were Given Three Days to See', '海伦·凯勒', '美国', '2007-1', '励志', '这里记录了一个聋哑人凭籍自己惊人的努力，改变自己苦难命运的经历，在无光、无声、无语的孤绝世界里，她的坚强自信让自己的人生丰富多彩。海伦?凯勒这位19世纪最了不起的人物，一生创作了十四本书，其散文《假如给我三天光明》，更是以其旷世之美，征服了全世界的读者，成为广为传诵的经典名篇。坚强面对：当世界变得无光、无声又无助，她一次又一次克服了软弱，选择了坚强……接受挑战：面对生活的困境，她以超出常人的坚强毅力，用生命的全部力量创造了奇迹！拥抱世界：自己生活在茫茫黑暗世界中，她却把目光投向需要帮助的她人，把爱之光洒满世界……', '2楼A区', 'Save', NULL, NULL, NULL),
	(126, 'Maybe You Should Talk to Someone.jpg', '也许你该找个人聊聊', 'Maybe You Should Talk to Someone', '洛莉·戈特利布', '美国', '2021-7-28', '心理', '这是一位心理治疗师的回忆录，讲述了发生在诊室中的故事。在这个小小的密闭空间里，人们会展现出最真实、最脆弱的一面；也是在这里，人们获得了陪伴和倾听，也获得了宝贵的觉察、成长与改变。在书中，我们会看到四个来访者的故事，他们是：一个四十多岁、事业成功、自以为是，认为身边所有人都是蠢货的好莱坞制片人；一个三十多岁、刚刚新婚就被诊断出患有绝症，时日不多的大学女教师；一个六十九岁、离过三次婚，感觉孤独绝望，声称生活再不好转就要在七十岁生日当天自杀的老太太；一个二十多岁、有原生家庭创伤和酗酒问题，在爱情中频频受挫的姑娘。同时，书中还有第五个寻求帮助的人，那就是治疗师自己。她是一个单身的职场妈妈，四十多岁时遭遇失恋，几乎崩溃。有朋友对她说“或许你该找个人聊聊”，于是她也给自己找了一位心理治疗师。当她切换到来访者的位置，坐到另一位心理治疗师的沙发上诉说自己内心的脆弱与悲伤，就更能感受到心理治疗为何具有治愈和改变的力量。', '2楼D区', 'Save', NULL, NULL, NULL),
	(127, 'Calm the mind.jpg', '安定此心', 'Calm the mind', '姜涛', '中国', '2026-1', '心理', '在安定医院的诊室里，姜涛已经守望了30余年。自1993年行医以来，姜涛亲历了中国精神医学从封闭、匮乏到逐渐开放、走向科学的转变；也陪伴无数人走过精神困境幽暗的角落。精神病院不仅是治疗之地，也是一扇窥见社会的窗口，透过它，能够看到不同的人生：这里有在躁狂与抑郁之间起伏的老人，生命被病痛切割；有被母爱裹挟的女儿，将控制与爱纠缠成伤口；有被抽动与强迫折磨的少年，在偷窃与自伤间寻求短暂解脱；有长期被暴力与冷漠撕裂的女孩，用人格碎片守护求生希望；有患有双相情感障碍的嫌疑犯，他的抑郁与躁狂让他无法自控，最终导致犯罪；还有来自偏远乡村的青年，背负家族抑郁与自杀，被偏见束缚，直到一剂药片才尝到活下去的滋味。这些故事来自他人的经历，却藏着我们都逃不开的问题：情绪、关系、压力、孤独。看见他们，是重新理解自己的开始。', '2楼D区', 'Save', NULL, NULL, NULL),
	(128, 'The Power of Now.jpg', '当下的力量', 'The Power of Now', '埃克哈特•托利 (Eckhart Tolle)', '德国', '2013-7-1', '心理', '《当下的力量》堪称心灵读物经典，英文版自2004年出版至今，被翻译成30多种语言，畅销超过200万册。本书为中文版第三版。作者埃克哈特•托利在书中引导我们发现，我们一直都处在大脑或思维的控制之下，生活在对时间的永恒焦虑中。我们忘不掉过去，更担心未来。但实际上，我们只能活在当下，活在此时此刻，所有的一切都是在当下发生的，而过去和未来只是一个无意义的时间概念。通过向当下的臣服，你才能找到真正的力量，找到获得平和与宁静的入口。在那里，我们能找到真正的欢乐，我们能拥抱真正的自我。', '2楼D区', 'Save', NULL, NULL, NULL),
	(129, 'The Middle Passage.jpg', '中年之路', 'The Middle Passage', '詹姆斯·霍利斯', '美国', '2022-12', '心理', '为什么这么多人在中年遭遇众多挫折？为什么我们会把这些挫折当作一种危机？这种危机与经历又代表了怎样的意义？中年危机——詹姆斯·霍利斯将其称为“中年之路”——为我们提供了一个审视自己的机会，霍利斯教授提出了一个看似可怕实则具有解放意义的问题：“除了我的过往以及我所扮演的角色，我究竟是谁？”当我们发现，自己一直在以虚假的自我生活，被不切实际的期望驱使着扮演—个“临时的”成年人格时，我们就打开了第二个成年期的大门，将迎来真实的人格。在本书中，霍利斯教授基于荣格心理学的视角，以一种富有洞察力的方式呈现了中年经历的层次，并带领我们重新审视、界定、调整自己的人格，从而了解内心真正的需求，抛开童年创伤与“临时人格”的束缚，从痛苦出发，穿越“中年之路”，前往意义的彼岸，最终形成稳定、成熟、完善的人格。', '2楼D区', 'Save', NULL, NULL, NULL),
	(130, 'The Road Less Traveled.jpg', '少有人走的路', 'The Road Less Traveled', 'M·斯科特·派克', '美国', '2007-1', '心理', '这本书处处透露出沟通与理解的意味，它跨越时代限制，帮助我们探索爱的本质，引导我们过上崭新，宁静而丰富的生活；它帮助我们学习爱，也学习独立；它教诲我们成为更称职的、更有理解心的父母。归根到底，它告诉我们怎样找到真正的自我。正如开篇所言：人生苦难重重。M·斯科特·派克让我们更加清楚：人生是一场艰辛之旅，心智成熟的旅程相当漫长。但是，他没有让我们感到恐惧，相反，他带领我们去经历一系列艰难乃至痛苦的转变，最终达到自我认知的更高境界。', '2楼D区', 'Save', NULL, NULL, NULL),
	(131, 'Strange Afghanistan.jpg', '陌生的阿富汗', 'Strange Afghanistan', '班卓', '中国', '2024-9', '旅行', '2003年夏天，班卓独自从新疆出发，翻越帕米尔高原进入巴基斯坦，然后从巴基斯坦西北边境进入阿富汗的荒漠之中，从北至南、从南至西地将阿富汗转了一圈。对很多人来说，阿富汗只是新闻里那个与战争、贫困、饥荒、恐怖主义等字眼挂钩的遥远陌生之地。但在班卓笔下，一个个普通又鲜活的人出现在读者眼前：追求自由、热爱乌尔都语文学的巴基斯坦青年，自幼父母双亡的喀布尔旅馆经理，曾是空手道冠军的现役警察，为巴米扬绘制地图的日本青年，河谷里的村民与中巴上的少年，突然求婚的单身男子与坎大哈的八口之家……他们有着自己的喜悦、哀愁、梦想、困惑，如同你我一样认认真真地度过每一天。班卓以她特有的细腻、谦逊、好奇，将目光诚恳地投向他者，因而有机会观察、接触形形色色的阿富汗人，近距离地与他们相处相知，建立了短暂却珍贵的缘分与联结。“我写下的并不是一份关于阿富汗的战后调查报告，而只是我看见的在那里生活着的人们的生活。事实上灾难远未结束，人们依然生活在贫困和饥荒之中。可是人们在生活着，并且如同你我一样渴望生活、热爱生活。我所写下的，也许只是一份关于生活的表白。”', '3楼A区', 'Save', NULL, NULL, NULL),
	(132, 'American passerby.jpg', '美国路人', 'American passerby', '刘骁骞', '中国', '2025-2', '旅行', '这本书是一个一直在路上的人收集的脚印，只有他能写就，因为唯有他在场——在驻外生涯的第二个十年，刘骁骞开启了特殊的走遍美国的行程。他踏足将近五十个州，深入人群和险地，穿梭城市和村庄，试图看清那些被笼罩的真相。他是长期徘徊此地的路人，得以冷静而精准地触摸这个国家的伤口：在一触即发的抗议现场，“让美国再次伟大”和“种族平等”是两句并不矛盾的口号，却将美国人推挤在一起，又将他们远远拉开；逃离奴隶棉田的黑人男子永远困在私刑的梦魇中，在民族神话中找不到自己的位置；在一个个残垣断壁的联邦学校旧址，一群人如海底捞针般寻找着埋葬着孩童遗骨的墓地，他们会成功吗？而当刘骁骞不断往返于新闻和历史的现场之间时，他开始回望这十余载的异乡之路，审视内心的初衷。“并不是所有心怀希望的人都抵达了目的地。我们可能去任何地方，却也无处可去。”', '3楼A区', 'Save', NULL, NULL, NULL),
	(133, 'Traveling with Herodotus.jpg', '与希罗多德一起旅行', 'Traveling with Herodotus', '雷沙德·卡普希钦斯基', '波兰', '2025-1', '旅行', '1956年，二十四岁的卡普希钦斯基成为社会主义波兰的一名新闻记者。一年之后，他被“意外地”派往印度，这是他数十年驻外生涯的第一站，在这里他将发现自己一生的志业——前往罕有人至的遥远角落，从那里理解和讲述世界的多样性，并在参差多态的现象中寻找普世真理。在长达四十余年硝烟弥漫、跌宕起伏的全球之旅中，卡普希钦斯基永恒的旅伴是一本希罗多德的《历史》。两千五百年前，这位被誉为“历史之父”的古希腊作家游历了当时已知的世界，描述其部落和国家的多样性，记录了它们的战争与和平。卡普希钦斯基视希罗多德为伟大的先驱和导师，认为他是世界上第一位记者和全球主义者。从中国到伊朗，从尼日利亚到刚果，从安哥拉到亚美尼亚，希罗多德教会这位年轻的记者在不可思议的地方发现故事，并理解他所处的日益全球化的现代世界。在本书中，卡普希钦斯基重温了自己冲破铁幕、走向世界的经历，讲述了他对异域与他者的觉醒之路。本书是两个无畏的旅行者交错时空、穿越世界的回忆，也是一部连贯东西方的非凡编年史：作者亲历与记录的那些塑造了近百年来人类历史的全球暗流，至今仍在涌动。', '3楼A区', 'Save', NULL, NULL, NULL),
	(134, 'Travel Notes on Central Asia.jpg', '中亚行纪', 'Travel Notes on Central Asia', '埃丽卡·法特兰', '挪威', '2022-4', '旅行', '亚历山大的军队将吉尔吉斯斯坦的胡桃木带回欧洲，在塔吉克斯坦和乌兹别克斯坦的雅格诺布谷，人们还在使用丝绸之路上的主要用语——古雅格诺比语，生活遵循着另一种时间节奏。然而这五个国家一直被随意归为一个地区：先是作为亚洲到波斯的古代丝绸之路的广阔地带，又被视为俄罗斯和英国大博弈的舞台。从里海之滨的土库曼斯坦和哈萨克斯坦，向东穿过乌兹别克斯坦、塔吉克斯坦和吉尔吉斯斯坦，这些国家曾经是苏联最远的边境线。社会人类学家埃丽卡·法特兰踏上一段即使是最老练的环球旅行者也很少涉足的旅程，探索五个苏联加盟共和国的成员国，自1991年陆续独立后，它们的现状如何？法特兰穿越土库曼斯坦这个多数世人被禁止进入的国家，前往哈萨克斯坦巨大而荒凉的核爆试验地，在干涸的咸海岸边遇到中国的捕虾人，还遇见自二百年前在吉尔吉斯斯坦平原上生活的德国门诺派教徒。她背包走遍了每个共和国的角落，将这五个中亚国家现在和过去的历史、文化和地理风貌完整介绍给读者，并特别关注每个国家女性生存的现状。《中亚行纪》是一部“穿越中亚的奥德赛”，一位青年人类学家的探索之旅。', '3楼A区', 'Save', NULL, NULL, NULL),
	(135, 'Melancholy Tropics.jpg', '忧郁的热带', 'Melancholy Tropics', '克洛德·列维-斯特劳斯', '法国', '2009-09', '旅行', '《忧郁的热带》是结构人类学宗师列维-斯特劳斯的著名的思想自传，更是人类学历史上的经典著作之一。青年时代，列维-斯特劳斯亲访亚马逊河流域和巴西高地森林，在丛林深处寻找保持最原始形态的人类社会。本书记述了他在卡都卫欧、波洛洛、南比克瓦拉等几个最原始部落里情趣盎然、寓意深远的思考历程与生活体验。列维-斯特劳斯以全新的路径、开放的眼光，根据敏锐的洞察力，辅以生动丰富的想象和细腻的笔触，将这些部落放在了整个人类发展的脉络之中，提出了引人入胜的相互印证和比较研究。《忧郁的热带》是一部对促进人类自我了解具有罕见贡献的人类学、文学及人类思想的杰作。', '3楼A区', 'Save', NULL, NULL, NULL),
	(136, 'How to quickly understand an industry.jpg', '如何快速了解一个行业', 'How to quickly understand an industry', '肖璟', '中国', '2025-8', '职场', '本书旨在帮助读者迅速掌握行业分析方法论，书中详细介绍了行业研究的基本框架和实战技巧。内容涵盖了行业分析的全过程，包括行业生命周期、商业模式、市场规模、竞争格局等关键维度，旨在提升读者的行业研究能力。书中还探讨了如何从不同角度剖析行业外部驱动力，以及如何通过景气度指标预判行业业绩增速。此外，本书还提供了丰富的实战案例和研究方法，并分享了多个利用AI进行投资研究的案例，适合投资者、金融行业从业者、创业者、咨询顾问以及问题解决爱好者阅读，能够帮助他们在投资和职业发展中做出更明智的决策。', '3楼B区', 'Save', NULL, NULL, NULL),
	(137, 'The Effective Executive.jpg', '卓有成效的管理者', 'The Effective Executive', '彼得·德鲁克', '美国', '2023-5', '职场', '本书主要面向企业管理者，探讨企业中的个人管理。这是管理大师德鲁克的经典代表作，书中详述了关于什么是卓有成效的管理者以及如何才能成为卓有成效的管理者。作者开篇即强调“卓有成效是可以学会的”，然后分别介绍了管理者应如何进行时间管理、应如何处理好组织中的人际关系、如何发掘组织成员的优势、如何选择合适的顺序进行决策、如何将个人见解与反面意见都考虑进管理决策中。', '3楼B区', 'Save', NULL, NULL, NULL),
	(138, 'The Power of Negotiation.jpg', '谈判的力量', 'The Power of Negotiation', '里尔登', '中国', '2005-4', '职场', '《谈判的力量》作者在谈判这条路上也是一路磕磕绊绊，不断从失败的经历中获得了宝贵的经验。正因为如此，《谈判的力量》一书才得以另辟蹊径，着眼于语言技巧和策略的紧密结合，正确指导读者使谈判过程按照自己的预期来发展，甚至在面临绝境时柳暗花明。现在，作者已经获得了成功，当你认真读完此书后，相信你也会拥有这种能力，成为一名谈判高手。', '3楼B区', 'Save', NULL, NULL, NULL),
	(139, 'Second job.jpg', '第2份工作', 'Second job', '京宝儿', '中国', '2012-9', '职场', '人人都要谋生，谋生就免不了给人打工，无论你的教育出身如何、在私企外企、做到什么样的职位，给人打工就逃脱不了被人摆布的命运。前公司晴天霹雳般的被收购让翠贝卡明白：所谓好员工，就是在公司好的时候你是幸运儿，在坏的时候你就成了牺牲品；而再好的老板，危机当前，也一定会先跑路再想到你。于是，翠贝卡毅然决然跳槽到了力德中国的市场部。力德是五百强中的好公司，市场部更是风光无限。但只有身处其中的翠贝卡才能领会：在大象间走钢丝，难度在于既不能被大象挤着，还要努力向前走；这样的平衡中求生存，一味妥协就只有被踩死的份儿。翠贝卡终于明白：企业大了就要简单问题复杂化，因为只有这样做起事来大家才最安全。当翠贝卡终于过关斩将、有惊无险地帮硬件部搞定本年度最重要的客户时，期待已久的辉煌和荣誉都似乎已经近在咫尺，而她也完全没有发觉在这些的背后，其实还有一张悄然撑开的网……很多时候，遵守游戏规则远比赢得单子更重要。', '3楼B区', 'Save', NULL, NULL, NULL),
	(140, 'Workplace soft skills.jpg', '职场软实力', 'Workplace soft skills', '亨利·克劳德', '美国', '2014-1', '职场', '《财星杂志》（Fortune）500大企业的顾问克劳德，为读者整理出一套学习「软实力」的方程式。他认为要真正成功，是没有速成的快捷方式，而是扎扎实实地培养「六大内在素质」，成为一个对的人，勇敢地「承担现实的挑战」，从成功迈向卓越。这些内在特质有六个层面，分别是：1.与人联结、建立信任的能力2.能够认清真相的能力3.使命必达的能力4.拥抱问题的能力5.能自我成长并帮助他人成长6.能看到超越自己的价值并以其为人生方向克劳德指出这些环环相扣的内在特质，才是成功人生的关键。他用许多生动的案例，加上长年辅导「成功人士」的经验与洞见，细心刻划出一幅真诚而不煽情的「第五级领导」图像。在竞争激烈的职场环境里，为了成功使得人们渐渐失去人性；本书强调「先做对的人」，才能做对的事。 个人或企业培训最佳读物。', '3楼B区', 'Save', NULL, NULL, NULL),
	(141, 'Early Spring in China.jpg', '早春的中国', 'Early Spring in China', '久保田博二', '日本', '2024-5', '摄影', '1978至1985年期间，日本摄影师久保田博二花了1000多天，几乎走遍了中国全部省份，拍摄了超过20万张彩色照片。他敏锐的政治学眼光注意到中国正处在一段历史的起点。他来到中国，和老百姓一起住人民公社、上旱厕、坐牛车，不动声色地观察中国的方方面面，用镜头记录中国人的衣着、饮食、工作、旅行、娱乐。他同时捕捉到深刻的传统元素和新的表达方式。本书以《早春的中国》精装版为基础，挑选出200余张尤为经典的作品，以更加方便阅读的开本和装帧方式，为读者呈现一个如早春般萌发新生的中国。', '3楼A区', 'Save', NULL, NULL, NULL),
	(142, 'New Photography Notes.jpg', '新摄影笔记', 'New Photography Notes', '宁思潇潇', '中国', '2021-8', '摄影', '《新摄影笔记》是作者在《摄影笔记》的基础上进行悉心编辑整理后的作品。作者结合亲身的拍摄经历，用通俗的语言将摄影技术娓娓道来，使读者真切地感受到学习摄影并不难。本书共分为4章，包含取景、曝光、摄影中的虚实、构图等内容。作者总结了亲身拍摄经验，创造出一套摄影教程体系，以思维导图的形式，引导摄影爱好者进行学习。作者深入浅出的讲解方式，让读者能够快速上手学习摄影技法，并通过实践，不断检验和提高自己的摄影水平。本书适合摄影初学者和摄影爱好者学习参考。', '3楼A区', 'Save', NULL, NULL, NULL),
	(143, 'Magnum Streetwise.jpg', '此时此地', 'Magnum Streetwise', '斯蒂芬·麦克拉伦', '英国', '2021-3', '摄影', '《此时此地：玛格南街头摄影经典》是一部摄影集，也是一部评论集，收录了国际顶尖摄影机构玛格南图片社的超过300幅照片作品。本书以四座城市、数十位摄影大师为中心，对相关的摄影创作进行了深入剖析，既包含理念的解读、历史的梳理，也包括了对具体作品的赏鉴，乃至对创作过程的披露。这是一次对玛格南图片社辉煌传统的深入发掘，也是一场摄影爱好者的饕餮盛宴。', '3楼A区', 'Save', NULL, NULL, NULL),
	(144, 'Spirit of Life.jpg', '生命之灵', 'Spirit of Life', '罗莎蒙德•基德曼•考克斯 / 罗莎蒙德·基德曼·考克斯', '英国', '2015-1', '摄影', '收藏级摄影书！《生命之灵》，集「BBC国际野生生物摄影年赛」举办50周年来最伟大的摄影作品于一册——独具慧心的动植物肖像照、各种动物野外生活的天然状态、自然界某个难以预料的瞬间、濒危生命的无助等，呈现触动人心的自然伟力与生命脆弱。在每张图片相应的图说中，了解鲜活的拍摄故事，认识动物、植物，重温相关事件，带你深入自然。在这些精彩绝伦的照片之后，是世界一流摄影师们观察理解自然的方式，也投射出人与自然在不同时代的相处方式。此书中文版由中国国家地理•图书、英国伦敦自然历史博物馆（NHM）、英国广播公司（BBC）、“野性中国”工作室共同推出。', '3楼A区', 'Lend', '2', '2026-04-05', '2026-04-20'),
	(145, 'Legendary Bresson.jpg', '传奇布列松', 'Legendary Bresson', '克莱蒙·舍卢', '法国', '2015-8-1', '摄影', '本书以全面的视角，回顾了摄影大师的创作生涯。与以往不同的是，书稿将布列松的创作生涯按三个阶段三个部分书回顾了布列松的一生，是配合巴黎蓬皮杜展览的一本具有史料价值的摄影书。《传奇布列松》展现了“绝对之眼”亨利·卡蒂埃-布列松最为知名的代表作和鲜为人知的摄影作品。《传奇布列松》以一种全新的解读视角，摒弃神话和陈词滥调，搜集超过了500件照片、素描、绘画、电影和资料，展现了布列松作品的历史，并通过它展现出那个世纪的历史。亨利·卡蒂埃-布列松持之以恒地融合纪录片的力量和抒情风格的诗意，创造出20世纪最为经典的作品，当之无愧的被世人称为“世纪之眼”、“眼人”，甚至“绝对之眼”。他是第一位在卢浮宫展出作品的摄影师；他是恩斯特·贡布里希所著的权威性著作《艺术故事》（The Story of Art)中登载的唯一一副摄影图片的摄影师；他是光圈出版社出版的“摄影史”系列丛书第一册的主人公；他就是传奇布列松-20世纪最伟大的摄影师之一。', '3楼A区', 'Save', NULL, NULL, NULL),
	(146, 'Shark’s Fin and Sichuan Pepper.jpg', '鱼翅与花椒', 'Shark’s Fin and Sichuan Pepper', '扶霞·邓洛普', '英国', '2018-7', '美食', '这里是中国，一个奇妙的饮食大国。这是关于中国菜的故事，也是一个英国女孩的中国历险记。扶霞一九九四年前往中国长住。打从一开始她就发誓不论人家请她吃什么，不管那食物有多么古怪，她一律来者不拒：第一次与四川料理相遇时的神魂颠倒、亲眼目睹鸡鸭被宰杀时的惊吓、体验千变万化的刀 工、对养生饮食的叹服、品尝珍稀野味时内心的道德两难……透过扶霞的眼睛，我们得以用全新的角度来了解熟悉的中国菜。不同地方的食物拥有其独一无二的气质：川菜的辣带着一丝丝甜，就像悠闲的四川人，总是带着甜甜的体贴；湘菜直接又毫无妥协余地，就跟那里培养出来的领袖人物一样；扬州菜则是太平盛世的食物，温暖而抚慰人心。从四川热闹的市场到甘肃北部荒僻的风景，从福建的深山到迷人的扬州古城，书中呈现了中式料理让人难忘的美妙滋味，也深刻描绘出中西饮食文化差异，且兼具人文观察与幽默趣味。', '3楼A区', 'Save', NULL, NULL, NULL),
	(147, 'No longer eating alone.jpg', '不再是一个人吃饭啦', 'No longer eating alone', '高木直子', '日本', '2021-7', '美食', '全家吃饱饱万岁！！高木老师41岁的时候结婚啦！开始了和丈夫一起的夫妇饮食。两个人会一起逛超市，一起在厨房忙忙碌碌，美好而又惬意。后来高木老师怀孕啦！丈夫仿佛一瞬间开启了厨房技能外挂！42岁时生下了女儿，父母和孩子三个人的生活终于开始了！这是一本充满“美味”的漫画书，记录了从高木与先生两人到一家三口的美食生活变化，一家人探寻、烹饪美食的过程温馨有趣又带一丝感动，让人在美食生活中发现乐趣，找到真切的幸福，给读者带去陪伴与美食的治愈力量。', '3楼A区', 'Save', NULL, NULL, NULL),
	(148, 'While eating, you grow old.jpg', '吃着吃着就老了', 'While eating, you grow old', '陈晓卿', '中国', '2024-1', '美食', '《风味人间》总导演陈晓卿的舌尖寻味故事。一部吃透人生的随笔集，一本掏心掏肺掏胎记的诚意之作。从十七岁出门远行，进京上学，到误打误撞成为一个美食纪录片导演，再到后来成为全国闻名的吃货，漫漫人生路，每个阶段都有与食物相关的记忆。年少时候，好吃是六毛钱的缸贴子，邻居家的西瓜酱，第一次下馆子时把嘴巴烫出泡的萧县羊肉汤，这些是刻在基因里的叫乡愁的东西。一个外地务工人员的北京记忆，是难过时府右街的延吉冷面，寒夜里24小时的马华，以及人手一把肉串，喝着工业啤酒，聊着维特根斯坦的岁月。食物，连接着故乡与世界。每个人都可以在“吃”里找到归属。美食并不小众，它藏在大多数人的一日三餐里。说到底，于勒叔叔的生蚝和父亲病榻前的萝卜丝汆丸子并没有本质区别——你吃到的，就是最好的。', '3楼A区', 'Save', NULL, NULL, NULL),
	(149, 'Nostalgia for food.jpg', '饮食的怀旧', 'Nostalgia for food', '马克·斯维斯洛克', '美国', '2024-10-1', '美食', '在《饮食的怀旧》出版之前，西方世界还没有一部学术著作能系统性地探讨中国人赋予本国地域饮食文化（包括被“规训”的西餐文化）的丰富历史意义。作者将上海这个美食天堂作为观察中国人实践都市生活、探寻地方身份、构建国家认同的田野，认为各种“风味”在这里的此消彼长，既是上海风云变幻中最灵敏的风向标，也是世事沉浮里赓续城市精神的定海针，为研究者观察中国都市文化生活提供了重要切入点。从最早记载上海地区物产的文献，到当下汇聚在这座城市中的地方菜品和风味餐馆，本书不但史料翔实厚重，更确立了一种原创性的研究框架，系统剖析了饮食何以成为中国人追忆过往、活在当下、想象未来的载体，中国人又如何通过对一饮一食的书写和想象，与故土、城市、国家甚至整个世界建立起深刻的联系。', '3楼A区', 'Save', NULL, NULL, NULL),
	(150, 'Cooking Guide.jpg', '料理图鉴', 'Cooking Guide', '越智登代子 / 平野惠理子', '日本', '2018-9', '美食', '本书用生动有趣的小插画告诉你所有生活中的饮食小智慧！聪明地挑选优质美味的生鲜蔬果、灵活地使用方便精巧的烹饪用具、巧妙地运用丰富适宜的香辛调味、了解掌握有趣而多样的烹饪手法、正确保存各类食品而不损失美味与营养……这些料理新手想知道的小秘诀，作者都能透过简单的说明、亲切的插画，让你轻松获得，引领你进入有趣的烹饪世界。具备基本常识，养成良好烹饪习惯，一个厨房新手就能从享受做菜的乐趣开始，慢慢成长为厨艺高手！', '3楼A区', 'Save', NULL, NULL, NULL),
	(151, 'Be personally involved.jpg', '置身事内', 'Be personally involved', '兰小欢', '中国', '2021-8', '经济', '本书是是兰小欢多年教学、调研与研究内容的凝练，将经济学原理与中国经济发展的实践有机融合，以地方政府投融资为主线，深入浅出地论述了中国经济的发展，笔触简练客观，并广泛采纳了各领域学者的最新研究成果。全书分上下两篇。上篇解释微观机制，包括地方政府的基本事务、收支、土地融资和开发、投资和债务等；下篇解释这些微观行为与宏观现象的联系，包括城市化和工业化、房价、地区差异、债务风险、国内经济结构失衡、国际贸易冲突等。最后一章提炼和总结全书内容。通过对中国政治经济体系的论述，作者简明地刻画了地方政府进行经济治理的基本方式，并指出，中国政府通过深度介入工业化和城市化的进程，在发展经济的同时逐步推动了市场机制的建立和完善，以一种有别于所谓发达国家经验的方式实现了经济奇迹。基于对改革历程与社会矛盾的回顾与分析，作者也在书中对当前推进的市场化改革与政府转型进行了解读，帮助读者增进对中国发展现实的把握。', '3楼B区', 'Save', NULL, NULL, NULL),
	(152, 'How an Economy Grows and Why It Crashes.jpg', '小岛经济学', 'How an Economy Grows and Why It Crashes', '彼得·希夫 / 安德鲁·希夫', '美国', '2017-3', '经济', '你一定非常想知道：通货膨胀到底是怎么来的？为什么中国要购买那么多的美国国债？扭转恶化的经济状况是该花钱，还是存钱？为什么有些国家很富有，而另外一些国家却很穷？席卷全球的经济危机又是怎么发生的？如何对经济领域的各种现象进行专业而又生动的分析，是一项艰巨的任务。如何让从9岁到90岁的读者都能通过一本书洞悉日常生活现象背后的经济规律，更是一项几乎不可能完成的任务。《小岛经济学》就是这样一本书，它通过插图、幽默的措辞以及讲故事的平实手法，将经济学从高不可攀的架子上取下来，放回到厨房的餐桌上。它本就该属于那个地方。这个关于鱼、渔网、存钱、借钱的故事揭示了经济是如何运行的，映射出当今经济体制与政策暗藏的漏洞。希夫兄弟以机智幽默的手法阐释了经济增长的根源，贸易、储蓄及风险三者的重要性，滞胀的根源，利率的影响，政府的刺激机制、消费信贷的破坏性本质等问题。这些问题经常被讨论，却常常被误解。对于那些想走出误区，理解经济学基本理论与常识的读者，这本书会带来惊喜。', '3楼B区', 'Save', NULL, NULL, NULL),
	(153, 'Profit for the sake of profit.jpg', '以利为利', 'Profit for the sake of profit', '周飞舟', '中国', '2012-2-1', '经济', '在我们国家，政府对于我们理解经济和社会发展的重要性是毋庸置疑的。改革开放虽然被理解为政府放权、市场成长和发展的过程，但是我们如果对经济和社会不平等的增长进行深层次的讨论，就会发现政府的力量仍然是无所不在、至关重要的。本书讨论的主题是中国当代的政府行为特征及其运作的规律，运用社会学的研究方式探讨地方政府与财政政策之间的关系。', '3楼B区', 'Lend', '2', '2026-04-05', '2026-05-05'),
	(154, 'How Countries Go Broke.jpg', '国家为什么会破产', ' How Countries Go Broke', '瑞·达利欧', '美国', '2025-6-6', '经济', '这本书是桥水基金创始人瑞·达利欧站在全球政治、经济格局变化的重要节点，针对迫在眉睫的债务问题与货币体系崩溃危机，对世界提出的关键警示。通过对过去100年间35个货币市场的研究，他创造性地总结了人类历史反复上演的“大债务周期”及其发展必经的五大阶段，并进一步指出，正是债务/货币体系、国家内部政治、地缘政治、重大自然事件、重大技术突破这五大力量的相互作用，推动了世界和平与繁荣、冲突与萧条的整体秩序变化。从《原则》《债务危机》《原则：应对变化中的世界秩序》到《国家为什么会破产》，瑞·达利欧始终致力于探索事物变化背后那些永恒而普遍的力量。在他看来，无论是个体的生活与工作、组织机构的运行，还是国家与社会的兴衰，都只有理解其运行规律，才能更好地发展与进化。在这本书中，达利欧探究的是信贷、债务对经济、政治乃至国际秩序的周期性影响，他不仅直观地展现了债务是如何导致国家陷入破产乃至政体崩溃等危机的，更给出了“和谐地去杠杆化”的重要财政策略。更关键的是，达利欧在通过本书告诫世人，我们必须重视经验与规律，不能因历史上的重大危机从在未有生之年出现过就轻视了其深层力量，因为它们很有可能即将发生。', '3楼B区', 'Save', NULL, NULL, NULL),
	(155, 'Analysis and Thinking.jpg', '分析与思考', 'Analysis and Thinking', '黄奇帆', '中国', '2020-7', '经济', '本书是黄奇帆教授在复旦大学所做的关于中国经济的讲座合集。本书共收录了12次讲座，根据主题分为“宏观调控”“基础货币”“资本市场”“房地产发展”“对外开放”“中美经贸”六个部分。除此之外，还收录了黄奇帆教授回顾他亲身参与改革开放40年经济发展中的重大事件的4篇文章作为附录。本书所谈的都是改革开放进入新时期以来的重点、热点问题，从现实出发，运用经济学理论总结改革开放的经验，为推进新时期经济改革和扩大开放，提供了深入的思考。本书的研究方法高屋建瓴，采用“问题—结构—对策”的方法，面对各种问题时，先研究问题、分析问题，找到问题结构性的、体制性的、机制性的、制度性的短板，通过改变问题的联系方式、边界条件，使得问题朝着理想的方向和预期的目标转化。全书深入浅出，既有学理上的深刻性，又有丰富的例证，表述生动，保持了演讲的特色，富有吸引力，可读性强，无论是专业研究者还是普通读者，都可以从中受益。', '3楼B区', 'Save', NULL, NULL, NULL),
	(156, 'Critical Leap.jpg', '关键跃升', 'Critical Leap', '刘润', '中国', '2024-7-8', '管理', '不少新任管理者，甚至高级管理者都会有这样的困惑：总觉得自己亲自动手比指挥别人去做效率更高，可控性更强。担心自己的决策被质疑，或者下属的能力与影响力超越自己。有些员工的责任心和表现不尽如人意，却又不得不依赖他们。公司是不是家，领导者跟员工可以做朋友吗？如何塑造一个健康、高效的团队？从个人贡献者到团队管理者，这无疑是职业生涯中的关键一跃。它不仅意味着工作方式的转变，更是一种管理思维的革新。', '3楼B区', 'Save', NULL, NULL, NULL),
	(157, 'Ever-changing and Evergreen.jpg', '常变与长青', 'Ever-changing and Evergreen', '郭平', '中国', '2024-5-1', '管理', '纵观华为过去30多年的发展历程，从代理商到全球领先的ICT基础设施和智能终端提供商，流程、组织和IT三位一体的变革相辅相成，从MRP Ⅱ到I/T S&P、IPD、ISC、IFS，从集成变革到引领数字化转型，华为的发展史就是一部变革史。华为变革始终遵循“业务为首，管理跟上”。通过持续变革，华为已经构建了“以客户为中心、生存为底线”的管理体系，形成组织级能力，持续为客户创造价值，而管理体系本身也成为企业价值的重要组成部分。本书首次披露华为历史上第一个变革规划项目，真实还原华为变革的原动力和决策逻辑，系统阐述变革和管理体系的核心思想，以及企业领导者如何以高超的领导力引领变革。每个企业都面临自己的挑战。本书难以帮助企业家做出战略决策，但企业一旦确定方向，可以借鉴书中的变革实践总结、变革原则和底层逻辑思考，构建组织级能力，支撑企业商业成功、修建企业家心中的“教堂”。', '3楼B区', 'Save', NULL, NULL, NULL),
	(158, 'Administrative Behavior.jpg', '管理行为', 'Administrative Behavior', '司马贺', '美国', '2013-5', '管理', '作为决策理论学派的代表人物，西蒙最重要的作品便是这部《管理行为》。决策制定的过程是组织和管理的核心内容，西蒙在此方面的研究具有开创性，并因此获得诺贝尔经济学奖。本书主要包含两方面的内容：“有限理性”和“满意解”——现实生活中的决策判断取决于有限理性，在这种条件下，人们寻求的是满意解，而非最优解。决策过程理论——组织内部的活动分为经常性（程序化决策）和非经常性（非程序化决策），而经常性活动具有共同的决策过程。', '3楼B区', 'Save', NULL, NULL, NULL),
	(159, 'The Leadership Pipeline.jpg', '领导梯队', 'The Leadership Pipeline', '拉姆·查兰 / 斯蒂芬· 德罗特 / 吉姆· 诺埃尔 / 肯特· 约纳森', '美国', '2024-9', '管理', '《领导梯队》是领导力发展领域的经典之作，畅销20余年，被翻译成12种语言，是企业进行人才选拔、绩效评估和继任规划的重要指导，也是个人职业发展的重要参考。相较之前的版本，第三版的核心价值体现在：1.面对新的商业环境和用工趋势，作者对内容进行了高达80%的优化与更新。2.将领导力的发展从传统的六个阶段转变为五个关键角色：初级经理人、中级经理人、职能负责人、业务一把手以及企业领导人。强调领导者的角色而非职级，使其不仅适用于层级比较多的传统企业，也适用于层级比较少的个体创业者或者中小企业。3.以清晰而系统的方式，明确了不同领导者的工作职责，并指导领导者在不同角色中，如何转变工作理念，合理分配自己的时间，并提升相应的领导技能，从而帮助领导者实现人岗匹配，提升绩效、创造价值。4.更加强调领导梯队的落地应用与实践，尤其是如何在不同的组织类型中帮助领导者达成全面绩效甚至是卓越绩效。《领导梯队》适合每个领导者和有意愿晋升领导的员工阅读，可以有效帮助他们提升个人领导力，进而驱动组织长远健康发展。', '3楼B区', 'Save', NULL, NULL, NULL),
	(160, 'Good to Great.jpg', '从优秀到卓越', 'Good to Great', '吉姆·柯林斯', '美国', '2006-7', '管理', '《从优秀到卓越》描绘了优秀公司实现向卓越公司跨越的宏伟蓝图。作者的前一部著作《基业长青》揭示了公司保持卓越的秘诀，但书中提到的公司自始至终都出类拔萃。对于那些业绩平平的公司，如何才能实现从优秀到卓越的跨越呢？是不是卓越的企业都有所谓的特殊“卓越气质”？发展的瓶颈是不是真的难以突破？针对这一问题，柯林斯和他的研究小组历时5年，阅读并系统整理了6000篇文章，记录了2000多页的专访内容，创建了3.84亿字节的电脑数据，收集了 28家公司过去50年，甚至更早的所有文章，进行了大范围的定性和定量分析，得出了如何使公司从优秀到卓越的令人惊异而振奋的答案。柯林斯发现，公司从优秀到卓越，跟从事的行业是否在潮流之中没有关系，事实上，即使是一个从事传统行业的企业，即使它最初默默无闻，它也可能卓越。柯林斯提出了一整套观点，“只要采纳并认真贯彻，几乎所有的公司都能极大改善自己的经营状况，甚至可能成为卓越公司”。', '3楼B区', 'Save', NULL, NULL, NULL),
	(161, 'Warren and Bill.jpg', '沃伦·巴菲特和比尔·盖茨', 'Warren and Bill', '安东尼·麦卡滕', '新西兰', '2026-1-15', '商业', '本书是著名作家、编剧、电影制作人安东尼·麦卡滕2024年出版的最新传记，近距离观察与描摹了两位长期在全球富豪榜上位列前茅的商业奇才——沃伦·巴菲特和比尔·盖茨，他们聪明过人，性格不同甚至各有固执、又都富可敌国，用彼此最有价值的时间和智力，维系了长达30年的友谊并结成慈善事业联盟，影响了彼此，也深刻影响了金融、科技和全球慈善事业的发展。巴菲特和盖茨相识于1991年，起初甚至没有愿望结交，两个热衷于积累各自财富的人，如何具体影响了对方的内在，并共同决定通过捐赠巨额财富，致力解决全球面临关键的问题——贫困、疾病、不平等？他们和他们的家人、团队，以巨额财富合作的伙伴关系所作的慈善事业，对这个不平等世界上越来越依赖于超级富豪的慷慨和决断的数百万贫困人口，还意味着什么？麦卡滕以睿智而妙趣横生的笔法、犀利而细致入微的观察，对二人的关系进行了有史以来的全面描述，并深入探悉他们如何在一点一滴地改变世界。', '3楼B区', 'Save', NULL, NULL, NULL),
	(162, 'The Art of Spending Money.jpg', '金钱的艺术', 'The Art of Spending Money', '摩根·豪泽尔', '美国', '2025-10-1', '商业', '金钱不是公式里的学问， 而是现实中的艺术。我们习惯于把投资理财当作一门科学，却忽视了其中复杂的心理与行为，导致我们要么把钱花在并不如预期那样带来快乐的事情上，要么错过真正有价值的投资。时隔多年，摩根·豪泽尔又回归到自己最擅长的财富、人性和幸福话题。他在书中横跨心理学、投资、历史等多视角，以案例故事的讲述方式，为我们娓娓道来了20个关于金钱的智慧。《金钱的艺术》并不会提供给你一刀切的解决方案，而是让你了解自己与金钱的关系如何影响你的决策，以及如何重塑这种关系。即使你没有接受过专业金融教育，没有投资理财技巧，你也可以凭借对金钱的良好认知，让金钱为你所用，让你的生活更独立自由。', '3楼B区', 'Save', NULL, NULL, NULL),
	(163, 'Zero to One.jpg', '从0到1：开启商业与未来的秘密', 'Zero to One', '彼得·蒂尔 / 布莱克·马斯特斯', '美国', '2015-1-1', '商业', '硅谷创投教父、PayPal创始人作品，斯坦福大学改变未来的一堂课，为世界创造价值的商业哲学。在科技剧烈改变世界的今天，想要成功，你必须在一切发生之前研究结局。你必须找到创新的独特方式，让未来不仅仅与众不同，而且更加美好。从0到1，为自己创造无限的机会与价值！Paypal创始人、Facebook第一位外部投资者彼得•蒂尔在本书中详细阐述了自己的创业历程与心得，包括如何避免竞争、如何进行垄断、如何发现新的市场。《从0到1》还将带你穿越哲学、历史、经济等多元领域，解读世界运行的脉络，分享商业与未来发展的逻辑，帮助你思考从0到1的秘密，在意想不到之处发现价值与机会。揭开创新的秘密，进入彼得•蒂尔颠覆式的商业世界：创新不是从1到N，而是从0到1', '3楼B区', 'Save', NULL, NULL, NULL),
	(164, 'Decoding Business Models.jpg', '解码商业模式', 'Decoding Business Models', '曾小军', '中国', '2023-11', '商业', '任何产品或生意都源于一个好的想法，但如何将一个想法转化成一个好的商业结果？你需要一个好的商业模式。本书抛开传统定义，从系统论的视角重新定义商业模式，并提供了许多洞察商业本质的思维、理论、方法和工具。本书分为两部分，第一部分详细阐述了商业模式的全新定义、底层结构和运行机制；第二部分揭示了商业模式高效运行必备的 4 大动力系统，它们是商业模式在面对风险和不确定性时实现持续进化的重要动力系统。无论你是创业者、企业管理者、个人IP打造者、产品经理，还是追求商业模式创新的终身学习者，本书都能帮助你从根本上实现认知升级，掌握洞察本质的底层逻辑，学会从顶层设计者的视角来构建核心竞争力。', '3楼B区', 'Save', NULL, NULL, NULL),
	(165, 'The Philosophy of Retail.jpg', '零售的哲学', 'The Philosophy of Retail', '铃木敏文', '日本', '2014-12-1', '商业', '全球最大的便利店7-11便利店创始人——铃木敏文，结合40多年零售经验，为你讲述击中消费心理的零售哲学。铃木敏文的很多创新，现在已经成为商界常识，本书把那些不可思议的零售创新娓娓道来。关于零售的一切：选址、订货、销售、物流、管理……他一次又一次地在一片反对声中创造出零售界的新纪录。翻开本书，看铃木敏文如何领导 7-Eleven 冲破层层阻碍，成为世界第一的零售哲学。', '3楼B区', 'Save', NULL, NULL, NULL),
	(166, 'Twenty-Five Lectures on Financial Economics.jpg', '金融经济学二十五讲', 'Twenty-Five Lectures on Financial Economics', '徐高', '中国', '2018-7-1', '金融', '《金融经济学二十五讲》是作者在北京大学数年讲授金融学课程所结出的果实。本书主要内容由均衡资产定价、无套利资产定价以及金融摩擦三部分组成，涉及现代金融经济学的所有重要方面。本书以本科生能接受的数学程度，平易近人地介绍了现代金融学理论的核心内容，并尤其注重透视理论背后的金融学思想，揭示了现代金融理论体系中澎湃的生命律动。本书的最大特点是运用了适用于本科生程度的数学工具，既不太过简单，也不太过专业，填补了市场同类教材的空白。本书既可作为本科生程度读者的金融学入门教材，也对研究生或MBA程度的读者有参考意义。', '3楼B区', 'Save', NULL, NULL, NULL),
	(167, 'Finance in America.jpg', '美国金融体系', 'Finance in America', '凯文·R·布莱恩 / 玛丽·普维', '美国', '2022-7', '金融', '本书介绍了从19世纪至今美国金融体系的起源、理论基础、核心模型、法规制度，以及其关键特征，如公司会计准则、美联储系统、风险管理实践，并进一步探讨了凯恩斯主义、新古典主义、新自由主义、货币经济学等对美国金融体系的影响，以及创新型金融产品在美国金融体系的转型中发挥了哪些关键性作用等。这些因素驱动了美国金融体系的兴起、发展、转型和创新。本书提供了过去一个多世纪美国经济学家开发的经济和金融模型的知识谱系，有助于人们对金融在美国和全球经济中的重要性进行更深入的讨论。', '3楼B区', 'Save', NULL, NULL, NULL),
	(168, 'The gradually approaching financial cycle.jpg', '渐行渐近的金融周期', 'The gradually approaching financial cycle', '彭文生', '中国', '2017-6', '金融', '过去40年在金融自由化、政府对私人财富隐性担保、宏观政策过度依赖信贷的大环境下，全球范围内金融的顺周期性成为驱动经济中期波动的重要力量，甚至带来了金融危机。有别于实体与金融相割裂的传统视角，本书在金融周期的分析框架下，聚焦信用和房地产相互促进的机制，联系金融和实体、总量和结构，提供一个从金融看宏观经济的全景式分析。中国在经历第一个金融周期，上半场的繁荣已经持续了10年，房地产和信用（债务）过度扩张损害潜在增长率，扭曲经济结构，加剧贫富分化和环境污染，不可持续。央行加息（紧货币）、监管加强（紧信用）、结构改革包括税制调整，独立或合力作用，将触发金融周期拐点。下半场调整意味着房地产去泡沫、非政府部门去杠杆，经济增长在一段时间面临下行压力，但结构改善。寄希望于刺激增长和通胀去杠杆、家庭加杠杆扶持企业降杠杆、只减债务不减资产泡沫、汇率贬值消化高房价等都是不现实的。进入金融周期下半场后，理想的宏观政策是“紧信用、松货币、宽财政”，但这是技术层面的调整，不改变金融的基本结构。', '3楼B区', 'Save', NULL, NULL, NULL),
	(169, 'History of World Finance.jpg', '世界金融史', 'History of World Finance', '板谷敏彦', '日本', '2022-8', '金融', '通过人类金融史的一个个灿烂的瞬间，本书串联起了一幅战争、货币、债务、财富与人性的壮阔画卷。可以说，我们所熟悉的历史事件的背后都有金融的影子，而正是这一串串事件构成了今天我们复杂纷呈的金融市场。本书能帮你读懂金融世界的来龙去脉，了解各种金融产品的本质。', '3楼B区', 'Save', NULL, NULL, NULL),
	(170, 'Beating the Street.jpg', '战胜华尔街', 'Beating the Street', '彼得·林奇 / 约翰·罗瑟查尔德', '美国', '2010-4-1', '金融', '《战胜华尔街》既是一个世界上最成功的基金经理的选股回忆录，又是一本难得的选股实践教程和案例集锦。它既可以作为《彼得·林奇的成功投资》的进阶读物，也可以作为其实操案例，二者结合来读，获益最大。', '3楼B区', 'Save', NULL, NULL, NULL),
	(171, 'Investment Opportunities from a Global Perspective.jpg', '全球视野下的投资机会', 'Investment Opportunities from a Global Perspective', '时寒冰', '中国', '2025-8', '投资', '时寒冰先生25年最新力作，讲述多年来的研究成果，在跟随趋势做投资的总纲领下，总结大量实用且符合常识的思考与方法，最终做到快乐投资。例如书中开篇就写道所谓“势”，就是资本、资源、人口等流动的方向，从趋势的角度进行解读，打破传统投资逻辑的束缚，以更高维的角度来看待投资这件事，读之令人 豁然开朗。 所谓授人以鱼不如授人以渔，本书最珍贵的地方是通过大量的数据和基础的逻辑推理，找到投资机会。这对读者而言亦是一次难得的思维训练和提升，为读者将来规划自己的投资奠定了坚实的基础。', '3楼B区', 'Save', NULL, NULL, NULL),
	(172, 'Investment Lesson 1.jpg', '投资第1课', 'Investment Lesson 1', '孟岩', '中国', '2023-2', '投资', '《投资第1课》是一本为普通投资者写就的入门读物。现代社会是一个分工高度专业化和精细化的社会，任何一个人都不可能、也没必要去学习所有的知识——生病了，找医生；有纠纷，找律师。投资是不是也应该如此？相比其他行业，投资行业有个很大的不同：作为用户，在绝大多数时间里，都无法评价产品，以及相应服务的好坏。“短期涨得好，不代表长期能赚钱。我们看到的投资收益，有可能是牛市带来的，有可能是短期市场风格带来的。如果不具备基本的金融素养（Financial Literacy），我们就无法辨别这个结果是能力还是运气，更无法在将来获得这个收益。更重要的是，即使我们选择了好的投资产品，如果不具备基本的投资知识，也可能会经历’贪婪和恐惧‘，在关键时刻无法拿住”，作者如是说。', '3楼B区', 'Save', NULL, NULL, NULL),
	(173, 'The Power Law.jpg', '风险投资史', 'The Power Law', '塞巴斯蒂安·马拉比', '英国', '2022-12-1', '投资', '如果你只能读一本关于风险投资的书，那么请读这本。这是风险投资真实运作的故事。在很多人的印象里，风险投资一直是神话般的存在，掌握着改变风向和创造巨额财富的密码。这本书可以帮助你打开风险投资神话般的外壳，如穿越时间的虫洞般，窥见其中关于人性、时代、财富甚至资本善恶的秘密。它将硅谷传奇企业与人物的故事与对风投行业发展脉络的洞见交织起来，首度权威揭秘硅谷指数级技术革命背后的千亿资本运作实情。它揭示了驱动风投行业、整个硅谷乃至整个世界的基本原理——指数法则。风投的蕞大秘密是蕞佳投资所创回报等于或超过基金其他部分的收益总和。成功虽是罕见的，但成功所带来的影响力却是变革性的。也正因如此，风险投资家总是有着异乎常人的洞察力和直觉,有着对于风险的偏好和对失败的宽容,他们面对巨大的不确定性敢于大举押注。对于他们而言，那些看似疯狂的梦想，越是大胆、越是看起来不可能，就越有价值。风险投资不只是一个生意，也是一种能带来社会进步的方法、思维方式和哲学，通过大胆支持勇敢的创新者来更好满足人类的需求和欲望，甚至可以说，风险投资本身就是巨大的创新。', '3楼B区', 'Save', NULL, NULL, NULL),
	(174, 'What I Learned About Investing From Darwin.jpg', '我从达尔文那里学到的投资知识', 'What I Learned About Investing From Darwin', '普拉克·普拉萨德', '印度', '2025-2', '投资', '投资行业正处于危机状态。绝大多数股票基金经理无法长期跑赢市场，导致大量资金从主动型基金流向被动型基金。投资者应该从哪里寻找新的投资途径？普拉萨德凭借其在投资领域取得的长期高额回报，分享了其独特的投资灵感来源——进化生物学。他深入挖掘达尔文学说的核心理念，将自然界的鲜活案例与自身丰富的投资实践紧密结合——熊蜂的生存策略如何帮助我们接受可能会错过特斯拉的决策；驯服银狐的实验揭示了成功企业应具备什么样的特征；为什么一只小青蛙模仿一个更大的竞争对手的呱呱叫声可以揭示公司不诚实的迹象……普拉萨德以生动有趣且富有洞察力的文笔，巧妙地将达尔文的理论与投资实践相联系，以引人入胜的方式呈现给读者。在成功的进化策略的指引下，他详细阐述了多个获取长期收益的反直觉原则，并强调良好的视角与思维方式远比单纯的技术和技能更为重要，知识与技巧只是实现目标的手段。他的观点基于对失败教训的深刻反思和成功经验的总结提炼，为投资者提供了极具价值的借鉴。在算法与人工智能日益应用于财务目标实现的当下，普拉萨德的投资思想有望在未来发挥更大的价值，帮助投资者在复杂多变的市场中稳健前行。', '3楼B区', 'Save', NULL, NULL, NULL),
	(175, 'The Intelligent Investor.jpg', '聪明的投资者', 'The Intelligent Investor', '本杰明•格雷厄姆', '美国', '2016-3', '投资', '《聪明的投资者》是一本证券投资实务领域的世界级和世纪级的经典著作，自从1949年首次出版以来，在股市上一直被奉为“股票投资圣经”。本修订版在完整保留格雷厄姆原著1973年第4版的基础上，由贾森·兹威格根据近40年尤其是世纪之交全球股市的大动荡现实，对格雷厄姆的原著作了大量的注释和章后点评，进一步检验和佐证了价值投资理论。股神巴菲特为本书撰写的序言和评论是这个版本的又一个亮点。本书首先明确了“投资”与“投机”的区别，指出聪明的投资者当如何确定预期收益。本书着重介绍防御型投资者与积极型投资者的投资组合策略，论述了投资者如何应对市场波动。本书还对基金投资、投资者与投资顾问的关系、普通投资者证券分析的一般方法、防御型投资者与积极型投资者的证券选择、可转换证券及认股权证等问题进行了详细阐述。本书主要面向个人投资者，全面体现了格雷厄姆的价值投资思想，为普通人在证券投资策略的选择和执行方面提供了重要指导。', '3楼B区', 'Save', NULL, NULL, NULL),
	(176, 'Marketing Management.jpg', '营销管理', 'Marketing Management', '菲利普·科特勒 / 凯文·莱恩·凯勒 / 亚历山大·切尔内夫', '美国', '2022-9-5', '营销', '《营销管理》第16版是世界领先的营销学权威之一，西北大学凯洛格管理学院国际市场营销杰出教授（荣誉教授）菲利普·科特勒的最新作品版本。这本书已畅销全球55年，被翻译为20多种语言，被誉为“营销圣经”。《营销管理》第16版有新内容：重写每章导引，重要的架构调整和新增内容，适应新材料，重组老材料；具有新形式：每章节插入开篇故事，章节结尾插入营销洞察栏、营销焦点框；有新洞察：针对单个特定营销主题进行更详细的论述，以提供深入理解，加深读者理解；有新体验：通过多媒体、动态、互动的阅读体验，提升读者阅读兴趣；有新作者，新加入三作亚历山大·切尔内夫在营销战略、品牌管理、消费者决策和行为经济学等领域是公认的学术思想领袖。本书分为七个部分，分别从营销管理的基本原理、了解市场、制定一个成功的营销战略、设计价值、传播价值、渠道价值、管理增长等七个方面展开阐述。', '3楼B区', 'Save', NULL, NULL, NULL),
	(177, 'Cultural Strategy.jpg', '文化战略', 'Cultural Strategy', '道格拉斯·霍尔特 / 道格拉斯·卡梅隆', '美国', '2013-8', '营销', '《蓝海战略》之类的当今最具影响力的品牌战略著作认为，创新在于产品功能的突破。然而，作者通过对万宝路、星巴克等数百个品牌案例的分析，以及与相关品牌管理者和消费者的访谈，发现了功能主义创新模式的缺陷，那就是忽略了社会和历史变迁产生的意识形态机遇。作者花费八年的时间，运用“实验”的方法，创立了足以弥补主流创新模式欠缺的“文化战略”理论，并将此理论反复应用于品牌推广实践，成功重塑了多个垂死挣扎的品牌，也成功地让数家新设小企业迅速成长为品牌价值达数亿美元的大企业。在实践的基础上，作者确立了文化创新模式以及适用于文化创新的组织形式。这是一部具有里程碑意义的品牌战略的宝典。', '3楼B区', 'Save', NULL, NULL, NULL),
	(178, 'Chip Marketing.jpg', '芯片营销', 'Chip Marketing', '林宏森', '中国', '2014-8', '营销', '《芯片营销》是国内第一本面向集成电路芯片领域的市场营销专著。集成电路（IC）从上世纪50年代发明以来，极大地改变了我们的世界和生活，几乎一切的电子产品都离不开集成电路芯片。每年我国进口的电子芯片就有两千亿美元之多，超过了石油的进口。在中国，芯片行业是一个正在蓬勃发展的行业，这个行业中，活跃着数以万计的公司企业和无数从业人员，尤其是市场销售人员，占据着非常大的比例。《芯片营销》系统性介绍了芯片行业的基本概况，对芯片产品的市场销售基本技巧给予深入浅出的阐述，本书能够帮助芯片行业的销售者快速入门，领会芯片销售的基本奥秘。本书共分为八章，内容包括：芯片行业基本情况概述、芯片原厂的产品市场营销管理、代理商分销商的销售运营和管理、销售人员心态和基础技能训练 、重要的销售技巧 、合同报告等文书写作、处理特殊问题的技巧、芯片的互联网营销和电子商务初探。从最基础的行业知识普及，到具体的客户拜访推销技巧，以及产品定价策略，客户管理，FCST预估，以及特殊问题处理等方面均有详细的阐述。', '3楼B区', 'Save', NULL, NULL, NULL),
	(179, 'Sell wheels.jpg', '卖轮子', 'Sell wheels', '杰夫 科克斯 / 霍华德 史蒂文斯', '美国', '2010-1', '营销', '《卖轮子:选择最佳营销方式》内容简介：故事中的主人公麦克斯从发明轮子到创立公司，每一阶段的发展都会遇到类似的问题。先知者则带领麦克斯拨开营销的层层迷雾，发现营销的真谛。如果你是销售人员，这本书将帮你把握自己的销售风格、选择适合的销售工作。如果你是营销管理者，这本书将帮你制定营销策略、选择销售人员。如果你在经营企业，这本书将帮你理解所处的行业发展阶段、找准自身定位。如果你是消费者，这本书将带你进入妙趣横生的营销世界，了解哪种类型的销售人员更能满足你的需求。让我们一起跟随先知者的脚步，踏上愉快的营销之旅吧！', '3楼B区', 'Save', NULL, NULL, NULL),
	(180, 'Hooked.jpg', '上瘾', 'Hooked', '尼尔·埃亚尔 / 瑞安·胡佛', '美国', '2017-5', '营销', '《上瘾》揭示了很多让用户形成使用习惯，甚至“上瘾”的互联网产品服务背后的基 本设计原理，告诉你怎样打造一款让用户欲罢不能的产品。作者根据自己多年的研究、咨询及实际经验，提出了新颖而实用的“上瘾模型”（Hook Model），即通过四个方面来养成用户的使用习惯。通过连续的“上瘾循环”，让用户成为“回头客”，进而实现循环消费的终极目标，而不是依赖高昂的广告投入或泛滥粗暴的信息传播。本书专为产品经理、设计师、市场销售人员、广告创意者打造，每一位跟用户行为打交道的人，都值得将其奉为案头必备指南。对于想要了解行为设计科学的读者来说，这本书也将让你对自己、对当前的热门产品有更深刻的认识。', '3楼B区', 'Save', NULL, NULL, NULL),
	(181, 'A Confession of an Advertiser.jpg', '一个广告人的自白', 'A Confession of an Advertiser', '大卫·奥格威', '美国', '2003-07-01', '广告', '在这本书中，奥格威坦诚地介绍他本人和奥美广告公司的宝贵经验，包括怎样经营广告公司、怎样争取客户、怎样维系客户，怎样当一个好客户，怎样撰写有效的文案、怎样制作上乘的电视广告等等。', '3楼C区', 'Save', NULL, NULL, NULL),
	(182, 'Persuasive Advertising.jpg', '广告说服力', 'Persuasive Advertising', '斯科特·阿姆斯特朗', '美国', '2016-8', '广告', '《广告说服力》总结了近3000项实证研究的结果和50本广告类图书的精华，在实证证据的基础上提出195条广告原理，条分缕析，事理结合，操作性强。《广告说服力》共分三大部分。导入部分介绍了广告行业的现状、基于证据的原理提出过程、证据类型的强弱排序、广告原理的适用条件等内容。广告原理部分为全书主干，分别从十个广告本质问题入手：信息、影响、情感、单纯曝光、抵制、接纳、讯息、注意力、静态媒介、动态媒介等，其下再分若干主题，全面而系统地论述了195条广告原理，每条原理都进行了案例分析、限制了适用条件、检查了效果证据，便于读者理解与运用。总结部分探讨了如何在运用广告原理时发挥创造力，如何评估广告并给出了简短的结论。最后在9个附录中分别就一些广告热点问题进行了有针对性的探讨。《广告说服力》是每一位设计、投放、研究和评估广告人士的指导用书，能帮助广告主切实改善广告效果，增强广告说服力，提高广告的购买转化率。《广告说服力》也适合广告专业的师生和广大普通读者研读，帮助他们深入理解广告产生说服力的效果与规律，这些广告说服原理同样适用于我们广泛的社会生活。', '3楼C区', 'Save', NULL, NULL, NULL),
	(183, 'Mad Men.jpg', '广告狂人', 'Mad Men', '理查德·克什鲍姆', '美国', '2014-1-1', '广告', '在人们都为金钱疯狂的20世纪70年代和80年代，理查德·克什鲍姆引爆了广告业的狂潮。26岁的他和29岁的合作伙伴约翰尼·邦德共同创立了克什鲍姆·邦德合伙公司。这本书里有爆炸头、绿色蛇皮牛仔靴、法式袖口，以及关于如何刺激消费者购物的种种设想。《广告狂人》是一部像过山车一样跌宕起伏的商业回忆录，记录了克什鲍姆如何走到今天这一步、他在前进道路上犯的错，以及他为什么只有两项黄金法则——这两项法则有时会发生冲突，但最后让他取得了举世瞩目的成功。《广告狂人》是一次真正的冒险之旅。作者在广告业界留下了不可磨灭的独特标记，使广告成为了经济领域的重要组成部分，他的名字是成功的代名词。你将跟随这位“奇迹之子”领略广告界的风云变化。', '3楼C区', 'Save', NULL, NULL, NULL),
	(184, 'Leverage the momentum.jpg', '借势', 'Leverage the momentum', '金枪大叔', '中国', '2022-6-1', '广告', '《借势》是广告鬼才金枪大叔从业20年实战心得，以弱胜强的128条黄金法则、10大借势思维、千亿品牌操盘的核心秘诀，首次倾囊相授。“语言是钉子，视觉是锤子”，打造多个品牌爆款广告的背后，是他强大的洞察力和与众不同的思维方式。价值500万的知识，一字一句都是金。', '3楼C区', 'Save', NULL, NULL, NULL),
	(185, 'Influence.jpg', '影响力', 'Influence', '罗伯特·B.西奥迪尼', '美国', '2010-9-20', '广告', '自1986年出版以来，作为获得美国心理协会、美国心理学基金会年度大奖提名的西奥迪尼经典著作，本书已经成为史上最强大、最震摄人心、最诡谲的心理学畅销书，24年来，被翻译成26种文字广为传播，全球销量超过300万册。时至今日，本书仍位列亚马逊总排行榜Top400之中，并雄踞消费者行为学和应用心理学类畅销书榜首。也正是在这个畅销版本的基础上，西奥迪尼才衍生出后来为斯坦福大学等多所名校所采用的教材版本。 没有专家解读，没有每章导读，这是一本最原汁原味的《影响力》，醇厚甘甜，久而弥笃。阅读本书仿佛是与西奥迪尼面对面，让你可以细细聆听，在定格的经典中体味无孔不入的影响力。 本书由斩获国家级图书大奖”文津奖”的《牛奶可乐经济学》的译者担纲翻译，语言生动流畅，意趣盎然，西奥迪尼式的诡谲与雄辩惟妙惟肖，跃然纸上。', '3楼C区', 'Save', NULL, NULL, NULL),
	(186, 'How to Read a Tree.jpg', '如何阅读一棵树', 'How to Read a Tree', '特里斯坦·古利', '英国', '2025-3', '科普', '树木渴望告诉我们很多事情。它们既想告诉我们关于土地、水分、人类、动物、天气和时间的故事，也想同我们分享它们自身所经历的痛苦与喜悦。树会讲故事，但只讲给那些知道如何阅读的人听。在《如何阅读一棵树》一书中，作家古利为我们揭示了树木隐藏的线索：树的枝叶、树皮、树干、花朵以及树桩的密语。读懂它们，就能读懂树木的生命故事，学会寻找自然的方向。如果你在树叶上看到一条明显的白线，这表明附近有水源。过不了多久，你就会看到河流。如果你在树干底部看到一堆低矮的嫩枝，这表明树木遇到了大麻烦。除了南侧浓密的树枝，树叶的颜色、树根也能为我们指引方向。这世界上没有两棵一模一样的树。只要我们细心观察它们之间的差异，就能解读树木经历的非凡的生命故事。', '3楼C区', 'Save', NULL, NULL, NULL),
	(187, 'The Treeline.jpg', '极北森林', 'The Treeline', '本·罗伦斯', '英国', '2025-2', '科普', '“林木线”是生态学、环境学及地理学中的概念。它显示了树的生长极限。在过去五十年里，全球北方森林一直在向北迁移。英国知名非虚构作家本·罗伦斯在2018到2020年间，穿越加拿大、西伯利亚、挪威、格陵兰岛和阿拉斯加，具体追踪了六种能够经受高纬度严寒的树种。他还与生态学家和博物学家交谈，拜访当地居民，观察树木，讨论巨大的环境变化。这是一次充满惊奇和敬畏的旅程。本书结合报告文学与最新的科学研究，讲述了即将消失的最后一片森林，以及它对地球上所有生命的未来意味着什么。', '3楼C区', 'Save', NULL, NULL, NULL),
	(188, 'The Order of Time.jpg', '时间的秩序', 'The Order of Time', '卡洛·罗韦利', '意大利', '2019-6', '科普', '为什么我们记得过去，而非未来？时间“流逝”意味着什么？是我们存在于时间之内，还是时间存在于我们之中？卡洛·罗韦利用诗意的文字，邀请我们思考这一亘古难题——时间的本质。在我们的直觉里，时间是全宇宙统一的，稳定地从过去流向未来，可以用钟表度量。可罗韦利向我们揭示出一个奇怪 的宇宙，在这里，时间的特质一一坍塌，在最基本的层面上，时间消失了。他告诉我们，我们对时间流逝的感知，取决于我们的视角……', '3楼C区', 'Lend', '3', '2026-04-05', '2026-05-05'),
	(189, 'Does God play dice.jpg', '上帝掷骰子吗', 'Does God play dice', '曹天元', '中国', '2019-6-1', '科普', '本书回顾量子论从无到有发展的风云录，从18世纪开始，直到21世纪，一批科学巨人开始颠覆传统物理学大厦，为了宇宙的终极理论而战，大大改变了人类发展的历史。再现量子物理一路的荆棘与荣光，展现科学激动人心的魅力，这部量子物理史，足以唤起你对世界的全部好奇！', '3楼C区', 'Save', NULL, NULL, NULL),
	(190, 'The Oceans.jpg', '海的呼吸', 'The Oceans', '埃尔科·J.罗林', '荷兰', '2026-1', '科普', '我们居住在一颗蓝色星球之上，其中70 %以上的面积被海洋覆盖。我们常说热 爱大海，却鲜少追问：在这片蔚蓝之下，在亿万年的时间里，有着怎样的历史？其实，科学家早已揭开海洋的诸多秘密：自 44 亿年前诞生以来，它不仅是生命最初的诞生之地，更是地球气候系统的调节器、全球最大的碳储存库。从冰封万里的雪球地球，到二叠纪末的生物大灭绝；从盘古超大陆的分裂漂移，到如今全球变暖的严峻挑战——《海的呼吸》将海洋演化过程中的重大事件娓娓道来，带我们穿越亿万年时光，见证海洋与气候、地球、生命的深深羁绊。更重要的是，我们将在书中了解到：海洋的温度变化与碳循环的关系，早已悄悄决定了人类的命运。正是海洋对大气中碳的吸收、对各种能量的转化，才造就了地球稳定的气候，并孕育出生命的奇迹。埃尔科·J.罗林提醒我们，海洋看似广阔无垠、取之不尽，实则脆弱不堪。近500年来，人类无休止的资源掠夺和无所顾惮的碳排放，正在将海洋推向崩溃的边缘，若我们无视历史，则终将面临无可挽回的绝境。', '3楼C区', 'Save', NULL, NULL, NULL),
	(191, 'A Brief History of Intelligence.jpg', '智能简史', 'A Brief History of Intelligence', '麦克斯·班尼特', '美国', '2025-2', '科学', '过去10年间，曾属科幻范畴的AI能力已悄然成为现实。AI如今能模仿莎士比亚的文风作诗，能自动驾驶汽车，甚至通过司法考试。然而，现代AI系统仍存在巨大局限——人类大脑轻而易举完成的认知壮举，AI至今无法复现。为何AI能击败国际象棋大师，却摆不好洗碗机中的餐具？AI企业家麦克斯·班尼特提出了令人信服的论断：答案深藏于人脑进化的10亿年历史中，而这段历程充斥着无数试错、灾难与精妙的创新。我们的大脑蕴藏着待解的进化密码——AI的未来或许正系于此。在《智能简史》中，班尼特架起神经科学与AI的桥梁，讲述大脑的进化史诗，并揭示这一历程如何塑造下一代AI革新。通过独创性框架，他将庞杂的进化史凝练为“五次突破”，每次突破都标志着人脑进化的重要跃迁，并为人类智能的核心谜题注入全新解读。结合AI科学的前沿进展，班尼特指出了当前AI系统在哪些领域已比肩或超越人脑，又在何处仍显不足。本书广受当代顶尖神经科学家赞誉，班尼特将进化神经科学与尖端AI研究熔铸成一部引人入胜的非凡之作。《智能简史》以恢宏的视野与颠覆性的洞见证明：唯有以远古智慧为灯塔，AI方能突破未来的可能性边界。', '3楼C区', 'Save', NULL, NULL, NULL),
	(192, 'The Logic of the World.jpg', '世界的逻辑', 'The Logic of the World', '马兆远', '中国', '2025-9', '科学', '在这个AI颠覆认知、信息爆炸冲击理性的时代，我们比任何时候都更需要回答：当“确定性”成为稀缺品，如何在混沌中锚定方向？如何用理性思维突破认知局限，做出理性的决策？本书以“如何用理性应对不确定性”为核心，贯穿古希腊哲学到量子力学的前沿探索，打破学科壁垒：从亚里士多德逻辑的诞生到哥德尔不完备定理对“完美真理”的终结，从量子力学颠覆“确定因果”到混沌理论揭示“预测极限”，从贝叶斯统计改写“认知逻辑”到熵增定律破解“躺平陷阱”——马兆远用“科学史+思维进化”的双重视角，还原理性与科学的本质：它们不是“终极答案”，而是人类应对未知的“思维工具”。书中没有晦涩公式，只有直击痛点的方法论：当信息过载时，如何用逻辑筛出关键变量？当未来不可测时，如何用概率思维优化选择？当“确定性依赖”成瘾时，如何借混沌理论拥抱灵活性？无论你是被职业选择困扰的年轻人、在商业浪潮中寻找方向的创业者，还是渴望提升思维深度的终身学习者，这本书都将为你提供一套“应对不确定性的顶层思维”：它既回溯人类2500年的思维进化史，又直指AI时代的生存法则——接受不确定性的常态，在理性与试错中迭代认知，最终将“未知”转化为成长的燃料。', '3楼C区', 'Save', NULL, NULL, NULL),
	(193, 'Philosophy of Science.jpg', '科学哲学导论', 'Philosophy of Science', '亚历克斯·罗森堡 / 李·麦金太尔', '美国', '2023-6-3', '科学', '科学哲学是哲学的一个分支，它试图阐明科学研究的本质——观测程序、论证方式、表述与计算方法、哲学假设，以及从认识论、形式逻辑、科学方法论和形而上学的角度评价其有效性的依据。本书介绍了科学哲学的所有主题，包括科学与哲学的关系，科学说明的定义和模型，定律的必然性和说明力，科学理论的建构和运作，科学史的挑战与科学革命的范式转变，后现代主义与“科学大战”，以及女性主义、相对主义等科学哲学面临的困难。作者对该领域的现状进行了全面、复杂的介绍，试图更好地理解科学的性质、方法和限度的读者可以从中得到有益的启迪。', '3楼C区', 'Save', NULL, NULL, NULL),
	(194, 'Reality Is Not What It Seems.jpg', '现实不似你所见', 'Reality Is Not What It Seems', '卡洛·罗韦利', '意大利', '2017-11', '科学', '世界的基本组成部分是什么？时间和空间真的存在吗？现实（Reality）的本质是什么？现象级科普畅销书《七堂极简物理课》作者、意大利理论物理学家卡洛·罗韦利以优雅易懂的方式带我们踏上这场探索现实之旅：从德谟克利特到爱因斯坦，从法拉第到引力波，从经典物理到量子引力……通过介绍现实的概念是如何随时间变迁的，今天的物理学家又是如何理解宇宙的结构的，他为我们提供了比《七堂极简物理课》更深入的理论解释。', '3楼C区', 'Save', NULL, NULL, NULL),
	(195, 'The Blind Spot.jpg', '何为科学', 'The Blind Spot', '亚当·弗兰克 / 埃文·汤普森 / 马塞洛·格雷斯', '美国', '2025-4', '科学', '本书从科学的历史出发，梳理现代科学所取得的辉煌成就和对世界的巨大改变，探寻科学的本质和真义，反思关键问题:今日科学为何能取得如此成功?我们为取得这种成功是否在过去付出了某些代价?未来的科学又应如何发展才能真正造福于人类?自启蒙运动以来，人类一直依靠科学来探寻世界的真相，却在某种程度上忽视了人类的感官经验。这种造成科学与经验脱节的“盲点”隐藏在关于时间、宇宙、量子物理、生命、人工智能和思维、意识等诸多科学悖论背后，既创造了今日的人类世界，也造成了气候变化、生境破坏、全球性流行病、数字监控等诸多困境。本书启迪我们从更广阔的角度审视现代科学，并提醒我们，科学并非无懈可击的绝对真理，而是根植于人类经验的创造物。只有正视科学的“盲点”，重新审视科学与经验的关系，技术与文明才有可能在新的千年中蓬勃发展。', '3楼C区', 'Save', NULL, NULL, NULL),
	(196, 'Python Crash Course.jpg', 'Python编程', 'Python Crash Course', '埃里克 • 马瑟斯（Eric Matthes）', '美国', '2023-5', '编程', '本书是针对所有层次的 Python 读者而作的 Python 入门书。全书分为两部分：第一部分介绍使用Python 编程所必须了解的基本概念，包括强大的 Python 库和工具，以及列表、字典、if 语句、类、文件和异常、测试代码等内容；第二部分将理论付诸实践，讲解如何开发三个项目，包括简单的 2D 游 戏、利用数据生成交互式的信息图以及创建和定制简单的 Web 应用程序，并帮助读者解决常见编程问题和困惑。第 3 版进行了全面修订：使用了文本编辑器 VS Code，新增了介绍 removeprefix() 方法和removesuffix() 方法的内容，并且在项目中利用了Matplotlib 和 Plotly 的最新特性，等等。本书适合对 Python 感兴趣的所有读者阅读。', '3楼D区', 'Save', NULL, NULL, NULL),
	(197, 'Advanced Programming in the UNIX Environment.jpg', 'UNIX环境高级编程', 'Advanced Programming in the UNIX Environment', 'W.Richard Stevens / Stephen A.Rago', '美国', '2006', '编程', '本书是被誉为UNIX编程“圣经”的Advanced Programming in the UNIX Environment一书的更新版。在本书第1版出版后的十几年中，UNIX行业已经有了巨大的变化，特别是影响UNIX编程接口的有关标准变化很大。本书在保持了前一版风格的基础上，根据最新的标准对内容进行了修订和增补，反映了最新的技术发展。书中除了介绍UNIX文件和目录、标准I/O库、系统数据文件和信息、进程环境、进程控制、进程关系、信号、线程、线程控制、守护进程、各种I/O、进程间通信、网络IPC、伪终端等方面的内容，还在此基础上介绍了多个应用示例，包括如何创建数据库函数库以及如何与网络打印机通信等。此外，还在附录中给出了函数原型和部分习题的答案。本书内容权威，概念清晰，阐述精辟，对于所有层次UNIX程序员都是一本不可或缺的参考书。', '3楼D区', 'Save', NULL, NULL, NULL),
	(198, 'Programming Pearls.jpg', '编程珠玑', 'Programming Pearls', 'Jon Bentley', '美国', '2014-12', '编程', '多年以来，当程序员们推选出最心爱的计算机图书时，《编程珠玑》总是位于前列。正如自然界里珍珠出自细沙对牡蛎的磨砺，计算机科学大师Jon Bentley以其独有的洞察力和创造力，从磨砺程序员的实际问题中凝结出一篇篇不朽的编程“珠玑”，成为世界计算机界名刊《ACM通讯》历史上最受欢迎的专栏，最终结集为两部不朽的计算机科学经典名著，影响和激励着一代又一代程序员和计算机科学工作者。在书中，作者选取许多具有典型意义的复杂编程和算法问题，生动描绘了历史上众大师们在探索解决方案中发生的轶事、走过的弯路和不断精益求精的历程，引导读者像真正的程序员和软件工程师那样富于创新性地思考，并透彻阐述和总结了许多独特而精妙的设计原则、思考和解决问题的方法以及实用程序设计技巧。解决方案的代码均以C/C++语言编写，不仅有趣，而且有很大的实战示范意义。本书是计算机科学方面的经典名著。书的内容围绕程序设计人员面对的一系列实际问题展开。本书的特色是通过一些精心设计的有趣而又颇具指导意义的程序，对实用程序设计技巧及基本设计原则进行了透彻而睿智的描述，为复杂的编程问题提供了清晰而完备的解决思路。本书对各个层次的程序员都具有很高的阅读价值。', '3楼D区', 'Save', NULL, NULL, NULL),
	(199, 'Ambient Programming.jpg', '氛围编程', 'Ambient Programming', '伍斌', '中国', '2025-8', '编程', '本书是展示如何用自然语言通过氛围编程工具搭配大模型生成代码解决真实问题的实用指南。书中提供9个实战项目作为入门讲解和检验实验，帮助读者选择合适的氛围编程工具与大模型组合。全书分5部分：第一部分介绍氛围编程基础理论和指导原则；第二部分通过智能体实现、数据可视化和Excel数据分析这3个应用场景，展示扣子、DeepSeek、Claude、Trae、Cursor、Windsurf和通义这7款主流氛围编程工具与大模型搭配组合的代码生成能力；第三部分演示用Trae实现微信小程序和用bolt等工具快速实现Web应用产品原型；第四部分展示用GitHub Copilot实现完整的前后端分离的Web应用和用Cursor生成自动化测试；第五部分提供不同背景读者的氛围编程攻略、工具和大模型对比，以及实战检验框架。', '3楼D区', 'Save', NULL, NULL, NULL),
	(200, 'The Pragmatic Programmer.jpg', '程序员修炼之道', 'The Pragmatic Programmer', 'Andrew Hunt / David Thomas', '美国', '2005-1', '编程', '《程序员修炼之道》由一系列的独立的部分组成，涵盖的主题从个人责任、职业发展，直到用于使代码保持灵活、并且易于改编和复用的各种架构技术。利用许多富有娱乐性的奇闻轶事、有思想性的例子以及有趣的类比，全面阐释了软件开发的许多不同方面的最佳实践和重大陷阱。无论你是初学者，是有经验的程序员，还是软件项目经理，本书都适合你阅读。', '3楼D区', 'Save', NULL, NULL, NULL),
	(201, 'Introduction to Algorithms.jpg', '算法导论', 'Introduction to Algorithms', 'Thomas H. Cormen / Charles E. Leiserson / Ronald L. Rivest / Clifford Stein', '美国', '2002-5', '算法', '《算法导论》自第一版出版以来，已经成为世界范围内广泛使用的大学教材和专业人员的标准参考手册。这本书全面论述了算法的内容，从一定深度上涵盖了算法的诸多方面，同时其讲授和分析方法又兼顾了各个层次读者的接受能力。各章内容自成体系，可作为独立单元学习。所有算法都用英文和伪码描述，使具备初步编程经验的人也可读懂。全书讲解通俗易懂，且不失深度和数学上的严谨性。第二版增加了新的章节，如算法作用、概率分析与随机算法、线性编程等，几乎对第一版的各个部分都作了大量修订。', '3楼D区', 'Save', NULL, NULL, NULL),
	(202, 'The Master Algorithm.jpg', '终极算法', 'The Master Algorithm', '佩德罗·多明戈斯', '美国', '2017-1-1', '算法', '算法已在多大程度上影响我们的生活？购物网站用算法来为你推荐商品，点评网站用算法来帮你选择餐馆，GPS系统用算法来帮你选择最佳路线，公司用算法来选择求职者……当机器最终学会如何学习时，将会发生什么？不同于传统算法，现在悄然主导我们生活的是“能够学习的机器”，它们通过学习我们琐碎的数据，来执行任务；它们甚至在我们还没提出要求，就能完成我们想做的事。什么是终极算法？机器学习五大学派，每个学派都有自己的主算法，能帮助人们解决特定的问题。而如果整合所有这些算法的优点，就有可能找到一种“终极算法”，该算法可以获得过去、现在和未来的所有知识，这也必将创造新的人类文明。你为什么必须了解终极算法？不论你身处什么行业、做什么工作，了解终极算法都将带给你崭新的科学世界观，预测以后的科技发展，布局未来，占位未来！', '3楼D区', 'Save', NULL, NULL, NULL),
	(203, 'The Nine Algorithms That Will Change the Future.jpg', '改变未来的九大算法', 'The Nine Algorithms That Will Change the Future', '约翰·麦考密克(John MacCormick)', '美国', '2019-2', '算法', '计算机如何精确地传输海量数据，识别语音和笔迹；智能手机、平板电脑如何在几分之一秒内搜索整个页面；身处大数据时代的我们，究竟该如何应对变化莫测的世界。计算机算法的底层建设为经济和产业发展提供了原始动力。在科技互联网时代，使用计算机和科技设备都不可避免地要依赖计算机科学的基础思想，而这些思想都诞生于20世纪。《改变未来的九大算法》是一本科普读物，作者致力于将计算机科学的复杂思想为大众做深入浅出的解读。此书通过简明的语言和生动的例证，阐述了计算机王国的核心算法：搜索引擎、PageRank、公钥加密、纠错码、图形识别、数据压缩、数据库、数字签名等。在解释这些算法的同时，作者也向我们展示了充满科学原创精神的计算机世界：每一种算法的提出不但拓展了虚拟世界的领域，它同时也是人类智慧的彰显，可以被广泛运用于众多领域，以推动商业和社会文明的发展。', '3楼D区', 'Save', NULL, NULL, NULL),
	(204, 'The Way of Algorithms.jpg', '算法之道', 'The Way of Algorithms', '邹恒明', '中国', '2012-4-20', '算法', '本书追求的目标是算法背后的逻辑，是一本启示书，而不是一本包罗万象的算法大全。因此，本书甄选了那些最能展现算法思想、战略和精华，并能够有效训练算法思维的内容。本书将算法的讨论分为五篇：算法基础篇、算法设计篇、算法分析篇、经典算法篇、难解与无解篇。每篇分别讨论算法的一个方面：基础、设计、分析、经典和难解问题。第2版还对进程调度问题、跳转表问题、概率分析应用、遗传算法等方面进行了论述。本书既可以作为大学本科或研究生的算法教材或参考书，也可以作为对算法有兴趣的读者提升认知深度的读物。', '3楼D区', 'Save', NULL, NULL, NULL),
	(205, 'Algorithms Everywhere.jpg', '无处不在的算法', 'Algorithms Everywhere', '贝特霍尔德·弗金 / 赫尔穆特·阿尔特', '德国', '2018-1-1', '算法', '本书以简单易懂的写作风格，通过解决现实世界常见的问题来介绍各种算法技术，揭示了算法的设计与分析思想。全书共有41章，分为四大部分，图文并茂，把各种算法的核心思想讲得浅显易懂。本书可作为高等院校算法相关课程的本科生教材，也可作为研究人员、专业技术人员的常备参考书。', '3楼D区', 'Save', NULL, NULL, NULL),
	(206, 'The Way of Communication.jpg', '通信之道', 'The Way of Communication', '杨学志', '中国', '2016-2', '通信', '《通信之道》按照读者的思维顺序讲述了从微积分到 5G 所涉及的基础知识和关键技术，全书共20章，具有以下特点：（1）跨度极大，内容翔实：涉及数学、信号处理、通信原理、通信前沿技术等多个学科领域，知识密度极高，并且是最精华的部分。（2）降低难度，提升高度：叙述符合读者的思维发展规律，并逐级提高，前后呼应，语言风趣幽默，节奏平稳；作者站高望远，直击本质，学术境界超越经典。（3）启发互动，培养创新：在多个环节上对读者提出挑战，启发读者思考，并给出作者的思考过程，培养读者的创新思维。《通信之道》可作为通信和信号处理相关专业的本科生及研究生的教辅书，也可作为从业技术人员的参考资料。', '3楼D区', 'Save', NULL, NULL, NULL),
	(207, 'Introduction to the Internet of Things.jpg', '物联网导论', 'Introduction to the Internet of Things', '刘云浩', '中国', '2017-1-1', '通信', '物联网是一个基于互联网、传统电信网等信息承载体，让所有能够被独立寻址的普通物理对象实现互联互通的网络。它具有普通对象设备化、自治终端互联化和普适服务智能化三个重要特征。《物联网导论（第3版）/物联网工程专业系列教材》从物联网的感知识别层、网络构建层、管理服务层和综合应用层这四层分别进行阐述，深入浅出地为读者拨开萦绕于物联网这个概念的重重迷雾，引领求知者渐渐步入物联网世界，帮助探索者把握第三次IT科技浪潮的方向。《物联网导论（第3版）/物联网工程专业系列教材》适合高等院校物联网工程专业作为专业教材使用，也适合其他各专业作为选修课教材使用，还适合对物联网感兴趣的各类读者参考阅读。', '3楼D区', 'Save', NULL, NULL, NULL),
	(208, 'Communication Principles Explained Clearly and Simply.jpg', '深入浅出通信原理', 'Communication Principles Explained Clearly and Simply', '陈爱军', '中国', '2017-12-22', '通信', '暂无', '3楼D区', 'Save', NULL, NULL, NULL),
	(209, 'Principles of Communication.jpg', '通信原理', 'Principles of Communication', '周炯槃/庞沁华等', '中国', '2005-11', '通信', '《通信原理》(合订本)系统、深入地介绍了通信系统及通信网的基本原理及基本分析方法，是通信及信息专业的专业基础教材。全书共十一章，内容包括通信系统交通网的基本概念、确定信号及随机过程、模拟通信系统、数字基带传输、数字频带传输、信源和信源编码、信道和信道容量、信道差错控制编码、正交编码与伪随机序列及其应用、通信网的基本原理。', '3楼D区', 'Save', NULL, NULL, NULL),
	(210, 'Digital communication.jpg', '数字通信', 'Digital communication', 'John G.Proakis / John Proakis', '美国', '2003-1-1', '通信', '《数字通信》(第4版)是数字通信领域的一本经典教材,通过对概率论及随机过程的复习,详细介绍了数字和模拟信源编码、数字调制信号和窄带信号与系统的特征、加性高斯白噪声中数字通信的调制和最佳调制与检测方法、基于最大似然准则的载波相位估计和定时同步的方法、不同信道模型的信道容量及随机编码、带限信道的信号设计、受到符号间干扰恶化信号的解调与检测问题、自适应信道均衡、多信道与多载波调制、扩展频谱信号和系统、衰落信道上的数字通信。', '3楼D区', 'Save', NULL, NULL, NULL),
	(211, 'Shout.jpg', '呐喊(云桥连借阅)(未到)', 'Shout', '鲁迅', '中国', '1973-3', '散文', '《呐喊》收录作者1918年至1922年所作小说十四篇。1923年8月由北京新潮社出版，原收十五篇，列为该社《文艺丛书》之一。1924年5月第三次印刷时起，改由北京北新书局出版，列为作者所编的《乌合丛书》之一。1930年1 月第十三次印刷时，由作者抽去其中的《不周山》一篇(后改名为《补天》，收入《故事新编》)。作者生前共印行二十二版次。', '云桥连', 'Lend_CBC', '1', '2026-04-28', '2026-06-12'),
	(212, 'Dreaming of being a wolf king.jpg', '狼王梦(云桥连借阅)(已到)', 'Dreaming of being a wolf king', '沈石溪', '中国', '2009-10', '小说', '《狼王梦》内容简介：绝境分娩、培养黑仔、魂断捕兽夹、重塑王者品性、寄望后代、血洒碧空、被淘汰的警犬、阴差阳错进了马戏团、扮演大灰狼、鲜花和掌声不属于它、遭哈巴狗暗算、恶狼?好狗?、野外遭遇云豹等等。', '云桥连', 'Lend_CBC', '5', '2026-04-28', '2026-05-09'),
	(213, '202605071750432078418.jpg', '三国演义', 'Romance of the Three Kingdoms', '罗贯中', '明朝', '1998-05', '小说', '《三国演义》又名《三国志演义》、《三国志通俗演义》，是我国小说史上最著名最杰出的长篇章回体历史小说。 《三国演义》的作者是元末明初人罗贯中，由毛纶，毛宗岗父子批改。在其成书前，“三国故事”已经历了数百年的历史发展过程。在唐代，三国故事已广为流传，连儿童都很熟悉。随着市民文艺的发展，宋代的“说话”艺人，已有专门说三国故事的，当时称为“说三分”。元代出现的《三国志平话》，实际上是从说书人使用的本子，虽较简略粗糙，但已初肯《三国演义》的规模。罗贯中在群众传说和民间艺人创作的基础上，又依据陈寿《三国志》及裴松之注中所征引的资料（还包括《世说新语》及注中的资料），经过巨大的创作劳动，写在了规模宏伟的巨著——《三国志通俗演义》全书24卷，240回。后来经过毛纶，毛宗岗父子批改，形成我们现在所见的《三国演义》120回版。', '1楼A区', 'Save', NULL, NULL, NULL),
	(214, 'A Madman\'s Diary.jpg', '狂人日记(云桥连借阅)(已到)', 'A Madman\'s Diary', '鲁迅', '中国', '2006-3', '小说', '《狂人日记》是鲁迅1918年发表的第一篇白话短篇小说，当时正值“五四”运动的前夜。由于辛亥革命的半途而废，特别是帝国主义侵略的加剧，使社会各种矛盾更加复杂尖锐。鲁迅以他锐敏的思想和犀利的笔触，对封建制度及其上层建筑表现了彻底的反抗。《狂人日记》是中国现代文学史上第一篇 真正的现代白话小说。令人惊异的是，这部中国现代小说史上具有开山意义的作品，已经显示出极其成熟的特色，使后来的许多研究者为之倾倒，究其原因，除了鲁迅深厚的文学素养外，我们也无法不叹服于先生的天才。', '云桥连', 'Lend_CBC', '10', '2026-05-07', '2026-05-11'),
	(215, '202610291548511296041.jpg', '拥抱的姿势', 'The Position of Spoons', '德博拉·利维', '英国', '2026-10', '心理', '      在《拥抱的姿势》中，利维邀请读者进入她的私人世界，重读玛格丽特·杜拉斯、西格蒙德·弗洛伊德、薇奥莱特·勒杜克和罗兰·巴特，探讨技术、美食、流行病、郊区生活，顺便分享一段关于勺子、邻居和尼采的趣闻。她的文字令人愉悦，每一页都是一幅美丽而蕴含思辨的自我写照，让我们对她古怪而博学的珍爱之物有了更深入的了解。\r\n      关于鞋类她写道：“我一直很清楚，那些只穿鞋不穿袜子的人注定会成为我的朋友和爱人。”关于公共花园：“一个城市的花园广场缓和了周围城市的节奏，在喧嚣之前保持一种思想。”关于伊丽莎白·哈德威克：“她明白什么是文学的关键所在。”关于婚姻的终结：“不需要外星人来告诉我们，当爱情消亡时，我们必须找到另一种生活方式。”', '2楼D区', 'Save', NULL, NULL, NULL);
INSERT INTO `book_branch` (`ID`, `Cover`, `Name`, `Name_EN`, `Author`, `Nationality`, `Publication_Date`, `Type`, `Introduction`, `Place`, `Lend_Status`, `Lend_ID`, `Lend_Time`, `Return_Time`) VALUES
	(1, 'Dawn Blossoms Plucked at Dusk.jpg', '朝花夕拾', 'Dawn Blossoms Plucked at Dusk', '鲁迅', '中国', '1973-4', '散文', '本书收作者1926年所作回忆散文十篇。1928年9月由北平未名社初版，列为作者所编的《未名新集》之一。1932年8月改由上海北新书局出版。作者生前共印行七版次。', '1楼A区', 'Save', NULL, NULL, NULL),
	(2, 'Wild Grass.jpg', '野草', 'Wild Grass', '鲁迅', '中国', '1973-3', '散文', '本书所收散文诗23篇〔包括一首打油诗和一出诗剧〕，最初都曾陆续发表于1924年12月至1926年1月的《语丝》周刊上，《题辞》最初也曾发表于1927年7月2日出版的《语丝》第138期，发表时署名均为鲁迅。本书于于年1927年4月由作者亲自编定，同年7月由上海北新书局初版印行列为作者所编的《乌合丛书》之一。此后印行的版本，除个别字和标点有所不同外，各篇文字大都和初版相同。《题辞》在本书最初的几次印刷都曾印入；后来被国民党政府书报检查机关抽去〔鲁迅在1935年11月23日致邱遇信和1936年2月19日致夏传经信中，均提及此事〕，至1941年上海鲁迅全集出版社出版《鲁迅三十年集》时才重新收入。《野草》的封面画系孙福熙所作，初版封面题字署“鲁迅先生”，后按鲁迅意思改为“鲁迅著”，鲁迅在1927年12月9日夜致章廷谦信中曾提及此事。', '1楼A区', 'Save', NULL, NULL, NULL),
	(3, 'Shout.jpg', '呐喊', 'Shout', '鲁迅', '中国', '1973-3', '散文', '《呐喊》收录作者1918年至1922年所作小说十四篇。1923年8月由北京新潮社出版，原收十五篇，列为该社《文艺丛书》之一。1924年5月第三次印刷时起，改由北京北新书局出版，列为作者所编的《乌合丛书》之一。1930年1 月第十三次印刷时，由作者抽去其中的《不周山》一篇(后改名为《补天》，收入《故事新编》)。作者生前共印行二十二版次。', '1楼A区', 'Lend_CBC', '1', '2026-04-28', '2026-06-12'),
	(4, 'Hesitation.jpg', '彷徨', 'Hesitation', '鲁迅', '中国', '1973-3', '散文', '《彷徨》收入鲁迅1924年至1925年所作的小说，首篇《祝福》写于1924年2月16日，末篇《离婚》写于1925年11月6日，实际的时间跨度是一年半多，1926年由北京北新书局出版，列为作者所编的《乌合丛书》之一。此后印行的版本都与初版同。书的扉页，有作者的题记：朝发轫于苍梧兮，夕余至乎县圃；欲少留此灵琐兮，日忽忽将其暮。吾令羲和弭节兮，望崦嵫而勿迫；路漫漫其修远兮，吾将上下而求索。《彷徨》鲁迅先生写作于“五·四”运动后新文化阵营分化的时期。原来参加过新文化运动的人，“有的退隐，有的高升，有的前进”，鲁迅当时象布不成阵的游勇那样“孤独”和 “彷徨”。《彷徨》表现了他在这一时期在革命征途上探索的心情。', '1楼A区', 'Save', NULL, NULL, NULL),
	(5, 'A Madman\'s Diary.jpg', '狂人日记', 'A Madman\'s Diary', '鲁迅', '中国', '2006-3', '小说', '《狂人日记》是鲁迅1918年发表的第一篇白话短篇小说，当时正值“五四”运动的前夜。由于辛亥革命的半途而废，特别是帝国主义侵略的加剧，使社会各种矛盾更加复杂尖锐。鲁迅以他锐敏的思想和犀利的笔触，对封建制度及其上层建筑表现了彻底的反抗。《狂人日记》是中国现代文学史上第一篇 真正的现代白话小说。令人惊异的是，这部中国现代小说史上具有开山意义的作品，已经显示出极其成熟的特色，使后来的许多研究者为之倾倒，究其原因，除了鲁迅深厚的文学素养外，我们也无法不叹服于先生的天才。', '1楼A区', 'Lend_CBC', '10', '2026-05-07', '2026-05-11'),
	(6, 'Dreaming of being a wolf king.jpg', '狼王梦', 'Dreaming of being a wolf king', '沈石溪', '中国', '2009-10', '小说', '《狼王梦》内容简介：绝境分娩、培养黑仔、魂断捕兽夹、重塑王者品性、寄望后代、血洒碧空、被淘汰的警犬、阴差阳错进了马戏团、扮演大灰狼、鲜花和掌声不属于它、遭哈巴狗暗算、恶狼?好狗?、野外遭遇云豹等等。', '1楼B区', 'Lend_CBC', '5', '2026-04-28', '2026-05-09');
